-- TOC entry 3052 (class 1255 OID 1038038)
-- Name: ft_eliminar_concept(); Type: FUNCTION; Schema: mod_personaproyecto; Owner: zeolides
--

CREATE FUNCTION ft_eliminar_concept() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
       ancho BIGINT;
BEGIN
     SET search_path = mod_personaproyecto;
     ancho := OLD.rgt - OLD.lft + 1;
     UPDATE nom_concepto SET rgt = rgt - ancho WHERE rgt > OLD.rgt;
     UPDATE nom_concepto SET lft = lft - ancho WHERE lft > OLD.rgt;
     RETURN OLD;
     EXCEPTION WHEN foreign_key_violation THEN
     RETURN OLD;
END;
$$;


ALTER FUNCTION mod_personaproyecto.ft_eliminar_concept() OWNER TO zeolides;

--
-- TOC entry 3053 (class 1255 OID 1038039)
-- Name: ft_eliminar_personaproyecto(); Type: FUNCTION; Schema: mod_personaproyecto; Owner: zeolides
--

CREATE FUNCTION ft_eliminar_personaproyecto() RETURNS trigger
    LANGUAGE plpgsql
    AS $$DECLARE
       ancho BIGINT;
BEGIN
     SET search_path = mod_personaproyecto;
     ancho := OLD.der - OLD.izq + 1;                       
     UPDATE dat_proyectoconcepto SET der = der - ancho WHERE der > OLD.der;
     UPDATE dat_proyectoconcepto SET izq = izq - ancho WHERE izq > OLD.der;
     RETURN OLD;
     EXCEPTION WHEN foreign_key_violation THEN
         RETURN OLD;
END;$$;


ALTER FUNCTION mod_personaproyecto.ft_eliminar_personaproyecto() OWNER TO zeolides;

--
-- TOC entry 3054 (class 1255 OID 1038040)
-- Name: ft_insertar_concepto(); Type: FUNCTION; Schema: mod_personaproyecto; Owner: zeolides
--

CREATE FUNCTION ft_insertar_concepto() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
        padre_rec mod_personaproyecto.nom_concepto;
	derecha bigint;
	temporalrgt numeric;
BEGIN
	SET search_path = mod_personaproyecto;
	IF NEW.lft is null THEN 
		IF NEW.idconcepto != NEW.idpadre THEN
			SELECT * INTO  padre_rec FROM nom_concepto WHERE idconcepto = NEW.idpadre;
			IF (padre_rec IS NULL ) THEN
				--idconcepto = 1 no existe
				SELECT * INTO padre_rec FROM nom_concepto WHERE tipo = 0;
				NEW.lft := padre_rec.rgt;
				NEW.rgt := padre_rec.rgt + 1;
				temporalrgt := padre_rec.rgt + 1;
				UPDATE nom_concepto SET rgt = rgt + 2 WHERE idconcepto = NEW.idpadre;
				UPDATE nom_concepto SET lft = lft + 2 WHERE lft >= temporalrgt;
				UPDATE nom_concepto SET rgt = rgt + 2 WHERE rgt >= temporalrgt and idconcepto <> NEW.idpadre; 
			ELSE
				NEW.lft := padre_rec.rgt;
				NEW.rgt := padre_rec.rgt + 1;
				temporalrgt := padre_rec.rgt + 1;
				UPDATE nom_concepto SET rgt = rgt + 2 WHERE idconcepto = NEW.idpadre;
				UPDATE nom_concepto SET lft = lft + 2 WHERE lft >= temporalrgt;
				UPDATE nom_concepto SET rgt = rgt + 2 WHERE rgt >= temporalrgt and idconcepto <> NEW.idpadre;
			END IF;
		ELSE
			derecha :=  MAX(rgt) FROM nom_concepto WHERE idconcepto = idpadre;
			IF derecha is not null THEN
				NEW.lft := derecha + 1;
				NEW.rgt := derecha + 2;
			ELSE
				NEW.lft := 1;
				NEW.rgt := 2;
			END IF;
		END IF;
	END IF;
	RETURN NEW;
END;$$;


ALTER FUNCTION mod_personaproyecto.ft_insertar_concepto() OWNER TO zeolides;

--
-- TOC entry 3055 (class 1255 OID 1038041)
-- Name: ft_insertar_nodo(); Type: FUNCTION; Schema: mod_personaproyecto; Owner: zeolides
--

CREATE FUNCTION ft_insertar_nodo() RETURNS trigger
    LANGUAGE plpgsql
    AS $$DECLARE
        padre_rec mod_personaproyecto.dat_proyectoconcepto;
	derecha bigint;
        temporalder numeric;
BEGIN
    SET search_path = mod_personaproyecto;
    IF  (NEW.idconcepto is null) AND (NEW.idpadre is null)THEN
    -- Es una Raiz agrupadora de conceptos y/o agrupadores.
	NEW.idpadre:= NEW.idproyectoconcepto;
    END IF;
    IF  NEW.izq is null THEN 
	IF NEW.idproyectoconcepto != NEW.idpadre THEN
		SELECT * INTO  padre_rec FROM dat_proyectoconcepto WHERE idproyectoconcepto = NEW.idpadre;
		NEW.izq := padre_rec.der;
		NEW.der := padre_rec.der + 1;			
		temporalder := padre_rec.der + 1;  
		UPDATE dat_proyectoconcepto SET der = der + 2 WHERE der = padre_rec.der; 
		UPDATE dat_proyectoconcepto SET izq = izq + 2 WHERE izq >= temporalder;
		UPDATE dat_proyectoconcepto SET der = der + 2 WHERE der >= padre_rec.der and (idproyectoconcepto <> padre_rec.idproyectoconcepto) ;
	ELSE
		derecha :=  MAX(der) FROM dat_proyectoconcepto WHERE idproyectoconcepto = idpadre;
		IF derecha is not null THEN
			NEW.izq := derecha + 1;
			NEW.der := derecha + 2;
		ELSE
			NEW.izq := 1;
			NEW.der := 2;
		END IF;
	END IF;
END IF;
RETURN NEW;
END;$$;


ALTER FUNCTION mod_personaproyecto.ft_insertar_nodo() OWNER TO zeolides;

--
-- TOC entry 3056 (class 1255 OID 1038042)
-- Name: ft_insertar_personaproyecto(); Type: FUNCTION; Schema: mod_personaproyecto; Owner: zeolides
--

CREATE FUNCTION ft_insertar_personaproyecto() RETURNS trigger
    LANGUAGE plpgsql
    AS $$DECLARE
        ult_orden numeric;
	cant_hijos_r numeric;
	root boolean := false;	
BEGIN
    SET search_path = mod_personaproyecto;
    IF (NEW.orden is null) THEN
	IF  (NEW.idpadre is null) THEN
					--Nuevo árbol.
		NEW.idpadre:= NEW.idproyectoconcepto;
		ult_orden:= MAX(orden) FROM dat_proyectoconcepto 
				       WHERE idproyectoconcepto = idpadre;
		IF (ult_orden is not null) THEN
			NEW.orden:= ult_orden + 1;
		ELSE
			NEW.orden:= 1;
		END IF;
	ELSE
				-- NEW.idpadre no es nulo, ver si se inserta como hijo de un root
					-- si el nodo con idproyectoconcepto = NEW.idpadre 
		root:= true FROM dat_proyectoconcepto 
			    WHERE NEW.idpadre = idpadre AND idproyectoconcepto = idpadre;
		IF (root) THEN
			cant_hijos_r:= COUNT(*) - 1 FROM dat_proyectoconcepto
						    WHERE NEW.idpadre = idpadre;
			IF (cant_hijos_r = 0) THEN
				NEW.orden:= 1;
			ELSE
				ult_orden:= MAX(orden) FROM dat_proyectoconcepto
						       WHERE NEW.idpadre = idpadre AND idproyectoconcepto <> NEW.idpadre;	
				NEW.orden:= ult_orden + 1;
			END IF;
		ELSE
				--Se inserta como hijo de un agrupador contenido en el árbol.
			cant_hijos_r:= COUNT(*) FROM dat_proyectoconcepto
						WHERE NEW.idpadre = idpadre;
			IF (cant_hijos_r = 0) THEN
				NEW.orden:= 1;
			ELSE
				ult_orden:= MAX(orden) FROM dat_proyectoconcepto
						       WHERE NEW.idpadre = idpadre AND idproyectoconcepto <> NEW.idpadre;	
				NEW.orden:= ult_orden + 1;
			END IF;	
		END IF;
	END IF;
    END IF;
RETURN NEW;
END;$$;


ALTER FUNCTION mod_personaproyecto.ft_insertar_personaproyecto() OWNER TO zeolides;

