INSERT INTO dat_proyectoconcepto (idproyectoconcepto, denominacion, idpadre, idproyecto, descripcion, tipo, propiedades, iconcls, orden, codigo, cmpempleado, getdata) VALUES (1083, 'Categorías', 1080, 'basetecnologica', NULL, 3, '{"xtype":"tree_combobox","allowBlank":"false","disabled":"false","editable":"true","hidden":"false","readOnly":"false","resizable":"false","anchocolumna":"","anchor":"98%","emptyText":"Seleccione...","fieldLabel":"Categoría","name":"denominacion"}', 'icondistra-tag_blue', 1, '{"clickNode":"function (node, e) {\n        if (node.isLeaf()) {\n            var text = node.text;\n            this.setValue(text);\n            this.fireEvent(''selectNode'', node);\n            this.collapse();\n            Ext.getCmp(''1251'' + this.idpadre).setValue(node.attributes.idcategoriapersona);\n        }\n    }","reset":"","setValue":"","treeConfig":"{loader: {\n            dataUrl: ''/pvd/persona/index.php/nomcategoriapersona/getCategorias''\n        },\n        border: false,\n        autoScroll: true,\n        rootVisible: false,\n        root: {\n            text: ''Categorías de persona'',\n            animate: false,\n            draggable: false,\n            expanded: false\n        }}","listeners":{"expand":""}}', '{"module":"persona","component":"treecombobox"}', NULL);
