INSERT INTO dat_proyectoconcepto (idproyectoconcepto, denominacion, idpadre, idproyecto, descripcion, tipo, propiedades, iconcls, orden, codigo, cmpempleado, getdata) VALUES (777, 'Grados militares', 57, 'basetecnologica', NULL, 1, '{"xtype":"gest_panel","animCollapse":"false","autoHeight":"false","border":"true","collapsed":"false","collapsible":"false","disabled":"false","frame":"false","hidden":"false","split":"false","elementsByRow":3,"height":"","anchocolumna":"","anchor":"","cmargins":"","collapseMode":"","html":"","layout":"","margins":"","region":"","title":"Grados militares","width":"auto"}', 'tag', 10, '{"columns":"[\n  {header: \"Imagen\", width: 50, sortable: true, \n   dataIndex: \"icongrado\",\n   renderer: function (value, meta, record) {\n     return ''<center><img ext:qtip=\"<b>'' + record.get(''denomgrado'') + ''</b>\" style=\"height: 16px;cursor: pointer\" src=\"'' + value + ''\" /></center>''     \n   }\n  },\n  {header: \"Grado militar\", width: 200, sortable: true, dataIndex: \"denomgrado\"},\n  {header: \"No. Orden\", width: 50, sortable: true, dataIndex: \"numorden\"},\n  {header: \"De quién\", width: 150, sortable: true, dataIndex: \"dequien\"},\n  {header: \"Desde\", width: 100, sortable: true, dataIndex: \"fdesde\"},\n  {header: \"Hasta\", width: 100, sortable: true, dataIndex: \"fhasta\"},\n  {header: \"Hist&oacute;rico\", hidden: true, sortable: true, dataIndex: \"historico\", renderer: function (v)\n   {\n     return (v == 1) ? ''Actual'' : ''Hist&oacute;rico'';\n   }}\n]","addBotones":"","adicionarHandler":"","aplicarHandler":"function(){\n  var values = this.fpFormulario.getForm().getValues();\n  //Obteniendo la denominacion de grado seleccionado\n  var cbGrado = Ext.getCmp(\"780\" + this.idpadre);\n  values.denomgrado = cbGrado.getRawValue();\n  \n  //Obteniendo la imagen del grado seleccionado\n  values.icongrado = cbGrado.findRecord(cbGrado.valueField, cbGrado.getValue()).get(''icono'');\n  \n  values.historico = isActual(values.fdesde, values.fhasta);\n\n  var store = this.gpGrid.getStore();\n  var index = -1;\n  if (Ext.isEmpty(values.idgradomilitar)) {//Si es vacio es porke estoy adicionando\n    values.idgradomilitar = Ext.id();\n    values.add = true;\n    if (values.historico == 1) {\n      Ext.each(store.getRange(), function (rec)\n      {\n      \tif (rec.get(''historico'') === 1 && rec.get(''idgrado'') == values.idgrado) {\n           index = ''grado'';\n           return false;\n        }\n        if(rec.get(''historico'') === 1){\n          index = ''actual'';\n          return false;\n        }\n      });\n    }\n    switch (index) {\n      case ''actual'':\n        Ext.Notification.show({\n          title: ''Aviso'',\n          msg: ''La persona ya esta nombrada en grado.'',\n          icon: ''warning''\n        });\n        break;\n      case ''grado'':\n        Ext.Notification.show({\n          title: ''Error'',\n          //msg: ''La persona ya est&aacute nombrada en el grado de: ''+values.denomgrado+''.'',\n          msg: ''El grado militar que quiere adicionar ya existe.'',\n          icon: ''error''\n        });\n        break;\n      default :\n        try {\n          store.add(new Ext.data.Record(values));\n          this.cleanForm();\n        } catch (error) {\n          Ext.Notification.show({\n            title: ''Error'',\n            msg: ''Ha ocurrido un error mientras se guardaba, contacte el administrador.'',\n            icon: ''error''\n          });\n        }\n        break;\n    }\n  }\n  store.clearGrouping();\n  store.groupBy(''historico'', true);\n\n  function isActual(fi, ff)\n  {\n    if (!Ext.isEmpty(ff)) {//Si la fecha fin es ditinto de vacio\n      var date = new Date();\n      date = date.format(''d/m/Y'');\n      var arrfi = fi.split(''/'');\n      var arrff = ff.split(''/'');\n      var arrfa = date.split(''/'');\n      var fi = arrfi[2] + arrfi[1] + arrfi[0];\n      var ff = arrff[2] + arrff[1] + arrff[0];\n      var fa = arrfa[2] + arrfa[1] + arrfa[0];\n      fi = parseInt(fi);\n      ff = parseInt(ff);\n      fa = parseInt(fa);\n      return (fi <= fa && fa <= ff) ? 1 : 0;\n      //1->Actual  0->Historico\n    }\n    return 1;\n  }\n}","eliminarHandler":"function(){\n  var records = this.gpGrid.getSelectionModel().getSelections();\n   var ask = (records.length == 1) ? ''¿Está seguro que quiere eliminar el grado seleccionado?'' : \n    ''¿Está seguro que quiere eliminar los grados seleccionados?'';\n\tmostrarMensaje(2, ask, function (btn)\n                   {\n                     if (btn == ''ok'') {\n\n                       var records = this.gpGrid.getSelectionModel().getSelections();\n                       Ext.each(records, function (rec)\n                                {\n                                  if (!rec.data.add) {\n                                    this.arrDel.push(rec.get(''idgradomilitar''));\n                                  }\n                                  this.gpGrid.getStore().remove(rec);\n                                }, this);\n                       this.gpGrid.getView().refresh();\n                     }\n                   }.createDelegate(this));\n}","gSecurity":"","getLanguaje":"function(idioma){\n  var lang={};\n if(idioma===''es''){\n     lang ={\n        ttBtnAdd:\"Adicionar grado militar\",\n        ttBtnMod:\"Modificar grado militar\",\n        ttBtnDel:\"Eliminar grado militar\",\n        ttBtnSave:\"Guardar datos y cerrar formulario\",\n        ttBtnApl:\"Guardar datos y limpiar los campos\",\n        ttBtnCancel:\"Cerrar formulario sin guardar los datos\"      \n\n      }  \t\n    }else{\n     lang = {\n        \n      }  \t\n      \n    }\n  return lang;\n\t\n}","guardarHandler":"function(){\n  var values = this.fpFormulario.getForm().getValues();\n  //Obteniendo la denominacion de grado seleccionado\n  var cbGrado = Ext.getCmp(\"780\" + this.idpadre);\n  values.denomgrado = cbGrado.getRawValue();\n  \n  //Obteniendo la imagen del grado seleccionado\n  values.icongrado = cbGrado.findRecord(cbGrado.valueField, cbGrado.getValue()).get(''icono'');\n\n  values.historico = isActual(values.fdesde, values.fhasta);\n\n  var store = this.gpGrid.getStore();\n  var index = -1;\n  if (Ext.isEmpty(values.idgradomilitar)) {//Si es vacio es porke estoy adicionando\n    values.idgradomilitar = Ext.id();\n    values.add = true;\n    if (values.historico == 1) {\n      Ext.each(store.getRange(), function (rec)\n      {\n      \tif (rec.get(''historico'') === 1 && rec.get(''idgrado'') == values.idgrado) {\n           index = ''grado'';\n           return false;\n        }\n        if(rec.get(''historico'') === 1){\n          index = ''actual'';\n          return false;\n        }\n      });\n    }\n    switch (index) {\n      case ''actual'':\n        Ext.Notification.show({\n          title: ''Aviso'',\n          msg: ''La persona ya esta nombrada en grado.'',\n          icon: ''warning''\n        });\n        break;\n      case ''grado'':\n        Ext.Notification.show({\n          title: ''Error'',\n          msg: ''El grado militar que quiere adicionar ya existe.'',\n          icon: ''error''\n        });\n        break;\n      default :\n        try {\n          store.add(new Ext.data.Record(values));\n          this.cancelarHandler();\n        } catch (error) {\n          Ext.Notification.show({\n            title: ''Error'',\n            msg: ''Ha ocurrido un error mientras se guardaba, contacte el administrador.'',\n            icon: ''error''\n          });\n        }\n        break;\n    }\n  } else {\n    var record;\n    //Iteracion para validar la modificacion y obtener el record a modificar\n    Ext.each(store.getRange(), function (rec)\n             {\n               if (rec.get(''idgradomilitar'') === values.idgradomilitar) {\n                 \trecord = rec; //Obtengo el record que se va a modificar\n               } else if (values.historico === 1 && rec.get(''historico'') == 1) {\n                   index = ''actual'';\n                   return false;\n                   if (rec.get(''idgrado'') == values.idgrado) {\n                   index = ''grado'';\n                   return false;\n              }\n               }              \n             });\n    switch (index) {\n      case ''actual'':\n        Ext.Notification.show({\n          title: ''Aviso'',\n          msg: ''La persona ya tiene una situaci&oacute;n actual.'',\n          icon: ''warning''\n        });\n        break;\n        case ''grado'':\n          Ext.Notification.show({\n            title: ''Error'',\n            msg: ''El grado militar ya existe.'',\n            icon: ''error''\n          });\n          break;\n      default :\n        try {\n          for (var p in values) {\n            if (values[p] != record.get(p)) {\n              record.set(p, values[p]);\n            }\n          }\n          this.cancelarHandler();\n        } catch (error) {\n          Ext.Notification.show({\n            title: ''Error'',\n            msg: ''Ha ocurrido un error mientras se modificaba, contacte el administrador.'',\n            icon: ''error''\n          });\n        }\n        break;\n    }\n  }\n  store.clearGrouping();\n  store.groupBy(''historico'', true);\n\n  function isActual(fi, ff)\n  {\n    if (!Ext.isEmpty(ff)) {//Si la fecha fin es ditinto de vacio\n      var date = new Date();\n      date = date.format(''d/m/Y'');\n      var arrfi = fi.split(''/'');\n      var arrff = ff.split(''/'');\n      var arrfa = date.split(''/'');\n      var fi = arrfi[2] + arrfi[1] + arrfi[0];\n      var ff = arrff[2] + arrff[1] + arrff[0];\n      var fa = arrfa[2] + arrfa[1] + arrfa[0];\n      fi = parseInt(fi);\n      ff = parseInt(ff);\n      fa = parseInt(fa);\n      return (fi <= fa && fa <= ff) ? 1 : 0;\n      //1->Actual  0->Historico\n    }\n    return 1;\n  }\n}","helpHandler":"","isDirty":"","loadFn":"function(idpersona){\n  this.arrAdd = [];\n  this.arrMod = [];\n  this.arrDel = [];\n  this.loadGridStore({idpersona: idpersona});\n}","modificarHandler":"","saveFn":"function(btnPress){\n  var self = this;\n  var store = this.gpGrid.getStore();\n  this.arrAdd = [];\n  this.arrMod = [];\n  var pass = false;\n  Ext.each(store.getRange(), function (rec)\n           {\n             if (rec.data.add) {//Si es un record que se adiciono nuevo\n               this.arrAdd.push(rec.data);\n             } else {\n               if (!Ext.isEmpty(rec.modified)) {//Si el record fue modificado\n                 this.arrMod.push(rec.data);\n               }\n             }             \n               pass = true;\n           }, this);\n  if (!pass && this.obligatorio) {\n    Ext.Notification.show({\n      title: ''Advertencia'',\n      msg: ''La persona debe estar nombrado en cargo'',\n      icon: ''warning''\n    });\n    return false;\n  }\n  var url = '''';\n  if (this.arrMod.length > 0 || (this.arrDel.length > 0 && this.arrAdd.length > 0)) {\n    url = ''modGradosMilitares'';\n  } else\n    if (this.arrDel.length > 0) {\n      url = ''delGradosMilitares'';\n    } else {\n      url = ''addGradosMilitares'';\n    }\n  if (this.arrAdd.length > 0 || this.arrMod.length > 0 || this.arrDel.length > 0) {\n    Ext.sendAjax.request({\n      url: url,\n      params: {\n        arrAdd: Ext.encode(self.arrAdd),\n        arrMod: Ext.encode(self.arrMod),\n        arrDel: Ext.encode(self.arrDel)\n      },\n      success: function (response, opt, notification)\n      {\n        var dataResponse = Ext.decode(response.responseText);\n        if (dataResponse.success) {\n          if (btnPress === ''APLICAR'') { //Si el boton que ejecuto la funcion fue aplicar\n            this.loadFn(Ext.getCmp(this.idpadre).persona.idpersona);\n          }\n          this.arrAdd = [];\n          this.arrMod = [];\n          this.arrDel = [];\n          var msg = '''';\n          switch (url) {\n            case ''modGradosMilitares'':\n              msg = ''El(Los) grado(s) militar(es) ha(n) sido modificado(s) satisfactoriamente.'';\n              break;\n            case ''delGradosMilitares'':\n              msg = ''El(Los) grado(s) militar(es) ha(n) sido eliminado(s) satisfactoriamente.'';\n              break;\n            case ''addGradosMilitares'':\n              msg = ''El(Los) grado(s) militar(es) ha(n) sido adicionado(s) satisfactoriamente.'';\n              break\n          }\n          notification({\n            title: ''Informaci&oacute;n'',\n            msg: msg,\n            icon: ''ok''\n          });\n        } else {\n          switch (dataResponse.codigo) {\n            default :\n              notification({\n                title: ''Error'',\n                msg: ''Ha ocurrido un error durante la transaccion.'',\n                icon: ''error''\n              });\n              break;\n          }\n        }\n      }.createDelegate(this)\n    }, this);\n  }\n}","validateForm":"","bbar":"","ptbar":"","sm":"{\n  type: \"RowSelectionModel\",\n  singleSelect: false\n}","store":"{\n  url: \"getGradosMilitares\",\n    type: \"GroupingStore\",\n      reader: {\n        type: \"JsonReader\",\n          totalProperty: \"quantity\",\n            root: \"data\"\n      },\n        mapping: [\n          {name: \"idgradomilitar\"},\n          {name: \"icongrado\"},\n          {name: \"idgrado\"},\n          {name: \"denomgrado\"},\n          {name: \"dequien\"},\n          {name: \"numorden\"},\n          {name: \"parrafo\"},\n          {name: \"anexo\"},\n          {name: \"fdesde\"},\n          {name: \"fhasta\"},\n          {name: \"historico\"}\n        ],\n        listeners: {\n            load: function (st)\n            {\n                var pRec = st.find(''historico'', ''1'', false)\n                var pGrado = Ext.getCmp(\"738\" + st.idpadre);\n              \tif(pGrado){\n                  if (pRec != -1) {\n                      var rec = st.getAt(pRec);\n                      pGrado.actualizarImagen.call(pGrado, rec.get(''icongrado''), rec.get(''denomgrado''), rec.get(''fdesde''));\n                  } else {\n                      var imgNUll = \"data:image/png;base64,\";\n                      pGrado.actualizarImagen.call(pGrado, imgNUll, ''Sin grado'', '''');\n                  }\n              \t}\n            }\n        },\n          sortInfo: {field: ''historico'', direction: \"DESC\"},\n            groupField: ''historico''\n}","view":"{\n  type: ''GroupingView'',\n    startCollapsed: true,\n      groupTextTpl: ''{group} ({[values.rs.length]} {[values.rs.length > 1 ? \"Grados\" : \"Grado\"]})''\n}","viewConfig":"","listeners":{"beforeload":"","expand":"","focus":"","load":"","render":"","resize":"","selectionchange":"","show":""}}', '{"module":"persona","component":"templates"}', '{"class":"DatGradomilitarModel","function":"getGradosMilitaresByPersona","id":"idgradomilitar", "project":"siac"}');
INSERT INTO dat_proyectoconcepto (idproyectoconcepto, denominacion, idpadre, idproyecto, descripcion, tipo, propiedades, iconcls, orden, codigo, cmpempleado, getdata) VALUES (1080, 'Categorías de la persona', 57, 'basetecnologica', NULL, 1, '{"xtype":"gest_panel","animCollapse":"false","autoHeight":"false","border":"true","collapsed":"false","collapsible":"false","disabled":"false","frame":"false","hidden":"false","split":"false","elementsByRow":3,"height":"","anchocolumna":"","anchor":"","cmargins":"","collapseMode":"","html":"","layout":"","margins":"","region":"","title":"Categorías de la persona","width":"auto"}', 'tag', 9, '{"columns":"[\n  {header: \"Categor&iacute;a\", width: 220, sortable: true, dataIndex: \"denominacion\"},  \n  {header: \"Desde\", width: 100, sortable: true, dataIndex: \"fdesde\"},\n  {header: \"Hasta\", width: 100, sortable: true, dataIndex: \"fhasta\"}\n]","addBotones":"","adicionarHandler":"","aplicarHandler":"function ()\n{\n    var values = this.fpFormulario.getForm().getValues();\n\t//Obteniendo la denominacion del tipo de categoria selecionada\n\n    values.denomcategoria = Ext.getCmp(\"1083\" + this.idpadre).getRawValue();\n\n    var store = this.gpGrid.getStore();\n\n    var index = -1;\n\n    if (Ext.isEmpty(values.idcategoria)) {\n        values.idcategoria = Ext.id();\n        values.add = true;\n        Ext.each(store.getRange(), function (rec)\n        {\n            if (rec.get(''idcategoria'') == values.idcategoria) {\n                index = ''categoria'';\n                return false;\n            }\n        });\n\n        switch (index) {\n            case ''categoria'':\n                Ext.Notification.show({\n                    title: ''Error'',\n                    msg: ''La categor&iacute;a que quiere adicionar ya existe.'',\n                    icon: ''error''\n                });\n                break;\n            default :\n                try {\n                    store.add(new Ext.data.Record(values));\n                    this.cleanForm();\n                } catch (error) {\n                    Ext.Notification.show({\n                        title: ''Error'',\n                        msg: ''Ha ocurrido un error mientras se guardaba, contacte el administrador.'',\n                        icon: ''error''\n                    });\n                }\n                break;\n        }\n    }\n}","eliminarHandler":"function ()\n{\n   var records = this.gpGrid.getSelectionModel().getSelections();\n   var ask = (records.length == 1) ? ''¿Está seguro que quiere eliminar la categoría seleccionada?'' : \n    ''¿Está seguro que quiere eliminar las categorías seleccionadas?'';\n\tmostrarMensaje(2, ask, function (btn)\n        {\n            if (btn == ''ok'') {\n               \n                Ext.each(records, function (rec)\n                {\n                    if (!rec.data.add) {\n                        this.arrDel.push(rec.get(''idcategoria''));\n                    }\n                    this.gpGrid.getStore().remove(rec);\n                }, this);\n\n                this.gpGrid.getView().refresh();\n            }\n        }.createDelegate(this));\n}","gSecurity":"","getLanguaje":"function(idioma){\n  var lang={};\n if(idioma===''es''){\n     lang ={\n        ttBtnAdd:\"Adicionar categoría de la persona\",\n        ttBtnMod:\"Modificar categoría de la persona\",\n        ttBtnDel:\"Eliminar categoría de la persona\",\n        ttBtnSave:\"Guardar datos y cerrar formulario\",\n        ttBtnApl:\"Guardar datos y limpiar los campos\",\n        ttBtnCancel:\"Cerrar formulario sin guardar los datos\"      \n\n      }  \t\n    }else{\n     lang = {\n        \n      }  \t\n      \n    }\n  return lang;\n\t\n}","guardarHandler":"function ()\n{\n    var values = this.fpFormulario.getForm().getValues();\n\n    values.denomcategoria = Ext.getCmp(\"1083\" + this.idpadre).getRawValue();\n\n    var store = this.gpGrid.getStore();\n\n    var index = -1;\n\n    if (Ext.isEmpty(values.idcategoria)) {\n        values.idcategoria = Ext.id();\n        values.add = true;\n        Ext.each(store.getRange(), function (rec)\n        {\n            if (rec.get(''idcategoria'') == values.idcategoria) {\n                index = ''categoria'';\n                return false;\n            }\n        });\n\n        switch (index) {\n            case ''categoria'':\n                Ext.Notification.show({\n                    title: ''Error'',\n                    msg: ''La categor&iacute;a que quiere adicionar ya existe.'',\n                    icon: ''error''\n                });\n                break;\n            default :\n                try {\n                    store.add(new Ext.data.Record(values));\n                    this.cancelarHandler();\n                } catch (error) {\n                    Ext.Notification.show({\n                        title: ''Error'',\n                        msg: ''Ha ocurrido un error mientras se guardaba, contacte el administrador.'',\n                        icon: ''error''\n                    });\n                }\n                break;\n        }\n    } else {\n        var record;\n        Ext.each(store.getRange(), function (rec)\n        {\n            if (rec.get(''idcategoriapersona'') != values.idcategoriapersona) {                \n                if (rec.get(''idcategoria'') == values.idcategoria) {\n                \tindex = ''categoria'';\n                \treturn false;\n            \t}\n            } else {\n                record = rec;\n            }\n        });\n        switch (index) {\n            case ''categoria'':\n                Ext.Notification.show({\n                    title: ''Error'',\n                    msg: ''La categor&iacute;a ya existe.'',\n                    icon: ''error''\n                });\n                break;\n            default :\n                try {\n                    for (var p in values) {\n                        if (values[p] != record.get(p)) {\n                            record.set(p, values[p]);\n                        }\n                    }\n                    this.cancelarHandler();\n                } catch (error) {\n                    Ext.Notification.show({\n                        title: ''Error'',\n                        msg: ''Ha ocurrido un error mientras se modificaba, contacte el administrador'',\n                        icon: ''error''\n                    });\n                }\n                break;\n        }\n    }\n}","helpHandler":"","isDirty":"","loadFn":"function (idpersona) {\n  this.arrAdd = [];\n  this.arrMod = [];\n  this.arrDel = [];\n  this.loadGridStore({idpersona: idpersona});\n}","modificarHandler":"","saveFn":"function (btnPress) {\n   var self = this;\n   var store = this.gpGrid.getStore();\n   var pass = false;\n   this.arrAdd = [];\n   this.arrMod = [];\n   Ext.each(store.getRange(), function (rec)\n            {\n              if (rec.data.add) {//Si es un record que se adiciono nuevo\n                this.arrAdd.push(rec.data);\n              } else {\n                if (!Ext.isEmpty(rec.modified)) {//Si el record fue modificado\n                  this.arrMod.push(rec.data);\n                }\n              }\n              pass = true;\n            }, this);\n   if (!pass && this.obligatorio) {\n     Ext.Notification.show({\n       title: ''Advertencia'',\n       msg: ''La persona debe tener alguna categor&iacute;a registrada'',\n       icon: ''warning''\n     });\n     return false;\n   }\n   var url = '''';\n   if (this.arrMod.length > 0 || (this.arrDel.length > 0 && this.arrAdd.length > 0)) {\n     url = ''modCategoriasPersona'';\n   } else\n     if (this.arrDel.length > 0) {\n       url = ''delCategoriasPersona'';\n     } else {\n       url = ''addCategoriasPersona'';\n     }\n   if (this.arrAdd.length > 0 || this.arrMod.length > 0 || this.arrDel.length > 0) {\n     Ext.sendAjax.request({\n       url: url,\n       params: {\n         arrAdd: Ext.encode(self.arrAdd),\n         arrMod: Ext.encode(self.arrMod),\n         arrDel: Ext.encode(self.arrDel)\n       },\n       success: function (response, opt, notification)\n       {\n         var dataResponse = Ext.decode(response.responseText);\n         if (dataResponse.success) {\n           if (btnPress === ''APLICAR'') { //Si el boton que ejecuto la funcion fue aplicar\n             this.loadFn(Ext.getCmp(this.idpadre).persona.idpersona);\n           }\n           this.arrAdd = [];\n           this.arrMod = [];\n           this.arrDel = [];\n           var msg;\n           switch (url) {\n             case ''modCategoriasPersona'':\n               msg = ''La(s) categoría(s) ha(n) sido eliminada(s) satisfactoriamente.'';\n               break;\n             case ''delCategoriasPersona'':\n               msg = ''La(s) categoría(s) ha(n) sido eliminada(s) satisfactoriamente.'';\n               break;\n             case ''addCategoriasPersona'':\n               msg = ''La(s) categoría(s) ha(n) sido adicionada(s) satisfactoriamente.'';\n               break\n           }\n           notification({\n             title: ''Informaci&oacute;n'',\n             msg: msg,\n             icon: ''ok''\n           });\n         } else {\n           switch (dataResponse.codigo) {\n             case 23503:\n               notification({\n                 title: ''Error'',\n                 msg: ''No se puede eliminar debido a que est&aacute; en uso.'',\n                 icon: ''error''\n               });\n               break;\n             default :\n               notification({\n                 title: ''Error'',\n                 msg: ''Ha ocurrido un error durante la transaccion.'',\n                 icon: ''error''\n               });\n               break;\n           }\n         }\n       }.createDelegate(this)\n     }, this);\n   }\n }","validateForm":"","bbar":"","ptbar":"","sm":"{\n  type: \"CheckboxSelectionModel\",\n  singleSelect: false\n}","store":"{\n  url: \"getCategoriasByPersona\",\n    type: \"Store\",\n      reader: {\n        type: \"JsonReader\",\n          totalProperty: \"quantity\",\n            root: \"data\"\n      },\n        mapping: [\n          {name: \"idcategoriapersona\"},\n          {name: \"idcategoria\"},\n          {name: \"denomcategoria\"},\n          {name: \"idtipocategoria\"},\n          {name: \"denominacion\"},\n          {name: \"fdesde\"},\n          {name: \"fhasta\"}\n        ]\n}","view":"","viewConfig":"","listeners":{"beforeload":"","expand":"","focus":"","load":"","render":"","resize":"","selectionchange":"","show":""}}', '{"module":"persona","component":"templates"}', '{"class":"DatCategoriaModel","function":"","id":"", "project":""}');
INSERT INTO dat_proyectoconcepto (idproyectoconcepto, denominacion, idpadre, idproyecto, descripcion, tipo, propiedades, iconcls, orden, codigo, cmpempleado, getdata) VALUES (1370, 'Caracterización general', 1118, 'basetecnologica', 'datos psicométrico', 1, '{"xtype":"form_panel","animCollapse":"false","autoHeight":"true","border":"true","collapsed":"false","collapsible":"false","disabled":"false","frame":"true","hidden":"false","split":"false","trackResetOnLoad":"true","elementsByRow":3,"height":"","anchocolumna":"","anchor":"","buttonAlign":"right","cmargins":"","collapseMode":"","html":"","labelAlign":"top","layout":"","margins":"","region":"","title":"Datos psicométricos","width":"auto"}', 'tag', 11, '{"gSecurity":"function(){\n  var resp = true;\n  if(Ext.isEmpty(this.getForm().getValues().idcaracterizacion)){\n    if(parseInt(this.segAction[0]) === 1){ //Si puede adicionar\n      resp = false;\n    }\n  }else{\n  \tif(parseInt(this.segAction[1]) === 1){//Si puede modificar\n      resp = false;\n    }\n  }\n  if(resp)\n    Ext.getCmp(\"1370\" + this.idpadre).getForm().reset();\n  return resp;\n}","helpHandler":"","isDirty":"","loadFn":"function(idpersona){\n  Ext.Ajax.request({\n    url: ''getDatosPsicometricos'',\n    params: {idpersona: idpersona},\n    success: function (response, opt)\n    {\n      var dataResponse = Ext.decode(response.responseText);\n      if (dataResponse.data.length != 0) {\n        this.getForm().loadRecord(new Ext.data.Record(dataResponse.data));\n        this.getForm().findField(''coeficiente'').setRawValue(dataResponse.data.coeficiente);\n        this.getForm().findField(''expresion'').setRawValue(dataResponse.data.expresion);\n        this.getForm().findField(''apariencia'').setRawValue(dataResponse.data.apariencia);\n        this.getForm().findField(''motivacion'').setRawValue(dataResponse.data.motivacion);\n        this.getForm().findField(''perfil'').setValue(dataResponse.data.perfil);\n        this.getForm().findField(''explaboral'').setRawValue(dataResponse.data.explaboral);\n        this.getForm().findField(''expactividad'').setRawValue(dataResponse.data.expactividad);\n        this.getForm().findField(''aptoperfil'').setValue(dataResponse.data.aptoperfil);\n        this.getForm().findField(''resumen'').setValue(dataResponse.data.resumen);\n        \n      }\n    }.createDelegate(this)\n  });\n}","saveFn":"function (btnPress, close)\n{\n  var values=this.getForm().getValues();\n  console.info(values);\n  values.perfil = values.perfil == \"on\" ? 1 : 0; \n  values.aptoperfil = values.aptoperfil == \"on\" ? 1 : 0; \n  \n \n if(Ext.getCmp(\"1370\" + this.idpadre).gSecurity())return; //Si devuelve TRUE es porque tiene permisos para realizar la gestion correspondiente\n    \n  if (this.getForm().isValid() && this.getForm().isDirty()) {     \n        var url = (Ext.isEmpty(this.getForm().getValues().idcaracterizacion)) ? ''addDatosPsicometricos'' : ''modDatosPsicometricos'';\n    \n        Ext.sendAjax.request({\n            url: url,\n            params: values,\n            success: function (response, opt, notification)\n            {\n                var dataResponse = Ext.decode(response.responseText);\n                if (dataResponse.success) {\n                  if(close == true) {\n                    Ext.getCmp(\"1370\" + this.idpadre).ownerCt.ownerCt.removeConcept(Ext.getCmp(\"1370\" + this.idpadre), true);\n                  } else\n                    if (btnPress === ''APLICAR'') { //Si el boton que ejecuto la funcion fue aplicar\n                        if (dataResponse.data) {\n                            this.getForm().loadRecord(new Ext.data.Record(dataResponse.data));\n                          \tthis.getForm().loadRecord(new Ext.data.Record(dataResponse.data));\n                        \tthis.getForm().findField(''coeficiente'').setRawValue(dataResponse.data.coeficiente);\n                        \tthis.getForm().findField(''expresion'').setRawValue(dataResponse.data.expresion);\n                        \tthis.getForm().findField(''apariencia'').setRawValue(dataResponse.data.apariencia);\n                        \tthis.getForm().findField(''motivacion'').setRawValue(dataResponse.data.motivacion);\n                         \tthis.getForm().findField(''perfil'').setRawValue(dataResponse.data.perfil);\n                         \tthis.getForm().findField(''explaboral'').setRawValue(dataResponse.data.explaboral);\n                         \tthis.getForm().findField(''expactividad'').setRawValue(dataResponse.data.expactividad);\n                            this.getForm().findField(''aptoperfil'').setRawValue(dataResponse.data.aptoperfil);\n                            this.getForm().findField(''resumen'').setRawValue(dataResponse.data.resumen);\n                        }\n                    }\n                    var msg = '''';\n                    switch (url) {\n                        case ''addDatosPsicometricos'':\n                            msg = ''Los datos psicométricos se han adicionado satisfactoriamente.'';\n                            break;\n                        case ''modDatosPsicometricos'':\n                            msg = ''Los datos psicométricos se han modificado satisfactoriamente.'';\n                            break;\n                    }\n                    notification({\n                        title: ''Informaci&oacute;n'',\n                        msg: msg,\n                        icon: ''ok''\n                    });\n                } else {\n                    switch (dataResponse.codigo) {\n                        default :\n                            notification({\n                                title: ''Error'',\n                                msg: ''Ha ocurrido un error durante la transaccion.'',\n                                icon: ''error''\n                            });\n                            break;\n                    }\n                }\n\n            }.createDelegate(this)\n        }, this);\n    }\n}","listeners":{"clientvalidation":"","expand":"","focus":"","render":"","resize":"","show":""}}', '{"module":"persona","component":"templates"}', NULL);
INSERT INTO dat_proyectoconcepto (idproyectoconcepto, denominacion, idpadre, idproyecto, descripcion, tipo, propiedades, iconcls, orden, codigo, cmpempleado, getdata) VALUES (1305, 'Evaluación', 1118, 'basetecnologica', NULL, 1, '{"xtype":"grid_panel","animCollapse":"false","autoHeight":"false","border":"true","collapsed":"false","collapsible":"false","disabled":"false","frame":"false","hidden":"false","split":"false","elementsByRow":"2","height":"","anchocolumna":"","anchor":"","cmargins":"","collapseMode":"","html":"","layout":"","margins":"","region":"","title":"Evaluaciones","width":"auto"}', 'tag', 6, '{"columns":"[\n  {header: \"Período evaluativo\", width: 300, sortable: true, dataIndex: \"denominacion\"},\n  {header: \"Evaluación\", width: 180, sortable: true, dataIndex: \"valor\"},\n  {header: \"Proceso\", width: 180, sortable: true, dataIndex: \"proceso\",hidden:true}\n]","gSecurity":"","helpHandler":"","isDirty":"function(){\n\treturn false;\n}","loadFn":"function (idpersona)\n{\n  this.loadGridStore({idpersona: idpersona});\n}","saveFn":"","bbar":"","ptbar":"","sm":"{\n  type: \"CheckboxSelectionModel\",\n  singleSelect: false\n}","store":"{\n  url: \"getEvaluaciones\",\n  type: \"GroupingStore\",\n  reader: {\n    type: \"JsonReader\",\n    totalProperty: \"quantity\",\n    root: \"data\"\n  },\n  mapping: [\n    {name: \"idpreprocesoevaluativo\"},\n    {name: \"denominacion\"},\n    {name: \"valor\"},\n    {name: \"proceso\"}\n  ],\n  sortInfo: {field: ''proceso'', direction: \"DESC\"},\n  groupField: ''proceso''\n}","view":"{\n  type: ''GroupingView'',\n    startCollapsed: false,\n      groupTextTpl: ''{group} ({[values.rs.length]} {[values.rs.length > 1 ? \"Procesos\" : \"Proceso\"]})''\n}","viewConfig":"","listeners":{"beforeload":"","expand":"","focus":"","load":"","render":"","resize":"","selectionchange":"","show":""}}', '{"module":"persona","component":"templates"}', NULL);
INSERT INTO dat_proyectoconcepto (idproyectoconcepto, denominacion, idpadre, idproyecto, descripcion, tipo, propiedades, iconcls, orden, codigo, cmpempleado, getdata) VALUES (1010, 'Sanciones', 1009, 'basetecnologica', NULL, 1, '{"xtype":"gest_panel","animCollapse":"false","autoHeight":"false","border":"true","collapsed":"false","collapsible":"false","disabled":"false","frame":"false","hidden":"false","split":"false","elementsByRow":4,"height":330,"anchocolumna":"","anchor":"","cmargins":"","collapseMode":"","html":"","layout":"","margins":"","region":"","title":"Sanciones","width":"auto"}', 'tag', 1, '{"columns":"[\n  {header: \"Tipo de sanción\", width: 100, sortable: true, dataIndex: \"denomtiposancion\"},\n  {header: \"Sanción\", width: 180, sortable: true, dataIndex: \"denomsancion\"},  \n  {header: \"Motivo de sanción\", width: 280, sortable: true, dataIndex: \"denommotivosancion\"},\n  {header: \"Fecha de imposición\", width: 100, sortable: true, dataIndex: \"fimposicion\"},\n  {header: \"Fecha de notificación\", width: 100, sortable: true, dataIndex: \"fnotificacion\"}\n]","addBotones":"","adicionarHandler":"function(){\n  //Limpiando el combo Tipo de sanción seleccionada\n  if(Ext.getCmp(\"1012\" + this.idpadre))\n  \tExt.getCmp(\"1012\" + this.idpadre).store.clearFilter(true);\n  //Limpiando el combo de la sanción seleccionada\n  Ext.getCmp(\"1013\" + this.idpadre).store.clearFilter(true);\n  //Limpiando el combo del motivo de sanción seleccionado\n  Ext.getCmp(\"1016\" + this.idpadre).store.clearFilter(true);\n}","aplicarHandler":"function ()\n{\n  var values = this.fpFormulario.getForm().getValues();\n  //Obteniendo la denominacion de Tipo de sanción seleccionada\n  values.denomtiposancion = (Ext.getCmp(\"1012\" + this.idpadre))?Ext.getCmp(\"1012\" + this.idpadre).getRawValue():'''';\n  //Obteniendo la denominacion de la sanción seleccionada\n  values.denomsancion = Ext.getCmp(\"1013\" + this.idpadre).getRawValue();\n  //Obteniendo la denominacion del motivo de sanción seleccionado\n  values.denommotivosancion = Ext.getCmp(\"1016\" + this.idpadre).getRawValue();\n  values.idcargofacultado = Ext.getCmp(\"1291\" + this.idpadre).getValue();\n  \n  if(Ext.isEmpty(values.tiemposancion)){\n  \tvalues.unidadtiempo = '''';\n  }\n\n  var store = this.gpGrid.getStore();\n  var index = -1;\n  if (Ext.isEmpty(values.idsancionp)){\n    values.idsancionp = Ext.id();\n    values.add = true;\n    try {\n      store.add(new Ext.data.Record(values));\n      this.cleanForm();\n    } catch (error) {\n      Ext.Notification.show({\n        title: ''Error'',\n        msg: ''Ha ocurrido un error mientras se guardaba, contacte el administrador.'',\n        icon: ''error''\n      });\n    }\n  }\n}","eliminarHandler":"function ()\n{\n  var records = this.gpGrid.getSelectionModel().getSelections();\n   var ask = (records.length == 1) ? ''¿Está seguro que quiere eliminar la sanción seleccionada?'' : \n    ''¿Está seguro que quiere eliminar las sanciones seleccionadas?'';\n\tmostrarMensaje(2,ask, function (btn)\n        {\n            if (btn == ''ok'') {\n                var records = this.gpGrid.getSelectionModel().getSelections();\n                Ext.each(records, function (rec)\n                {\n                    if (!rec.data.add) {\n                        this.arrDel.push(rec.get(''idsancionp''));\n                    }\n                    this.gpGrid.getStore().remove(rec);\n                }, this);\n\n                this.gpGrid.getView().refresh();\n            }\n        }.createDelegate(this));\n}","gSecurity":"","getLanguaje":"function(idioma){\n  var lang={};\n if(idioma===''es''){\n     lang ={\n        ttBtnAdd:\"Adicionar sanci&oacute;n\",\n        ttBtnMod:\"Modificar sanci&oacute;n\",\n        ttBtnDel:\"Eliminar sanci&oacute;n\",\n        ttBtnSave:\"Guardar datos y cerrar formulario\",\n        ttBtnApl:\"Guardar datos y limpiar los campos\",\n        ttBtnCancel:\"Cerrar formulario sin guardar los datos\"      \n\n      }  \t\n    }else{\n     lang = {\n        \n      }  \t\n      \n    }\n  return lang;\n\t\n}","guardarHandler":"function ()\n{\n    var values = this.fpFormulario.getForm().getValues();\n    //Obteniendo la denominacion de Tipo de sanción seleccionada\n    values.denomtiposancion = (Ext.getCmp(\"1012\" + this.idpadre)) ? Ext.getCmp(\"1012\" + this.idpadre).getRawValue() : '''';\n    //Obteniendo la denominacion de la sanción seleccionada\n    values.denomsancion = Ext.getCmp(\"1013\" + this.idpadre).getRawValue();\n    //Obteniendo la denominacion del motivo de sanción seleccionado\n    values.denommotivosancion = Ext.getCmp(\"1016\" + this.idpadre).getRawValue();\n    values.idcargofacultado = Ext.getCmp(\"1291\" + this.idpadre).getValue();\n\n    if (Ext.isEmpty(values.tiemposancion)) {\n        values.unidadtiempo = '''';\n    }\n\n    var store = this.gpGrid.getStore();\n\n    if (Ext.isEmpty(values.idsancionp)) {\n        values.idsancionp = Ext.id();\n        values.add = true;\n        try {\n            store.add(new Ext.data.Record(values));\n            this.cancelarHandler();\n        } catch (error) {\n            Ext.Notification.show({\n                title: ''Error'',\n                msg: ''Ha ocurrido un error mientras se guardaba, contacte el administrador'',\n                icon: ''error''\n            });\n        }\n    } else {\n        var record;\n        Ext.each(store.getRange(), function (rec)\n        {\n            if (rec.get(''idsancionp'') == values.idsancionp) {\n                record = rec;\n                return false;\n            }\n        });\n\n        try {\n            for (var p in values) {\n                if (values[p] != record.get(p)) {\n                    record.set(p, values[p]);\n                }\n            }\n            this.cancelarHandler();\n        } catch (error) {\n            Ext.Notification.show({\n                title: ''Error'',\n                msg: ''Ha ocurrido un error mientras se modificaba, contacte el administrador'',\n                icon: ''error''\n            });\n        }\n\n    }\n}","helpHandler":"","isDirty":"","loadFn":"function (idpersona)\n{\n  this.arrAdd = [];\n  this.arrMod = [];\n  this.arrDel = [];\n  this.loadGridStore({idpersona: idpersona});\n}","modificarHandler":"function(){\n  //Limpiando el combo Tipo de sanción seleccionada\n  if(Ext.getCmp(\"1012\" + this.idpadre))\n  \tExt.getCmp(\"1012\" + this.idpadre).store.clearFilter(true);\n  //Limpiando el combo de la sanción seleccionada\n  Ext.getCmp(\"1013\" + this.idpadre).store.clearFilter(true);\n  //Limpiando el combo del motivo de sanción seleccionado\n  Ext.getCmp(\"1016\" + this.idpadre).store.clearFilter(true);\n\n  var record = this.gpGrid.getSelectionModel().getSelected();\n  this.loadFormulario(record);\n\n}","saveFn":"function (btnPress)\n{\n  var store = this.gpGrid.getStore();\n  var self = this;\n  var pass = false;\n  this.arrAdd = [];\n  this.arrMod = [];\n  Ext.each(store.getRange(), function (rec)\n  {\n    if (rec.data.add) {//Si es un record que se adiciono nuevo\n      this.arrAdd.push(rec.data);\n    } else {\n      if (!Ext.isEmpty(rec.modified)) {//Si el record fue modificado\n        this.arrMod.push(rec.data);\n      }\n    }\n    pass = true;\n  }, this);\n  if (!pass && this.obligatorio) {\n    Ext.Notification.show({\n      title: ''Advertencia'',\n      msg: ''La persona debe tener una sanción registrada'',\n      icon: ''warning''\n    });\n    return false;\n  }\n  var url = '''';\n  if (this.arrMod.length > 0 || (this.arrDel.length > 0 && this.arrAdd.length > 0)) {\n    url = ''modSanciones'';\n  } else\n    if (this.arrDel.length > 0) {\n      url = ''delSanciones'';\n    } else {\n      url = ''addSanciones'';\n    }\n  if (this.arrAdd.length > 0 || this.arrMod.length > 0 || this.arrDel.length > 0) {\n    Ext.sendAjax.request({\n      url: url,\n      params: {\n        arrAdd: Ext.encode(self.arrAdd),\n        arrMod: Ext.encode(self.arrMod),\n        arrDel: Ext.encode(self.arrDel)\n      },\n      success: function (response, opt, notification)\n      {\n        var dataResponse = Ext.decode(response.responseText);\n        if (dataResponse.success) {\n          if (btnPress === ''APLICAR'') { //Si el boton que ejecuto la funcion fue aplicar\n            this.loadFn(Ext.getCmp(this.idpadre).persona.idpersona);\n          }\n          this.arrAdd = [];\n          this.arrMod = [];\n          this.arrDel = [];\n          var msg;\n          switch (url) {\n            case ''modSanciones'':\n              msg = ''La(s) sanción(es) ha(n) sido modificada(s) satisfactoriamente.'';\n              break;\n            case ''delSanciones'':\n              msg = ''La(s) sanción(es) ha(n) sido eliminada(s) satisfactoriamente.'';\n              break;\n            case ''addSanciones'':\n              msg = ''La(s) sanción(es) ha(n) sido adicionada(s) satisfactoriamente.'';\n              break\n          }\n          notification({\n            title: ''Informaci&oacute;n'',\n            msg: msg,\n            icon: ''ok''\n          });\n        } else {\n          switch (dataResponse.codigo) {\n            default :\n              notification({\n                title: ''Error'',\n                msg: ''Ha ocurrido un error durante la transaccion.'',\n                icon: ''error''\n              });\n              break;\n          }\n        }\n      }.createDelegate(this)\n    }, this);\n  }\n}","validateForm":"","bbar":"","ptbar":"","sm":"{\n  type: \"CheckboxSelectionModel\",\n  singleSelect: false\n}","store":"{\n  url: \"getSanciones\",\n    type: \"Store\",\n      reader: {\n        type: \"JsonReader\",\n          totalProperty: \"quantity\",\n            root: \"data\"\n      },\n        mapping: [\n          {name: \"idsancionp\"},\n          {name: \"idtiposancion\"},\n          {name: \"denomtiposancion\"},\n          {name: \"idsancion\"},\n          {name: \"denomsancion\"},\n          {name: \"idmotivosancion\"},\n          {name: \"denommotivosancion\"},\n          {name: \"tiemposancion\"},\n          {name: \"unidadtiempo\"},\n          {name: \"fimposicion\"},\n          {name: \"frehabilitacion\"},\n          {name: \"observacion\"},\n          {name: \"fnotificacion\"},\n          {name: \"resolucion\"},\n          {name: \"denominacion\"},\n          {name: \"idcargofacultado\"},\n          {name: \"resrehabilitacion\"},\n          {name: \"cargopropuesto\"},\n          {name: \"idcargopropuesto\"}\n        ]\n}","view":"","viewConfig":"","listeners":{"beforeload":"","expand":"","focus":"","load":"","render":"","resize":"","selectionchange":"","show":""}}', '{"module":"persona","component":"templates"}', '{"class":"DatSancionModel","function":"","id":"", "project":""}');
INSERT INTO dat_proyectoconcepto (idproyectoconcepto, denominacion, idpadre, idproyecto, descripcion, tipo, propiedades, iconcls, orden, codigo, cmpempleado, getdata) VALUES (1291, 'idcargojefe', 1010, 'basetecnologica', NULL, 3, '{"xtype":"combo_box","allowBlank":"true","disabled":"false","editable":"true","forceSelection":"false","hidden":"false","readOnly":"false","resizable":"false","selectOnFocus":"false","typeAhead":"false","anchocolumna":"","anchor":"98%","displayField":"cargopropuesto","emptyText":"Seleccione...","fieldLabel":"Jefe Facultado","hiddenName":"idcargopropuesto","loadingText":"","mode":"local","name":"idcargopropuesto","toolTipTrigger1":"","toolTipTrigger2":"","triggerAction":"","valueField":"idcargopropuesto"}', 'icondistra-tag_blue', 13, '{"handler":"","store":"{\n  url: \"getFormEnteringJefe\",\n    type: \"Store\",\n       baseParams: {\n            value: 1\n        },\n      reader: {\n        type: \"JsonReader\",          \n            root: \"data\"\n      },\n        mapping: [\n          \t{name: ''idcargopropuesto''},\n        \t{name: ''idcargopropuesto''},\n        \t{name: ''cargopropuesto''},\n        \t{name: ''fdesde''},\n        \t{name: ''fhasta ''},\n        \t{name: ''descripcion''}      \n        ],\n          autoLoad:true,\n          \n}","tpl":"","listeners":{"expand":"","focus":"","render":"","select":""}}', '{"module":"persona","component":"templates"}', NULL);
INSERT INTO dat_proyectoconcepto (idproyectoconcepto, denominacion, idpadre, idproyecto, descripcion, tipo, propiedades, iconcls, orden, codigo, cmpempleado, getdata) VALUES (91, 'Documentos de identificación', 57, 'basetecnologica', NULL, 1, '{"xtype":"gest_panel","animCollapse":"false","autoHeight":"false","border":"true","collapsed":"false","collapsible":"false","disabled":"false","frame":"false","hidden":"false","split":"false","elementsByRow":5,"height":"","anchocolumna":"","anchor":"","cmargins":"","collapseMode":"","html":"","layout":"","margins":"","region":"","title":"Documentos de identificación","width":"auto"}', 'tag', 1, '{"columns":"[\n  {header: \"Tipo de identificación\", width: 220, sortable: true, dataIndex: \"denomtipodocidentidad\"},\n  {header: \"Número\", width: 180, sortable: true, dataIndex: \"numero\"},\n  {header: \"Principal\", width: 60, sortable: true, dataIndex: \"principal\", renderer: function (val, metadata)\n   {\n     if (val == true) {\n       return \"<center class=''checked'' style=''width: 16px; height: 16px;''></center>\";\n     }\n     return '''';\n   }},\n  {header: \"Desde\", width: 100, sortable: true, dataIndex: \"fdesde\"},\n  {header: \"Hasta\", width: 100, sortable: true, dataIndex: \"fhasta\"},\n  {header: \"Hist&oacute;rico\", hidden: true, sortable: true, dataIndex: \"historico\", renderer: function (v)\n   {\n     if(isNaN(v)){\n     return ''Nuevo'';\n   }else{\n    return (v == 1) ? ''Actual'' : ''Hist&oacute;rico'';\n   }\n   }}\n]","addBotones":"","adicionarHandler":"","aplicarHandler":"function ()\n{\n    var values = this.fpFormulario.getForm().getValues();\n\n    values.denomtipodocidentidad = Ext.getCmp(\"92\" + this.idpadre).getRawValue();\n  \n\tvalues.historico = isActual(values.fdesde, values.fhasta);\n    values.principal = values.principal == \"on\" ? true : false;\n\n    var store = this.gpGrid.getStore();\n\n    var index = -1;\n\n    if (Ext.isEmpty(values.iddocidentidad)) {\n        values.iddocidentidad = Ext.id();\n        values.add = true;\n        Ext.each(store.getRange(), function (rec)\n        {\n            if (rec.get(''principal'') == true && values.principal != false && rec.get(''historico'') == 1 && values.historico == 1) {\n                index = ''principal'';\n                return false;\n            }\n            if (rec.get(''idtipodocidentidad'') == values.idtipodocidentidad && rec.get(''historico'') == 1 && values.historico == 1) {\n                index = ''Tipo doc identidad'';\n                return false;\n            }\n          \tif (!Ext.isEmpty(rec.get(''fhasta'')) && rec.get(''idtipodocidentidad'') == values.idtipodocidentidad) {\n              \tif (isActual(rec.get(''fdesde''), rec.get(''fhasta''), values.fdesde) == 1 || (!Ext.isEmpty(values.fhasta) && isActual(rec.get(''fdesde''), rec.get(''fhasta''), values.fhasta) == 1)) {\n              \t\tindex = ''Cruce de fechas'';\n              \t\treturn false;\n            \t}\n          \t}\n        });\n\n        switch (index) {\n            case ''principal'':\n               \n            \tExt.Notification.show({\n                       title: ''Error'',\n                  msg: ''La persona posee registrado un documento de identidad como principal.'',\n                  icon: ''error''\n                    });\n                break;\n            case ''Tipo doc identidad'':\n              \n            Ext.Notification.show({\n                      title: ''Error'',\n                  msg: ''El documento de indentificación que quiere adicionar ya existe.'',\n                  icon: ''error''\n                    });\n                break;  \n            case ''Cruce de fechas'':\n              \n            Ext.Notification.show({\n                      title: ''Error'',\n                  msg: ''Verifique las fechas, no pueden encontrarse en el intervalo de otro documento del mismo tipo.'',\n                  icon: ''error''\n                    });\n                break;  \n            case ''Cruce de fechas'':\n              Ext.Notification.show({\n                      title: ''Error'',\n                  msg: ''Verifique las fechas, no pueden encontrarse en el intervalo de otro documento del mismo tipo.'',\n                  icon: ''error''\n                    });\n                break;  \n            default :\n                try {\n                    store.add(new Ext.data.Record(values));\n                    this.cleanForm();\n                } catch (error) {\n                  \n                   Ext.Notification.show({\n                     title: ''Error'',\n                      msg: ''Ha ocurrido un error mientras se guardaba, contacte el administrador.'',\n                      icon: ''error''\n                    });\n                 \n                }\n                break;\n        }\n    }\n  \n   store.clearGrouping();\n   store.groupBy(''historico'', true);\n  \n   function isActual(fi, ff, fa)\n   {\n    if (!Ext.isEmpty(ff)) {//Si la fecha fin es ditinto de vacio\n      if (Ext.isEmpty(fa)) {\n         var date = new Date();\n      \t date = date.format(''d/m/Y'');\n      } else {\n         date = fa;\n      }     \n      var arrfi = fi.split(''/'');\n      var arrff = ff.split(''/'');\n      var arrfa = date.split(''/'');\n      var fi = arrfi[2] + arrfi[1] + arrfi[0];\n      var ff = arrff[2] + arrff[1] + arrff[0];\n      var fa = arrfa[2] + arrfa[1] + arrfa[0];\n      fi = parseInt(fi);\n      ff = parseInt(ff);\n      fa = parseInt(fa);\n      return (fi <= fa && fa <= ff) ? 1 : 0;\n      //1->Actual  0->Historico\n    }\n    return 1;\n  }\n}","eliminarHandler":"function ()\n{\n   var records = this.gpGrid.getSelectionModel().getSelections();\n    var ask = (records.length == 1) ? ''¿Está seguro que quiere eliminar el documento de identificación seleccionado?'' : \n    ''¿Está seguro que quiere eliminar los documentos de identificación seleccionados?'';\n     \n\tmostrarMensaje(2, ask, function (btn)\n        {\n            if (btn == ''ok'') {\n               \n                Ext.each(records, function (rec)\n                {\n                    if (!rec.data.add) {\n                        this.arrDel.push(rec.get(''iddocidentidad''));\n                    }\n                    this.gpGrid.getStore().remove(rec);\n                }, this);\n\n                this.gpGrid.getView().refresh();\n            }\n        }.createDelegate(this));\n}","gSecurity":"","getLanguaje":"function(idioma){\n  var lang={};\n if(idioma===''es''){\n     lang ={\n        ttBtnAdd:\"Adicionar documento de identificación\",\n        ttBtnMod:\"Modificar documento de identificación\",\n        ttBtnDel:\"Eliminar documento de identificación\",\n        ttBtnSave:\"Guardar datos y cerrar formulario\",\n        ttBtnApl:\"Guardar datos y limpiar los campos\",\n        ttBtnCancel:\"Cerrar formulario sin guardar los datos\"      \n\n      }  \t\n    }else{\n     lang = {\n        \n      }  \t\n      \n    }\n  return lang;\n\t\n}","guardarHandler":"function ()\n{\n    var values = this.fpFormulario.getForm().getValues();\n\n    values.denomtipodocidentidad = Ext.getCmp(\"92\" + this.idpadre).getRawValue();\n\n    values.principal = values.principal == \"on\" ? true : false;\n  \tvalues.historico = isActual(values.fdesde, values.fhasta);\n\n    var store = this.gpGrid.getStore();\n\n    var index = -1;\n\n    if (Ext.isEmpty(values.iddocidentidad)) {\n        values.iddocidentidad = Ext.id();\n        values.add = true;\n        Ext.each(store.getRange(), function (rec)\n        {\n            if (rec.get(''principal'') == true && values.principal != false && rec.get(''historico'') == 1 && values.historico == 1) {\n                index = ''principal'';\n                return false;\n            }\n            if (rec.get(''idtipodocidentidad'') == values.idtipodocidentidad && rec.get(''historico'') == 1 && values.historico == 1) {\n                index = ''Tipo doc identidad'';\n                return false;\n            }\n          \tif (!Ext.isEmpty(rec.get(''fhasta'')) && rec.get(''idtipodocidentidad'') == values.idtipodocidentidad) {\n              \tif (isActual(rec.get(''fdesde''), rec.get(''fhasta''), values.fdesde) == 1 || (!Ext.isEmpty(values.fhasta) && isActual(rec.get(''fdesde''), rec.get(''fhasta''), values.fhasta) == 1)) {\n              \t\tindex = ''Cruce de fechas'';\n              \t\treturn false;\n            \t}\n          \t}\n          \t\n        });\n\n        switch (index) {\n            case ''principal'':\n             \n            Ext.Notification.show({\n                      title: ''Error'',\n                      msg: ''La persona posee registrado un documento de identidad como principal.'',\n                      icon: ''error''\n                    });\n        \n                break;\n            case ''Tipo doc identidad'':\n              \n             Ext.Notification.show({\n                      title: ''Error'',\n                      msg: ''El documento de indentificación que quiere adicionar ya existe.'',\n                      icon: ''error''\n                    });\n                break;\n            case ''Cruce de fechas'':\n              Ext.Notification.show({\n                      title: ''Error'',\n                  msg: ''Verifique las fechas, no pueden encontrarse en el intervalo de otro documento del mismo tipo.'',\n                  icon: ''error''\n                    });\n                break;  \n            default :\n                try {\n                    store.add(new Ext.data.Record(values));\n                    this.cancelarHandler();\n                } catch (error) {\n                    \n                     Ext.Notification.show({\n                      title: ''Error'',\n                      msg: ''Ha ocurrido un error mientras se guardaba, contacte el administrador.'',\n                      icon: ''error''\n                    });\n                 \n                }\n                break;\n        }\n    } else {\n        var record;\n        Ext.each(store.getRange(), function (rec)\n        {\n            if (rec.get(''iddocidentidad'') != values.iddocidentidad) {              \n                if (rec.get(''principal'') == true && values.principal != false && rec.get(''historico'') == 1 && values.historico == 1) {\n                    index = ''principal'';\n                    return false;\n                }\n                if (rec.get(''idtipodocidentidad'') == values.idtipodocidentidad && rec.get(''historico'') == 1 && values.historico == 1) {\n                    index = ''Tipo doc identidad'';\n                    return false;\n                }\n                if (!Ext.isEmpty(rec.get(''fhasta'')) && rec.get(''idtipodocidentidad'') == values.idtipodocidentidad) {\n              \t\tif (isActual(rec.get(''fdesde''), rec.get(''fhasta''), values.fdesde) == 1 || (!Ext.isEmpty(values.fhasta) && isActual(rec.get(''fdesde''), rec.get(''fhasta''), values.fhasta) == 1)) {\n              \t\t\tindex = ''Cruce de fechas'';\n              \t\t\treturn false;\n            \t\t}\n          \t\t}\n            } else {\n                record = rec;\n            }\n        });\n        switch (index) {\n            case ''principal'':\n              \t \n             Ext.Notification.show({\n                    title: ''Error'',\n                      msg: ''La persona posee registrado un documento de identidad como principal.'',\n                      icon: ''error''\n                    });\n          \n                break;\n            case ''Tipo doc identidad'':\n             \t \n              Ext.Notification.show({\n                    title: ''Error'',\n                      msg: ''El documento de indentificación ya existe.'',\n                      icon: ''error''\n                    });\n                break;\n            case ''Cruce de fechas'':\n              Ext.Notification.show({\n                      title: ''Error'',\n                  msg: ''Verifique las fechas, no pueden encontrarse en el intervalo de otro documento del mismo tipo.'',\n                  icon: ''error''\n                    });\n                break;  \n            default :\n                try {\n                    for (var p in values) {\n                        if (values[p] != record.get(p)) {\n                            record.set(p, values[p]);\n                        }\n                    }\n                    this.cancelarHandler();\n                } catch (error) {\n                    \n                    Ext.Notification.show({\n                    title: ''Error'',\n                      msg: ''Ha ocurrido un error mientras se modificaba, contacte el administrador.'',\n                      icon: ''error''\n                    });\n                }\n                break;\n        }\n    }\n  \n   store.clearGrouping();\n   store.groupBy(''historico'', true);\n  \n   function isActual(fi, ff, fa)\n   {\n    if (!Ext.isEmpty(ff)) {//Si la fecha fin es ditinto de vacio\n      if (Ext.isEmpty(fa)) {\n         var date = new Date();\n      \t date = date.format(''d/m/Y'');\n      } else {\n         date = fa;\n      }     \n      var arrfi = fi.split(''/'');\n      var arrff = ff.split(''/'');\n      var arrfa = date.split(''/'');\n      var fi = arrfi[2] + arrfi[1] + arrfi[0];\n      var ff = arrff[2] + arrff[1] + arrff[0];\n      var fa = arrfa[2] + arrfa[1] + arrfa[0];\n      fi = parseInt(fi);\n      ff = parseInt(ff);\n      fa = parseInt(fa);\n      return (fi <= fa && fa <= ff) ? 1 : 0;\n      //1->Actual  0->Historico\n    }\n    return 1;\n  }\n}\n","helpHandler":"function()\n{\nvar title = ''Ayuda de Tipos de nodos'';\nvar referencia = ''RH/Registro/Clientes/principal'';\nhelp.show(title, referencia);\n}","isDirty":"","loadFn":"function(idpersona){\n  this.arrAdd = [];\n  this.arrMod = [];\n  this.arrDel = [];\n  this.loadGridStore({idpersona: idpersona});\n}","modificarHandler":"function(){\n    var record=this.gpGrid.getSelectionModel().getSelected();\n  \tExt.getCmp(\"93\" + this.idpadre).enable();\n    Ext.getCmp(\"93\" + this.idpadre).minLength=record.data.mincaracter;\n    Ext.getCmp(\"93\" + this.idpadre).maxLength=record.data.maxcaracter;\n    Ext.getCmp(\"93\" + this.idpadre).vtype=record.data.type;\n    Ext.getCmp(\"93\" + this.idpadre).maxLengthText=''El tamaño máximo permitido es de ''+record.data.maxcaracter+'' caracteres.'';\n    Ext.getCmp(\"93\" + this.idpadre).minLengthText=''El tamaño mínimo permitido es de ''+record.data.mincaracter+'' caracteres.'';\n    Ext.getCmp(\"93\" + this.idpadre).render();\n\n}","saveFn":"function (btnPress)\n{\n  var store = this.gpGrid.getStore();\n  var self = this;\n  var pass = false;\n  this.arrAdd = [];\n  this.arrMod = [];\n  Ext.each(store.getRange(), function (rec)\n           {\n             if (rec.data.add) {//Si es un record que se adiciono nuevo\n               this.arrAdd.push(rec.data);\n             } else {\n               if (!Ext.isEmpty(rec.modified)) {//Si el record fue modificado\n                 this.arrMod.push(rec.data);\n               }\n             }\n             if (rec.get(''principal'') == true) {\n               pass = true;\n             }\n           }, this);\n  if (!pass && this.obligatorio) {\n      notification({\n        title: ''Error'',\n        msg: ''La persona debe tener un tipo de documento como principal.'',\n        icon: ''error''\n      });  \n    return false;\n  }\n  var url = '''';\n  if (this.arrMod.length > 0) {\n    url = ''modDocIdentidad'';\n  } else\n    if (this.arrDel.length > 0) {\n      url = ''delDocIdentidad'';\n    } else {\n      url = ''addDocIdentidad'';\n    }\n  if (this.arrAdd.length > 0 || this.arrMod.length > 0 || this.arrDel.length > 0) {\n    Ext.sendAjax.request({\n      url: url,\n      params: {\n        arrAdd: Ext.encode(self.arrAdd),\n        arrMod: Ext.encode(self.arrMod),\n        arrDel: Ext.encode(self.arrDel)\n      },\n      success: function (response, opt, notification)\n      {\n        var dataResponse = Ext.decode(response.responseText);\n        if (dataResponse.success) {\n          if (btnPress === ''APLICAR'') { //Si el boton que ejecuto la funcion fue aplicar\n            this.loadFn(Ext.getCmp(this.idpadre).persona.idpersona);\n          }\n          this.arrAdd = [];\n          this.arrMod = [];\n          this.arrDel = [];\n          var msg;\n          switch (url) {\n            case ''modDocIdentidad'':\n              msg = ''El(Los) documento(s) de identificación  ha(n) sido modificado satisfactoriamente.'';\n              break;\n            case ''delDocIdentidad'':\n              msg = ''El(Los) documento(s) de identificación  ha(n) sido eliminado satisfactoriamente.'';\n              break;\n            case ''addDocIdentidad'':\n              msg = ''El(Los) documento(s) de identificación ha(n) sido adicionado(s) satisfactoriamente.'';\n              break\n          }         \n            notification({\n              title: ''Informaci&oacute;n'',\n              msg: msg,\n              icon: ''ok''\n          \t}); \n        } else {\n          switch (dataResponse.codigo) {\n            default :\n             notification({\n                title: ''Error'',\n                msg: ''H ocurrido un error durante la transacción.'',\n                icon: ''error''\n              });\n              break;\n          }\n        }\n      }.createDelegate(this)\n    }, this);\n  }\n}","validateForm":"","bbar":"","ptbar":"","sm":"{\n  type: \"CheckboxSelectionModel\",\n  singleSelect: false\n}","store":"{\n  url: \"getDocIdentidad\",\n  type: \"GroupingStore\",\n  reader: {\n    type: \"JsonReader\",\n    totalProperty: \"quantity\",\n    root: \"data\"\n  },\n  mapping: [\n    {name: \"iddocidentidad\"},\n    {name: \"idtipodocidentidad\"},\n    {name: \"denomtipodocidentidad\"},\n    {name: \"numero\"},\n    {name: \"principal\"},\n    {name: \"type\"},\n    {name: \"maxcaracter\"},\n    {name: \"mincaracter\"},\n    {name: \"serie\"},\n    {name: \"fdesde\"},\n    {name: \"fhasta\"},\n    {name: \"historico\"}\n  ],\n  sortInfo: {field: ''historico'', direction: \"DESC\"},\n  groupField: ''historico''\n}","view":"{\n  type: ''GroupingView'',\n    startCollapsed: false,\n      groupTextTpl: ''{group} ({[values.rs.length]} {[values.rs.length > 1 ? \"Documentos de identificaci&oacute;n\" : \"Documento de identificaci&oacute;n\"]})''\n}","viewConfig":"","listeners":{"beforeload":"","expand":"","focus":"","load":"","render":"","resize":"","selectionchange":"","show":""}}', '{"module":"persona","component":"templates"}', '{"class":"DatDocidentidadModel","function":"","id":"", "project":""}');
INSERT INTO dat_proyectoconcepto (idproyectoconcepto, denominacion, idpadre, idproyecto, descripcion, tipo, propiedades, iconcls, orden, codigo, cmpempleado, getdata) VALUES (1180, 'Familiares y amigos', 1180, 'basetecnologica', NULL, 0, NULL, 'agrupador', 30, NULL, NULL, NULL);
INSERT INTO dat_proyectoconcepto (idproyectoconcepto, denominacion, idpadre, idproyecto, descripcion, tipo, propiedades, iconcls, orden, codigo, cmpempleado, getdata) VALUES (1028, 'Afiliaciones', 1027, 'basetecnologica', NULL, 1, '{"xtype":"panel","animCollapse":"false","autoHeight":"false","border":"true","collapsed":"false","collapsible":"false","disabled":"false","frame":"false","hidden":"false","split":"false","elementsByRow":"2","height":300,"anchocolumna":"","anchor":"","cmargins":"","collapseMode":"","html":"","layout":"border","margins":"","region":"","title":"Gestión de afiliaciones","width":"auto"}', 'tag', 1, '{"gSecurity":"","helpHandler":"","isDirty":"function(idpersona){\n  //Grid de afiliaciones\n  //Grid de Trayectoria de cargos\n  return Ext.getCmp(\"1029\" + this.idpadre).isDirty() && Ext.getCmp(\"1035\" + this.idpadre).isDirty();\n}\n  ","loadFn":"function(idpersona){\n  //Grid de afiliaciones\n  Ext.getCmp(\"1029\" + this.idpadre).loadGridStore({idpersona: idpersona});\n  //Grid de Trayectoria de cargos\n  Ext.getCmp(\"1035\" + this.idpadre).loadGridStore({idpersona: idpersona});\n}","saveFn":"function (btnPress)\n{\n  //Grid de afiliaciones\n  var arrAfil = Ext.getCmp(\"1029\" + this.idpadre).saveFn();\n  //Grid de Trayectoria de cargos\n  var arrCargos = Ext.getCmp(\"1035\" + this.idpadre).saveFn();\n  Ext.each(arrAfil.arrAdd, function (rec)\n           {\n             if (rec.add) {\n               rec.DatCargoorganizacion = new Array();\n               Ext.each(arrCargos.arrAdd, function (v, i)\n                        {\n                          if (v.idafiliacion === rec.idafiliacion) {\n                            rec.DatCargoorganizacion.push(v);\n                            arrCargos.arrAdd.splice(i, 1);\n                          }\n                        }, this);\n             }\n           }, this);\n\n  var url = '''';\n  if (arrAfil.arrMod.length > 0 || (arrAfil.arrDel.length > 0 && arrAfil.arrAdd.length > 0) ||\n      arrCargos.arrMod.length > 0 || (arrCargos.arrDel.length > 0 && arrCargos.arrAdd.length > 0)) {\n    url = ''modAfiliaciones'';\n  } else\n    if (arrAfil.arrDel.length > 0 || arrCargos.arrDel.length > 0) {\n      url = ''delAfiliaciones'';\n    } else {\n      url = ''addAfiliaciones'';\n    }\n\n  if (arrAfil.arrAdd.length > 0 || arrAfil.arrMod.length > 0 || arrAfil.arrDel.length > 0 ||\n      arrCargos.arrAdd.length > 0 || arrCargos.arrMod.length > 0 || arrCargos.arrDel.length > 0) {\n    Ext.sendAjax.request({\n      url: url,\n      params: {\n        arrAfil: Ext.encode(arrAfil),\n        arrCargos: Ext.encode(arrCargos),\n      },\n      success: function (response, opt, notification)\n      {\n        var dataResponse = Ext.decode(response.responseText);\n        if (dataResponse.success) {\n          if (btnPress === ''APLICAR'') { //Si el boton que ejecuto la funcion fue aplicar\n            this.loadFn(Ext.getCmp(this.idpadre).persona.idpersona);\n          }\n          var msg;\n          switch (url) {\n            case ''modAfiliaciones'':\n              msg = ''La(s) afiliación(es) ha(n) sido modificada(s) satisfactoriamente.'';\n              break;\n            case ''delAfiliaciones'':\n              msg = ''La(s) afiliación(es) ha(n) sido eliminada(s) satisfactoriamente.'';\n              break;\n            case ''addAfiliaciones'':\n              msg = ''La(s) afiliación(es) ha(n) sido adicionada(s) satisfactoriamente.'';\n              break\n          }\n          notification({\n            title: ''Informaci&oacute;n'',\n            msg: msg,\n            icon: ''ok''\n          });\n        } else {\n          switch (dataResponse.codigo) {\n            default :\n              notification({\n                title: ''Error'',\n                msg: ''Ha ocurrido un error durante la transaccion.'',\n                icon: ''error''\n              });\n              break;\n          }\n        }\n      }.createDelegate(this)\n    }, this);\n  }\n}","listeners":{"expand":"function(cmp){\n\tcmp.doLayout();\n}","focus":"","render":"","resize":"function(){\n\t//Grid Trayectoria de cargos\n  Ext.getCmp(''1035''+this.idpadre).setWidth(''50%'');\n}","show":""}}', 'null', '{"class":"DatAfiliacionModel","function":"","id":"", "project":""}');
INSERT INTO dat_proyectoconcepto (idproyectoconcepto, denominacion, idpadre, idproyecto, descripcion, tipo, propiedades, iconcls, orden, codigo, cmpempleado, getdata) VALUES (6, 'Transportación', 1, 'basetecnologica', NULL, 1, '{"xtype":"gest_panel","animCollapse":"false","autoHeight":"false","border":"true","collapsed":"false","collapsible":"false","disabled":"false","frame":"false","hidden":"false","split":"false","elementsByRow":3,"height":"","anchocolumna":"","anchor":"","cmargins":"","collapseMode":"","html":"","layout":"","margins":"","region":"","title":"Servicios de transportación","width":"auto"}', 'tag', 3, '{"columns":"[\n  {dataIndex: \"historico\", hidden:true, renderer: function(v){return (v == 0) ? ''Actual'' : ''Hist&oacute;rico'';}},\n  {header: \"Estructura de transportación\", width: 255, dataIndex: \"ruta\"},\n  {header: \"Desde\", width: 100, dataIndex: \"fdesde\"},\n  {header: \"Hasta\", width: 100, dataIndex: \"fhasta\"}\n]","addBotones":"","adicionarHandler":"","aplicarHandler":"function()\n{\n  var values = this.fpFormulario.getForm().getValues();\n  values.historico = fnHistorico(values.fdesde, values.fhasta);\n  values.denomtransportacion = Ext.getCmp(\"8\" + this.idpadre).getRawValue();\n  values.ruta = Ext.getCmp(\"8\" + this.idpadre).getRawValue();\n  values.idestructuratransportacion = Ext.getCmp(\"8\" + this.idpadre).getValue();\n  values.add = true;\n  var store = this.gpGrid.getStore();\n  var control = 0;\n  Ext.each(store.getRange(), function(rec){\n    if(rec.get(''idestructuratransportacion'') == values.idestructuratransportacion && rec.get(''historico'') == 0) {\n      control = 1;\n      return false;\n    }\n  });\n  if(control == 1) {\n    mostrarMensaje(6, ''El servicio de transportaci&oacute;n que quiere adicionar ya se encuentra activo para la persona.'');\n  } else {\n    try {\n      store.add(new Ext.data.Record(values));\n      this.cleanForm();\n    } catch(error){\n      mostrarMensaje(4, ''Ha ocurrido un error mientras se guardaba, contacte el administrador.'');\n    }\n  }\n  store.clearGrouping();\n  store.groupBy(''historico'', true);\n  function fnHistorico(fi, ff){\n    if(!Ext.isEmpty(ff)) {\n      var date = new Date();\n      date = date.format(''d/m/Y'');\n      var arrfi = fi.split(''/'');\n      var arrff = ff.split(''/'');\n      var arrfa = date.split(''/'');\n      var fi = arrfi[2] + arrfi[1] + arrfi[0];\n      var ff = arrff[2] + arrff[1] + arrff[0];\n      var fa = arrfa[2] + arrfa[1] + arrfa[0];\n      fi = parseInt(fi);\n      ff = parseInt(ff);\n      fa = parseInt(fa);\n      return (fi <= fa && fa <= ff) ? 0 : 1;\n    }\n    return 0;\n  }\n}","eliminarHandler":"function()\n{\n   var records = this.gpGrid.getSelectionModel().getSelections();\n   var ask = (records.length == 1) ? ''¿Está seguro que quiere eliminar el servicio de transportaci&oacute;n seleccionado?'' : \n    ''¿Está seguro que quiere eliminar los servicios de transportaci&oacute;n seleccionado?'';\n  mostrarMensaje(2, ask, function (btn) {\n    if (btn == ''ok'') {\n     \n      Ext.each(records, function (rec) {\n        if (!rec.data.add) {\n          this.arrDel.push(rec.get(''idservtransportacion''));\n        }\n        this.gpGrid.getStore().remove(rec);\n      }, this);\n      this.gpGrid.getView().refresh();\n    }\n  }.createDelegate(this));\n}","gSecurity":"","getLanguaje":"function(idioma)\n{\n  var lang={};\n  if(idioma===''es''){\n    lang ={\n      ttBtnAdd:\"Adicionar servicio de transportaci&oacute;n\",\n      ttBtnMod:\"Modificar servicio de transportaci&oacute;n\",\n      ttBtnDel:\"Eliminar servicio de transportaci&oacute;n\",\n      ttBtnSave:\"Guardar datos y cerrar formulario\",\n      ttBtnApl:\"Guardar datos y limpiar los campos\",\n      ttBtnCancel:\"Cerrar formulario sin guardar los datos\"\n    }\n  } else {\n    lang = {}\n  }\n  return lang;\n}","guardarHandler":"function()\n{\n  var values = this.fpFormulario.getForm().getValues();\n  values.historico = fnHistorico(values.fdesde, values.fhasta);\n  values.denomtransportacion = Ext.getCmp(\"8\" + this.idpadre).getRawValue();\n  values.ruta = Ext.getCmp(\"8\" + this.idpadre).getRawValue();\n  values.idestructuratransportacion = Ext.getCmp(\"8\" + this.idpadre).getValue();\n  \n \n  var store = this.gpGrid.getStore();\n  var control = false;\n  if(Ext.isEmpty(values.idservtransportacion)){\n    values.idservtransportacion = Ext.id();\n    values.add = true;\n    Ext.each(store.getRange(), function(rec){\n      if (rec.get(''idestructuratransportacion'') == values.idestructuratransportacion && rec.get(''historico'') == 0){\n        control = true;\n        return false;\n      }\n    });\n    if(control){\n      mostrarMensaje(6, ''El servicio de transportaci&oacute;n que quiere adicionar ya se encuentra activo para la persona.'');\n    } else {\n      try {\n        store.add(new Ext.data.Record(values));\n        this.cancelarHandler();\n      } catch(error) {\n        mostrarMensaje(6, ''Ha ocurrido un error, contacte con el administrador.'');\n      }\n    }\n  } else {\n    var reco= this.gpGrid.getSelectionModel().getSelected();  \n    var record;\n    Ext.each(store.getRange(), function(rec) {\n      \n      if(isNaN(values.idestructuratransportacion)){\n            values.idestructuratransportacion=reco.get(''idestructuratransportacion'');\n          }\n      \n      \n      if(rec.get(''idservtransportacion'') != values.idservtransportacion) {\n        if (rec.get(''idestructuratransportacion'') == values.idestructuratransportacion && rec.get(''historico'') == 0) {\n          control = true;\n          return false;\n        }\n      } else {\n        record = rec;\n      }\n      \n      \n    });\n    \n    if(control) {\n      mostrarMensaje(6, ''El servicio de transportaci&oacute;n ya se encuentra activo para la persona.'');\n    } else {\n      try {\n        for(var p in values) {\n          if (values[p] != record.get(p)) {\n            record.set(p, values[p]);\n          }\n        }\n        this.cancelarHandler();\n      } catch(error) {\n        mostrarMensaje(6, ''Ha ocurrido un error, contacte el administrador.'');\n      }\n    }\n  }\n  store.clearGrouping();\n  store.groupBy(''historico'', true);\n  function fnHistorico(fi, ff){\n    if(!Ext.isEmpty(ff)) {\n      var date = new Date();\n      date = date.format(''d/m/Y'');\n      var arrfi = fi.split(''/'');\n      var arrff = ff.split(''/'');\n      var arrfa = date.split(''/'');\n      var fi = arrfi[2] + arrfi[1] + arrfi[0];\n      var ff = arrff[2] + arrff[1] + arrff[0];\n      var fa = arrfa[2] + arrfa[1] + arrfa[0];\n      fi = parseInt(fi);\n      ff = parseInt(ff);\n      fa = parseInt(fa);\n      return (fi <= fa && fa <= ff) ? 0 : 1;\n    }\n    return 0;\n  }\n}","helpHandler":"","isDirty":"","loadFn":"function(idpersona)\n{\n  this.arrAdd = [];\n  this.arrMod = [];\n  this.arrDel = [];\n  this.loadGridStore({idpersona: idpersona});\n}","modificarHandler":"function(){  \n  var record = this.gpGrid.getSelectionModel().getSelected();  \n  this.loadFormulario(record);\n\n}","saveFn":"function(btnPress)\n{\n  var store = this.gpGrid.getStore();\n  var self = this;\n  var pass = false;\n  this.arrAdd = [];\n  this.arrMod = [];\n  Ext.each(store.getRange(), function(rec) {\n    if(rec.data.add) {\n      this.arrAdd.push(rec.data);\n    } else {\n      if(!Ext.isEmpty(rec.modified)) {\n        this.arrMod.push(rec.data);\n      }\n    }\n  }, this);\n  if(this.arrAdd.length > 0 || this.arrMod.length > 0 || this.arrDel.length > 0) {\n    Ext.sendAjax.request({\n      url: ''gestionarServTransportacion'',\n      params: {\n        arrAdd: Ext.encode(self.arrAdd),\n        arrMod: Ext.encode(self.arrMod),\n        arrDel: Ext.encode(self.arrDel)\n      },\n      success: function (response, opt, notification) {\n        var dataResponse = Ext.decode(response.responseText);\n        if(dataResponse.success) {\n          if(btnPress === ''APLICAR'') {\n            this.loadFn(Ext.getCmp(this.idpadre).persona.idpersona);\n          }\n          this.arrAdd = [];\n          this.arrMod = [];\n          this.arrDel = [];\n          mostrarMensaje(1, ''Los cambios han sido aplicados satisfactoriamente'');\n        } else {\n          mostrarMensaje(6, dataResponse.mensaje);\n        }\n      }.createDelegate(this)\n    }, this);\n  }\n}","validateForm":"function(){\n  if(this.fpFormulario.getForm().isValid()) {\n    return true;\n  } else {\n    return false;\n  }\n}","bbar":"","ptbar":"","sm":"{singleSelect: true}","store":"{\n  url: \"obtenerServTransportacionPorPersona\",\n  type: \"GroupingStore\",\n  reader: {\n    type: \"JsonReader\",\n    totalProperty: \"\",\n    root: \"data\"\n  },\n  mapping: [\n    {name: \"idservtransportacion\"},\n    {name: \"idpersona\"},   \n    {name: \"denomtransportacion\"},\n    {name: \"idestructuratransportacion\"},\n    {name: \"fdesde\"},\n    {name: \"fhasta\"},\n    {name: \"historico\"},\n    {name:\t\"ruta\"}\n  ],\n  sortInfo: {field: ''historico'', direction: \"DESC\"},\n  groupField: ''historico''\n}","view":"{\n  forceFit: true,\n  type: ''GroupingView'',\n  startCollapsed: false,\n  groupTextTpl: ''{group}''\n}","viewConfig":"","listeners":{"beforeload":"","expand":"","focus":"","load":"","render":"","resize":"","selectionchange":"","show":""}}', '{"module":"persona","component":"templates"}', '{"class":"DatServtransportacionModel","function":"","id":"", "project":""}');
INSERT INTO dat_proyectoconcepto (idproyectoconcepto, denominacion, idpadre, idproyecto, descripcion, tipo, propiedades, iconcls, orden, codigo, cmpempleado, getdata) VALUES (19, 'Alojamiento', 1, 'basetecnologica', NULL, 1, '{"xtype":"gest_panel","animCollapse":"false","autoHeight":"false","border":"true","collapsed":"false","collapsible":"false","disabled":"false","frame":"false","hidden":"false","split":"false","elementsByRow":3,"height":"","anchocolumna":"","anchor":"","cmargins":"","collapseMode":"","html":"","layout":"","margins":"","region":"","title":"Servicios de alojamiento","width":"auto"}', 'tag', 4, '{"columns":"[\n  {dataIndex: \"historico\", hidden:true, renderer: function(v){return (v == 0) ? ''Actual'' : ''Hist&oacute;rico'';}},\n  {header: \"Estructura de alojamiento\", width: 255, dataIndex: \"denomalojamiento\"},\n  {header: \"Desde\", width: 100, dataIndex: \"fdesde\"},\n  {header: \"Hasta\", width: 100, dataIndex: \"fhasta\"}\n]","addBotones":"","adicionarHandler":"","aplicarHandler":"function()\n{\n  var values = this.fpFormulario.getForm().getValues();\n  values.historico = fnHistorico(values.fdesde, values.fhasta);\n  values.denomalojamiento = Ext.getCmp(\"21\" + this.idpadre).getRawValue();\n  values.idestructuraalojamiento = Ext.getCmp(\"21\" + this.idpadre).getValue();\n  values.add = true;\n  var store = this.gpGrid.getStore();\n  var control = 0;\n  Ext.each(store.getRange(), function(rec){\n    if(rec.get(''idestructuraalojamiento'') == values.idestructuraalojamiento && rec.get(''historico'') == 0) {\n      control = 1;\n      return false;\n    }\n  });\n  if(control == 1) {\n    mostrarMensaje(6, ''El servicio de alojamiento que quiere adicionar ya se encuentra activo para la persona.'');\n  } else {\n    try {\n      store.add(new Ext.data.Record(values));\n      this.cleanForm();\n    } catch(error){\n      mostrarMensaje(4, ''Ha ocurrido un error mientras se guardaba, contacte el administrador.'');\n    }\n  }\n  store.clearGrouping();\n  store.groupBy(''historico'', true);\n  function fnHistorico(fi, ff){\n    if(!Ext.isEmpty(ff)) {\n      var date = new Date();\n      date = date.format(''d/m/Y'');\n      var arrfi = fi.split(''/'');\n      var arrff = ff.split(''/'');\n      var arrfa = date.split(''/'');\n      var fi = arrfi[2] + arrfi[1] + arrfi[0];\n      var ff = arrff[2] + arrff[1] + arrff[0];\n      var fa = arrfa[2] + arrfa[1] + arrfa[0];\n      fi = parseInt(fi);\n      ff = parseInt(ff);\n      fa = parseInt(fa);\n      return (fi <= fa && fa <= ff) ? 0 : 1;\n    }\n    return 0;\n  }\n}","eliminarHandler":"function()\n{\n  var records = this.gpGrid.getSelectionModel().getSelections();\n   var ask = (records.length == 1) ? ''¿Está seguro que quiere eliminar el servicio de alojamiento seleccionado?'' : \n    ''¿Está seguro que quiere eliminar los servicios de alojamiento seleccionados?'';\n  mostrarMensaje(2, ask, function (btn) {\n    if (btn == ''ok'') {\n      \n      Ext.each(records, function (rec) {\n        if (!rec.data.add) {\n          this.arrDel.push(rec.get(''idservalojamiento''));\n        }\n        this.gpGrid.getStore().remove(rec);\n      }, this);\n      this.gpGrid.getView().refresh();\n    }\n  }.createDelegate(this));\n}","gSecurity":"","getLanguaje":"function(idioma)\n{\n  var lang={};\n  if(idioma===''es''){\n    lang ={\n      ttBtnAdd:\"Adicionar servicio de alojamiento\",\n      ttBtnMod:\"Modificar servicio de alojamiento\",\n      ttBtnDel:\"Eliminar servicio de alojamiento\",\n      ttBtnSave:\"Guardar datos y cerrar formulario\",\n      ttBtnApl:\"Guardar datos y limpiar los campos\",\n      ttBtnCancel:\"Cerrar formulario sin guardar los datos\"\n    }\n  } else {\n    lang = {}\n  }\n  return lang;\n}","guardarHandler":"function()\n{\n  var values = this.fpFormulario.getForm().getValues();\n  values.historico = fnHistorico(values.fdesde, values.fhasta);\n  values.denomalojamiento = Ext.getCmp(\"21\" + this.idpadre).getRawValue();\n  values.idestructuraalojamiento = Ext.getCmp(\"21\" + this.idpadre).getValue();\n  var store = this.gpGrid.getStore();\n  var control = false;\n  if(Ext.isEmpty(values.idservalojamiento)){\n    values.idservalojamiento = Ext.id();\n    values.add = true;\n    Ext.each(store.getRange(), function(rec){\n      if (rec.get(''idestructuraalojamiento'') == values.idestructuraalojamiento && rec.get(''historico'') == 0){\n        control = true;\n        return false;\n      }\n    });\n    if(control){\n      mostrarMensaje(6, ''El servicio de alojamiento que quiere adicionar ya se encuentra activo para la persona.'');\n    } else {\n      try {\n        store.add(new Ext.data.Record(values));\n        this.cancelarHandler();\n      } catch(error) {\n        mostrarMensaje(6, ''Ha ocurrido un error, contacte con el administrador.'');\n      }\n    }\n  } else {\n    var reco= this.gpGrid.getSelectionModel().getSelected();  \n    var record;\n    Ext.each(store.getRange(), function(rec) {\n      \n      \n       if(isNaN(values.idestructuraalojamiento)){\n            values.idestructuraalojamiento=reco.get(''idestructuraalojamiento'');\n          }\n      \n      if(rec.get(''idservalojamiento'') != values.idservalojamiento) {\n        if (rec.get(''idestructura'') == values.idestructura && rec.get(''historico'') == 0) {\n          control = true;\n          return false;\n        }\n      } else {\n        record = rec;\n      }\n    });\n    if(control) {\n      mostrarMensaje(6, ''El servicio de alojamiento ya se encuentra activo para la persona.'');\n    } else {\n      try {\n        for(var p in values) {\n          if (values[p] != record.get(p)) {\n            record.set(p, values[p]);\n          }\n        }\n        this.cancelarHandler();\n      } catch(error) {\n        mostrarMensaje(6, ''Ha ocurrido un error, contacte el administrador.'');\n      }\n    }\n  }\n  store.clearGrouping();\n  store.groupBy(''historico'', true);\n  function fnHistorico(fi, ff){\n    if(!Ext.isEmpty(ff)) {\n      var date = new Date();\n      date = date.format(''d/m/Y'');\n      var arrfi = fi.split(''/'');\n      var arrff = ff.split(''/'');\n      var arrfa = date.split(''/'');\n      var fi = arrfi[2] + arrfi[1] + arrfi[0];\n      var ff = arrff[2] + arrff[1] + arrff[0];\n      var fa = arrfa[2] + arrfa[1] + arrfa[0];\n      fi = parseInt(fi);\n      ff = parseInt(ff);\n      fa = parseInt(fa);\n      return (fi <= fa && fa <= ff) ? 0 : 1;\n    }\n    return 0;\n  }\n}","helpHandler":"","isDirty":"","loadFn":"function(idpersona)\n{\n  this.arrAdd = [];\n  this.arrMod = [];\n  this.arrDel = [];\n  this.loadGridStore({idpersona: idpersona});\n}","modificarHandler":"","saveFn":"function(btnPress)\n{\n  var store = this.gpGrid.getStore();\n  var self = this;\n  var pass = false;\n  this.arrAdd = [];\n  this.arrMod = [];\n  Ext.each(store.getRange(), function(rec) {\n    if(rec.data.add) {\n      this.arrAdd.push(rec.data);\n    } else {\n      if(!Ext.isEmpty(rec.modified)) {\n        this.arrMod.push(rec.data);\n      }\n    }\n  }, this);\n  if(this.arrAdd.length > 0 || this.arrMod.length > 0 || this.arrDel.length > 0) {\n    Ext.sendAjax.request({\n      url: ''gestionarServAlojamiento'',\n      params: {\n        arrAdd: Ext.encode(self.arrAdd),\n        arrMod: Ext.encode(self.arrMod),\n        arrDel: Ext.encode(self.arrDel)\n      },\n      success: function (response, opt, notification) {\n        var dataResponse = Ext.decode(response.responseText);\n        if(dataResponse.success) {\n          if(btnPress === ''APLICAR'') {\n            this.loadFn(Ext.getCmp(this.idpadre).persona.idpersona);\n          }\n          this.arrAdd = [];\n          this.arrMod = [];\n          this.arrDel = [];\n          mostrarMensaje(1, ''Los cambios han sido aplicados satisfactoriamente'');\n        } else {\n          mostrarMensaje(6, dataResponse.mensaje);\n        }\n      }.createDelegate(this)\n    }, this);\n  }\n}","validateForm":"function(){\n  if(this.fpFormulario.getForm().isValid()) {\n    return true;\n  } else {\n    return false;\n  }\n}","bbar":"","ptbar":"","sm":"{singleSelect: true}","store":"{\n  url: \"obtenerServAlojamientoPorPersona\",\n  type: \"GroupingStore\",\n  reader: {\n    type: \"JsonReader\",\n    totalProperty: \"\",\n    root: \"data\"\n  },\n  mapping: [\n    {name: \"idservalojamiento\"},\n    {name: \"idpersona\"},\n    {name: \"idestructura\"},\n    {name: \"denomalojamiento\"},\n    {name: \"idestructuraalojamiento\"},\n    {name: \"fdesde\"},\n    {name: \"historico\"}\n    \n  ],\n  sortInfo: {field: ''historico'', direction: \"DESC\"},\n  groupField: ''historico''\n}","view":"{\n  forceFit: true,\n  type: ''GroupingView'',\n  startCollapsed: false,\n  groupTextTpl: ''{group}''\n}","viewConfig":"","listeners":{"beforeload":"","expand":"","focus":"","load":"","render":"","resize":"","selectionchange":"","show":""}}', '{"module":"persona","component":"templates"}', '{"class":"DatServalojamientoModel","function":"","id":"", "project":""}');
INSERT INTO dat_proyectoconcepto (idproyectoconcepto, denominacion, idpadre, idproyecto, descripcion, tipo, propiedades, iconcls, orden, codigo, cmpempleado, getdata) VALUES (101, 'Datos fenotípicos', 57, 'basetecnologica', NULL, 1, '{"xtype":"form_panel","animCollapse":"false","autoHeight":"true","border":"true","collapsed":"false","collapsible":"false","disabled":"false","frame":"true","hidden":"false","split":"false","trackResetOnLoad":"true","elementsByRow":3,"height":"","anchocolumna":"","anchor":"","buttonAlign":"right","cmargins":"","collapseMode":"","html":"","labelAlign":"top","layout":"","margins":"","region":"","title":"Datos fenotípicos","width":"auto"}', 'tag', 2, '{"gSecurity":"function(){\n  var resp = true;\n  if(Ext.isEmpty(this.getForm().getValues().idfenotipo)){\n    if(parseInt(this.segAction[0]) === 1){ //Si puede adicionar\n      resp = false;\n    }\n  }else{\n  \tif(parseInt(this.segAction[1]) === 1){//Si puede modificar\n      resp = false;\n    }\n  }\n  if(resp)\n    Ext.getCmp(\"101\" + this.idpadre).getForm().reset();\n  return resp;\n}","helpHandler":"","isDirty":"","loadFn":"function(idpersona){\n  Ext.Ajax.request({\n    url: ''getDatosFenotipicos'',\n    params: {idpersona: idpersona},\n    success: function (response, opt)\n    {\n      var dataResponse = Ext.decode(response.responseText);\n      if (dataResponse.data.length != 0) {\n        this.getForm().loadRecord(new Ext.data.Record(dataResponse.data));\n        this.getForm().findField(''idcolorojos'').setRawValue(dataResponse.data.ojos);\n        this.getForm().findField(''idcolorpiel'').setRawValue(dataResponse.data.piel);\n        this.getForm().findField(''idcolorpelo'').setRawValue(dataResponse.data.pelo);\n        this.getForm().findField(''idgruposanguineo'').setRawValue(dataResponse.data.gruposanguineo);\n      }\n    }.createDelegate(this)\n  });\n}","saveFn":"function (btnPress, close)\n{\n  //if(Ext.getCmp(\"101\" + this.idpadre).gSecurity())return; //Si devuelve TRUE es porque tiene permisos para realizar la gestion correspondiente\n    \n  if (this.getForm().isValid() && this.getForm().isDirty()) {      \n        var url = (Ext.isEmpty(this.getForm().getValues().idfenotipo)) ? ''addDatosFenotipicos'' : ''modDatosFenotipicos'';\n        Ext.sendAjax.request({\n            url: url,\n            params: this.getForm().getValues(),\n            success: function (response, opt, notification)\n            {\n                var dataResponse = Ext.decode(response.responseText);\n                if (dataResponse.success) {\n                  if(close == true) {\n                    Ext.getCmp(\"101\" + this.idpadre).ownerCt.ownerCt.removeConcept(Ext.getCmp(\"101\" + this.idpadre), true);\n                  } else\n                    if (btnPress === ''APLICAR'') { //Si el boton que ejecuto la funcion fue aplicar\n                        if (dataResponse.data) {\n                            this.getForm().loadRecord(new Ext.data.Record(dataResponse.data));\n                            this.getForm().findField(''idcolorojos'').setRawValue(dataResponse.data.ojos);\n                            this.getForm().findField(''idcolorpiel'').setRawValue(dataResponse.data.piel);\n                            this.getForm().findField(''idcolorpelo'').setRawValue(dataResponse.data.pelo);\n                            this.getForm().findField(''idgruposanguineo'').setRawValue(dataResponse.data.gruposanguineo);\n                        }\n                    }\n                    var msg = '''';\n                    switch (url) {\n                        case ''addDatosFenotipicos'':\n                            msg = ''Los datos fenotipicos se ha adicionado satisfactoriamente.'';\n                            break;\n                        case ''modDatosFenotipicos'':\n                            msg = ''Los datos fenotipicos se ha modificado satisfactoriamente.'';\n                            break;\n                    }\n                    notification({\n                        title: ''Informaci&oacute;n'',\n                        msg: msg,\n                        icon: ''ok''\n                    });\n                } else {\n                    switch (dataResponse.codigo) {\n                        default :\n                            notification({\n                                title: ''Error'',\n                                msg: ''Ha ocurrido un error durante la transaccion.'',\n                                icon: ''error''\n                            });\n                            break;\n                    }\n                }\n\n            }.createDelegate(this)\n        }, this);\n    }\n}","listeners":{"clientvalidation":"","expand":"","focus":"","render":"","resize":"","show":""}}', '{"module":"persona","component":"templates"}', '{"class":"DatFenotipoModel","function":"","id":"", "project":""}');
INSERT INTO dat_proyectoconcepto (idproyectoconcepto, denominacion, idpadre, idproyecto, descripcion, tipo, propiedades, iconcls, orden, codigo, cmpempleado, getdata) VALUES (123, 'Datos de contacto', 57, 'basetecnologica', NULL, 1, '{"xtype":"gest_panel","animCollapse":"false","autoHeight":"false","border":"true","collapsed":"false","collapsible":"false","disabled":"false","frame":"false","hidden":"false","split":"false","elementsByRow":4,"height":"","anchocolumna":"","anchor":"","cmargins":"","collapseMode":"","html":"","layout":"","margins":"","region":"","title":"Datos de contacto","width":"auto"}', 'tag', 4, '{"columns":"[\n  {header: \"Tipo contacto\", width: 150, sortable: true, dataIndex: \"denomtipocontacto\"},\n  {header: \"Medio de contacto\", width: 150, sortable: true, dataIndex: \"denomtipomediocontacto\"},\n  {header: \"Contacto\", width: 220, sortable: true, dataIndex: \"contacto\"},\n  {header: \"Principal\", width: 60, sortable: true, dataIndex: \"oficial\", renderer: function (val)\n   {\n     if (val == true) {\n       return \"<center class=''checked'' style=''width: 16px; height: 16px;''></center>\";\n     }\n     return '''';\n   }}\n]","addBotones":"","adicionarHandler":"","aplicarHandler":"function ()\n{\n    var values = this.fpFormulario.getForm().getValues();\n\n    values.denomtipocontacto = Ext.getCmp(\"125\" + this.idpadre).getRawValue();\n\n    values.denomtipomediocontacto = Ext.getCmp(\"1236\" + this.idpadre).getRawValue();\n\n    values.oficial = values.oficial == \"on\" ? true : false;\n\n    var store = this.gpGrid.getStore();\n\n    var index = -1;\n\n    if (Ext.isEmpty(values.idcontacto)) {\n        values.idcontacto = Ext.id();\n        values.add = true;\n        Ext.each(store.getRange(), function (rec)\n        {\n            if (rec.get(''idtipomediocontacto'') == values.idtipomediocontacto && rec.get(''oficial'') == values.oficial) {\n                index = ''oficial'';\n                return false;\n            }\n            if (rec.get(''contacto'') == values.contacto) {\n                index = ''contacto'';\n                return false;\n            }\n        });\n        switch (index) {\n            case ''oficial'':\n                Ext.Notification.show({\n                    title: ''Error'',\n                    msg: ''Ya se ha registrado este medio de contacto como principal.'',\n                    icon: ''error''\n                });\n                break;\n            case ''contacto'':\n                Ext.Notification.show({\n                    title: ''Error'',\n                    msg: ''El contacto que quiere adicionar ya existe.'',\n                    icon: ''error''\n                });\n                break;\n            default :\n                try {\n                    store.add(new Ext.data.Record(values));\n                    this.cleanForm();\n                } catch (error) {\n                    Ext.Notification.show({\n                        title: ''Error'',\n                        msg: ''Ha ocurrido un error mientras se guardaba, contacte el administrador.'',\n                        icon: ''error''\n                    });\n                }\n                break;\n        }\n    }\n}","eliminarHandler":"function(){\n   var records = this.gpGrid.getSelectionModel().getSelections();\n   var ask = (records.length == 1) ? ''¿Está seguro que quiere eliminar el conctacto seleccionado?'' : \n    ''¿Está seguro que quiere eliminar los conctactos seleccionados?'';\n  mostrarMensaje(2, ask, function (btn)\n                 {\n                   if (btn == ''ok'') {                  \n                     Ext.each(records, function (rec)\n                              {\n                                if (!rec.data.add) {\n                                  this.arrDel.push(rec.get(''idcontacto''));\n                                }\n                                this.gpGrid.getStore().remove(rec);\n                              }, this);\n\n                     this.gpGrid.getView().refresh();\n                   }\n                 }.createDelegate(this));\n}","gSecurity":"","getLanguaje":"function(idioma){\n  var lang={};\n if(idioma===''es''){\n     lang ={\n        ttBtnAdd:\"Adicionar dato de contacto\",\n        ttBtnMod:\"Modificar dato de contacto\",\n        ttBtnDel:\"Eliminar dato de contacto\",\n        ttBtnSave:\"Guardar datos y cerrar formulario\",\n        ttBtnApl:\"Guardar datos y limpiar los campos\",\n        ttBtnCancel:\"Cerrar formulario sin guardar los datos\"      \n\n      }  \t\n    }else{\n     lang = {\n        \n      }  \t\n      \n    }\n  return lang;\n\t\n}","guardarHandler":"function ()\n{\n    var values = this.fpFormulario.getForm().getValues();\n\n    values.denomtipocontacto = Ext.getCmp(\"125\" + this.idpadre).getRawValue();\n\n    values.denomtipomediocontacto = Ext.getCmp(\"1236\" + this.idpadre).getRawValue();\n\n    values.oficial = values.oficial == \"on\" ? true : false;\n\n    var store = this.gpGrid.getStore();\n\n    var index = -1;\n\n    if (Ext.isEmpty(values.idcontacto)) {\n        values.idcontacto = Ext.id();\n        values.add = true;\n        Ext.each(store.getRange(), function (rec)\n        {\n           if (rec.get(''idtipomediocontacto'') == values.idtipomediocontacto && rec.get(''oficial'') == values.oficial) {\n                index = ''oficial'';\n                return false;\n            }\n            if (rec.get(''contacto'') == values.contacto) {\n                index = ''contacto'';\n                return false;\n            }\n        });\n        switch (index) {\n            case ''oficial'':\n                Ext.Notification.show({\n                    title: ''Error'',\n                    msg: ''Ya se ha registrado este medio de contacto como principal.'',\n                    icon: ''error''\n                });\n                break;\n            case ''contacto'':\n                Ext.Notification.show({\n                    title: ''Error'',\n                    msg: ''El contacto que quiere adicionar ya existe.'',\n                    icon: ''error''\n                });\n                break;\n            default :\n                try {\n                    store.add(new Ext.data.Record(values));\n                    this.cancelarHandler();\n                } catch (error) {\n                    Ext.Notification.show({\n                        title: ''Error'',\n                        msg: ''Ha ocurrido un error mientras se guardaba, contacte el administrador.'',\n                        icon: ''error''\n                    });\n                }\n                break;\n        }\n    } else {\n        var record;\n        Ext.each(store.getRange(), function (rec)\n        {\n            if (rec.get(''idcontacto'') != values.idcontacto) {\n               if (rec.get(''idtipomediocontacto'') == values.idtipomediocontacto && rec.get(''oficial'') == values.oficial) {\n                    index = ''oficial'';\n                    return false;\n                }\n                if (rec.get(''contacto'') == values.contacto) {\n                    index = ''contacto'';\n                    return false;\n                }\n            } else {\n                record = rec;\n            }\n        });\n\n        switch (index) {\n            case ''oficial'':\n                Ext.Notification.show({\n                    title: ''Error'',\n                    msg: ''Ya se ha registrado este medio de contacto como principal.'',\n                    icon: ''error''\n                });\n                break;\n            case ''contacto'':\n                Ext.Notification.show({\n                    title: ''Error'',\n                    msg: ''El contacto ya existe.'',\n                    icon: ''error''\n                });\n                break;\n            default :\n                try {\n                    for (var p in values) {\n                        if (values[p] != record.get(p)) {\n                            record.set(p, values[p]);\n                        }\n                    }\n                    this.cancelarHandler();\n                } catch (error) {\n                    Ext.Notification.show({\n                        title: ''Error'',\n                        msg: ''Ha ocurrido un error mientras se modificaba, contacte el administrador.'',\n                        icon: ''error''\n                    });\n                }\n                break;\n        }\n    }\n}","helpHandler":"","isDirty":"","loadFn":"function (idpersona)\n{\n  this.arrAdd = [];\n  this.arrMod = [];\n  this.arrDel = [];\n  this.loadGridStore({idpersona: idpersona});\n}","modificarHandler":"","saveFn":"function (btnPress)\n{\n    var store = this.gpGrid.getStore();\n    var self = this;\n    var pass = false;\n    this.arrAdd = [];\n    this.arrMod = [];\n    Ext.each(store.getRange(), function (rec)\n    {\n        if (rec.data.add) {//Si es un record que se adiciono nuevo\n            this.arrAdd.push(rec.data);\n        } else {\n            if (!Ext.isEmpty(rec.modified)) {//Si el record fue modificado\n                this.arrMod.push(rec.data);\n            }\n        }\n        if (rec.get(''oficial'') == true) {\n            pass = true;\n        }\n    }, this);\n    if (!pass && this.obligatorio) {\n        Ext.Notification.show({\n            title: ''Advertencia'',\n            msg: ''La persona debe tener un contacto como principal'',\n            icon: ''warning''\n        });\n        return false;\n    }\n    if (this.arrMod.length > 0 || (this.arrDel.length > 0 && this.arrAdd.length > 0)) {\n        url = ''modContactos'';\n    } else\n        if (this.arrDel.length > 0) {\n            url = ''delContactos'';\n        } else {\n            url = ''addContactos'';\n        }\n    if (this.arrAdd.length > 0 || this.arrMod.length > 0 || this.arrDel.length > 0) {\n        Ext.sendAjax.request({\n            url: url,\n            params: {\n                arrAdd: Ext.encode(self.arrAdd),\n                arrMod: Ext.encode(self.arrMod),\n                arrDel: Ext.encode(self.arrDel)\n            },\n            success: function (response, opt, notification)\n            {\n                var dataResponse = Ext.decode(response.responseText);\n                if (dataResponse.success) {\n                    if (btnPress === ''APLICAR'') { //Si el boton que ejecuto la funcion fue aplicar\n                        this.loadFn(Ext.getCmp(this.idpadre).persona.idpersona);\n                    }\n                    this.arrAdd = [];\n                    this.arrMod = [];\n                    this.arrDel = [];\n                    var msg;\n                    switch (url) {\n                        case ''modContactos'':\n                            msg = ''El(Los) contacto(s) ha(n) sido modificado(s) satisfactoriamente.'';\n                            break;\n                        case ''delContactos'':\n                            msg = ''El(Los) contacto(s) ha(n) sido eliminado(s) satisfactoriamente.'';\n                            break;\n                        case ''addContactos'':\n                            msg = ''El(Los) contacto(s) ha(n) sido adicionado(s) satisfactoriamente.'';\n                            break\n                    }\n                    notification({\n                        title: ''Informaci&oacute;n'',\n                        msg: msg,\n                        icon: ''ok''\n                    });\n                } else {\n                    switch (dataResponse.codigo) {\n                        default :\n                            notification({\n                                title: ''Error'',\n                                msg: ''Ha ocurrido un error durante la transaccion.'',\n                                icon: ''error''\n                            });\n                            break;\n                    }\n                }\n            }.createDelegate(this)\n        }, this);\n    }\n}","validateForm":"","bbar":"","ptbar":"","sm":"{\n  type: ''RowSelectionModel'',\n    singleSelect: false\n}","store":"{\n  url: \"getContactos\",\n    type: \"Store\",\n      reader: {\n        type: \"JsonReader\",\n          totalProperty: \"quantity\",\n            root: \"data\"\n      },\n        mapping: [\n          {name: \"idcontacto\"},\n          {name: \"contacto\"},\n          {name: \"oficial\"},\n          {name: \"idtipomediocontacto\"},\n          {name: \"denomtipomediocontacto\"},\n          {name: \"idtipocontacto\"},\n          {name: \"denomtipocontacto\"},\n        ]\n}","view":"","viewConfig":"","listeners":{"beforeload":"","expand":"","focus":"","load":"","render":"","resize":"","selectionchange":"","show":""}}', '{"module":"persona","component":"templates"}', '{"class":"DatContactoModel","function":"","id":"", "project":""}');
INSERT INTO dat_proyectoconcepto (idproyectoconcepto, denominacion, idpadre, idproyecto, descripcion, tipo, propiedades, iconcls, orden, codigo, cmpempleado, getdata) VALUES (873, 'Nacionalidades', 57, 'basetecnologica', NULL, 1, '{"xtype":"gest_panel","animCollapse":"false","autoHeight":"false","border":"true","collapsed":"false","collapsible":"false","disabled":"false","frame":"false","hidden":"false","split":"false","elementsByRow":4,"height":"","anchocolumna":"","anchor":"","cmargins":"","collapseMode":"","html":"","layout":"","margins":"","region":"","title":"Nacionalidades","width":"auto"}', 'tag', 6, '{"columns":"[  \n  {header: \"Nacionalidad\",\n   width: 180, \n   sortable: true,\n   resizable:false, \n   dataIndex: \"denomnacionalidad\",\n   renderer: function (value, meta, record) {\n     return \"<div class=''flags_img \" + record.get(''bandera'') + \"'' style=''width: 16px; height: 16px;''><p style=''margin-left: 20px; margin-top: 2px;''>\" + value + \"</p></div>\";\n   }\n  },\n  {header: \"Desde\", width: 100, sortable: true,resizable:false, dataIndex: \"fdesde\"},\n  {header: \"Hasta\", width: 100, sortable: true,resizable:false, dataIndex: \"fhasta\"},\n  {header: \"Activa\", hidden: true, sortable: true, dataIndex: \"activa\", renderer: function (v)\n   {\n     return (v == 1) ? ''Nacionalidad activa'' : ''Nacionalidades pasivas'';\n   }}\n]","addBotones":"","adicionarHandler":"","aplicarHandler":"function ()\n{\n    var values = this.fpFormulario.getForm().getValues();\n    values.denomnacionalidad = Ext.getCmp(\"875\" + this.idpadre).getRawValue();\n    values.bandera = Ext.getCmp(\"875\" + this.idpadre).findRecord(\"idnacionalidad\", values.idnacionalidad).get(\"bandera\");\n    values.activa = (Ext.getCmp(\"1311\" + this.idpadre).checked) ? 1 : 0;\n\n    var store = this.gpGrid.getStore();\n    var index = -1;\n    if (Ext.isEmpty(values.idnacionalidadp)) {//Si es vacio es porke estoy adicionando\n        values.idnacionalidadp = Ext.id();\n        values.add = true;\n        Ext.each(store.getRange(), function (rec)\n        {\n            if (rec.get(''idnacionalidad'') == values.idnacionalidad) {\n                index = ''Nacionalidad'';\n                return false;\n            }\n        });\n        switch (index) {\n            case ''Nacionalidad'':\n                Ext.Notification.show({\n                    title: ''Error'',\n                    //msg: ''Ya existe una nacionalidad con esta denominaci&oacute;n: <b>'' + values.denomnacionalidad + ''</b>.'',\n                  \tmsg: ''La nacionalidad que quiere adicionar ya existe.'',\n                    icon: ''error''\n                });\n                break\n            default:\n                try {\n                    store.add(new Ext.data.Record(values));\n                    this.cleanForm();\n                } catch (error) {\n                    Ext.Notification.show({\n                        title: ''Error'',\n                        msg: ''Ha ocurrido un error mientras se guardaba, contacte el administrador.'',\n                        icon: ''error''\n                    });\n                }\n                break;\n        }\n    }\n}","eliminarHandler":"function ()\n{\n   var records = this.gpGrid.getSelectionModel().getSelections();\n   var ask = (records.length == 1) ? ''¿Está seguro que quiere eliminar la nacionalidad seleccionada?'' : \n    ''¿Está seguro que quiere eliminar las nacionalidades seleccionadas?'';\n\tmostrarMensaje(2, ask, function (btn)\n        {\n            if (btn == ''ok'') {\n              \n                Ext.each(records, function (rec)\n                {\n                    if (!rec.data.add) {\n                        this.arrDel.push(rec.get(''idnacionalidadp''));\n                    }\n                    this.gpGrid.getStore().remove(rec);\n                }, this);\n\n                this.gpGrid.getView().refresh();\n            }\n        }.createDelegate(this));\n}","gSecurity":"","getLanguaje":"function(idioma){\n  var lang={};\n if(idioma===''es''){\n     lang ={\n        ttBtnAdd:\"Adicionar nacionalidad\",\n        ttBtnMod:\"Modificar nacionalidad\",\n        ttBtnDel:\"Eliminar nacionalidad\",\n        ttBtnSave:\"Guardar datos y cerrar formulario\",\n        ttBtnApl:\"Guardar datos y limpiar los campos\",\n        ttBtnCancel:\"Cerrar formulario sin guardar los datos\"      \n\n      }  \t\n    }else{\n     lang = {\n        \n      }  \t\n      \n    }\n  return lang;\n\t\n}","guardarHandler":"function ()\n{\n    var values = this.fpFormulario.getForm().getValues();\n    values.denomnacionalidad = Ext.getCmp(\"875\" + this.idpadre).getRawValue();\n    values.bandera = Ext.getCmp(\"875\" + this.idpadre).findRecord(\"idnacionalidad\", values.idnacionalidad).get(\"bandera\");\n    values.activa = (Ext.getCmp(\"1311\" + this.idpadre).checked) ? 1 : 0;\n\n    var store = this.gpGrid.getStore();\n    var index = -1;\n    if (Ext.isEmpty(values.idnacionalidadp)) {//Si es vacio es porke estoy adicionando\n        values.idnacionalidadp = Ext.id();\n        values.add = true;\n        Ext.each(store.getRange(), function (rec)\n        {\n            if (rec.get(''idnacionalidad'') == values.idnacionalidad) {\n                index = ''Nacionalidad'';\n                return false;\n            }\n        });\n        switch (index) {\n            case ''Nacionalidad'':\n                Ext.Notification.show({\n                    title: ''Error'',\n                    msg: ''La nacionalidad que quiere adicionar ya existe.'',\n                    icon: ''error''\n                });\n                break\n            default:\n                try {\n                    store.add(new Ext.data.Record(values));\n                    this.cancelarHandler();\n                } catch (error) {\n                    Ext.Notification.show({\n                        title: ''Error'',\n                        msg: ''Ha ocurrido un error mientras se guardaba, contacte el administrador.'',\n                        icon: ''error''\n                    });\n                }\n                break;\n        }\n    } else {\n        var record;\n        //Iteracion para validar la modificacion y obtener el record a modificar\n        Ext.each(store.getRange(), function (rec, i)\n        {\n            if (rec.get(''idnacionalidadp'') == values.idnacionalidadp) { //Si  es el que se va a modificar\n                record = rec; //Obtengo el record que se va a modificar\n            } else\n                if (rec.get(''idnacionalidad'') == values.idnacionalidad) {\n                    index = ''Nacionalidad'';\n                }\n        });\n        switch (index) {\n            case ''Nacionalidad'':\n                Ext.Notification.show({\n                    title: ''Error'',\n                    msg: ''La nacionalidad ya existe.'',\n                    icon: ''error''\n                });\n                break\n            default:\n                try {\n                    for (var p in values) {\n                        if (values[p] != record.get(p)) {\n                            record.set(p, values[p]);\n                        }\n                    }\n                    this.cancelarHandler();\n                } catch (error) {\n                    Ext.Notification.show({\n                        title: ''Error'',\n                        msg: ''Ha ocurrido un error mientras se modificaba, contacte el administrador.'',\n                        icon: ''error''\n                    });\n                }\n                break;\n        }\n    }\n}","helpHandler":"","isDirty":"","loadFn":"function (idpersona)\n{\n  this.arrAdd = [];\n  this.arrMod = [];\n  this.arrDel = [];\n  this.loadGridStore({idpersona: idpersona});\n}","modificarHandler":"","saveFn":" function (btnPress) {\n   var self = this;\n   var store = this.gpGrid.getStore();\n   var pass = false;\n   this.arrAdd = [];\n   this.arrMod = [];\n   Ext.each(store.getRange(), function (rec)\n            {\n              if (rec.data.add) {//Si es un record que se adiciono nuevo\n                this.arrAdd.push(rec.data);\n              } else {\n                if (!Ext.isEmpty(rec.modified)) {//Si el record fue modificado\n                  this.arrMod.push(rec.data);\n                }\n              }\n              pass = true;\n            }, this);\n   if (!pass && this.obligatorio) {\n     Ext.Notification.show({\n       title: ''Advertencia'',\n       msg: ''La persona debe tener alguna nacionalidad registrada'',\n       icon: ''warning''\n     });\n     return false;\n   }\n   var url = '''';\n   if (this.arrMod.length > 0 || (this.arrDel.length > 0 && this.arrAdd.length > 0)) {\n     url = ''changeNationalitys'';\n   } else\n     if (this.arrDel.length > 0) {\n       url = ''removeNationalitys'';\n     } else {\n       url = ''addNationalitys'';\n     }\n   if (this.arrAdd.length > 0 || this.arrMod.length > 0 || this.arrDel.length > 0) {\n     Ext.sendAjax.request({\n       url: url,\n       params: {\n         arrAdd: Ext.encode(self.arrAdd),\n         arrMod: Ext.encode(self.arrMod),\n         arrDel: Ext.encode(self.arrDel)\n       },\n       success: function (response, opt, notification)\n       {\n         var dataResponse = Ext.decode(response.responseText);\n         if (dataResponse.success) {\n           if (btnPress === ''APLICAR'') { //Si el boton que ejecuto la funcion fue aplicar\n             this.loadFn(Ext.getCmp(this.idpadre).persona.idpersona);\n           }\n           this.arrAdd = [];\n           this.arrMod = [];\n           this.arrDel = [];\n           var msg;\n           switch (url) {\n             case ''changeNationalitys'':\n               msg = ''La(s) nacionalidad(es) ha(n) sido modificada(s) satisfactoriamente.'';\n               break;\n             case ''removeNationalitys'':\n               msg = ''La(s) nacionalidad(es) ha(n) sido eliminada(s) satisfactoriamente.'';\n               break;\n             case ''addNationalitys'':\n               msg = ''La(s) nacionalidad(es) ha(n) sido adicionada(s) satisfactoriamente.'';\n               break\n           }\n           notification({\n             title: ''Informaci&oacute;n'',\n             msg: msg,\n             icon: ''ok''\n           });\n         } else {\n           switch (dataResponse.codigo) {\n             case 23503:\n               notification({\n                 title: ''Error'',\n                 msg: ''No se puede eliminar debido a que est&aacute; en uso.'',\n                 icon: ''error''\n               });\n               break;\n             default :\n               notification({\n                 title: ''Error'',\n                 msg: ''Ha ocurrido un error durante la transaccion.'',\n                 icon: ''error''\n               });\n               break;\n           }\n         }\n       }.createDelegate(this)\n     }, this);\n   }\n }","validateForm":"function () {\n  if (this.fpFormulario.getForm().isValid()) {\n    return true;\n  } else {\n    return false;\n  }\n}","bbar":"","ptbar":"","sm":"{\n  type:''RowSelectionModel'',\n  singleSelect: false\n}","store":"{\n  url: \"getNationalityByIdperson\",\n  type: \"GroupingStore\",\n  reader: {\n    type: \"JsonReader\",\n    totalProperty: \"quantity\",\n    root: \"data\"\n  },\n  mapping: [\n    {name: \"idnacionalidadp\"},\n    {name: \"idnacionalidad\"},\n    {name: \"denomnacionalidad\"},\n    {name: \"fdesde\"},\n    {name: \"fhasta\"},\n    {name: \"bandera\"},\n    {name: \"activa\"}\n  ],\n  sortInfo: {field: ''activa'', direction: \"DESC\"},\n  groupField: ''activa''\n}","view":"{\n  type: ''GroupingView'',\n  groupTextTpl: ''{group}''\n}","viewConfig":"","listeners":{"beforeload":"","expand":"","focus":"","load":"","render":"","resize":"","selectionchange":"","show":""}}', '{"module":"persona","component":"templates"}', '{"class":"DatNacionalidadModel","function":"","id":"", "project":""}');
INSERT INTO dat_proyectoconcepto (idproyectoconcepto, denominacion, idpadre, idproyecto, descripcion, tipo, propiedades, iconcls, orden, codigo, cmpempleado, getdata) VALUES (1054, 'Estado de salud', 1053, 'basetecnologica', NULL, 1, '{"xtype":"panel","animCollapse":"false","autoHeight":"false","border":"true","collapsed":"false","collapsible":"false","disabled":"false","frame":"true","hidden":"false","split":"false","elementsByRow":"2","height":300,"anchocolumna":"","anchor":"","cmargins":"","collapseMode":"","html":"","layout":"border","margins":"","region":"","title":"Estado de salud","width":"auto"}', 'tag', 1, '{"gSecurity":"","helpHandler":"","isDirty":"function(idpersona){\n  //Grid de Padecimientos\n  //Formulario de estado de salud\n  return Ext.getCmp(\"1055\" + this.idpadre).isDirty() && Ext.getCmp(\"1061\" + this.idpadre).isDirty();\n}","loadFn":"function(idpersona){\n  //Grid de afecciones\n  Ext.getCmp(\"1055\" + this.idpadre).loadFn(idpersona);\n  //Formulario de estado de salud\n  Ext.getCmp(\"1061\" + this.idpadre).loadFn(idpersona);\n}","saveFn":"function (btnPress)\n{\n  //Grid de afecciones\n  var arrAfec = Ext.getCmp(\"1055\" + this.idpadre).saveFn();\n  //Formulario de estados de salud\n  var dataForm = Ext.getCmp(\"1061\" + this.idpadre).saveFn();\n  \n  var url = '''';\n  if (arrAfec.arrMod.length > 0 || (arrAfec.arrDel.length > 0 && arrAfec.arrAdd.length > 0) ||\n      dataForm.arrMod.length > 0) {\n    url = ''modAllDatosSalud'';\n  } else\n    if (arrAfec.arrDel.length > 0) {\n      url = ''delAllDatosSalud'';\n    } else {\n      url = ''addAllDatosSalud'';\n    }\n\n  if (arrAfec.arrAdd.length > 0 || arrAfec.arrMod.length > 0 || arrAfec.arrDel.length > 0 ||\n      dataForm.arrAdd.length > 0 || dataForm.arrMod.length > 0) {\n    Ext.sendAjax.request({\n      url: url,\n      params: {\n        arrAfec: Ext.encode(arrAfec),\n        dataForm: Ext.encode(dataForm),\n      },\n      success: function (response, opt, notification)\n      {\n        var dataResponse = Ext.decode(response.responseText);\n        if (dataResponse.success) {\n          if (btnPress === ''APLICAR'') { //Si el boton que ejecuto la funcion fue aplicar\n            this.loadFn(Ext.getCmp(this.idpadre).persona.idpersona);\n          }\n          var msg;\n          switch (url) {\n            case ''modAllDatosSalud'':\n              msg = ''El(Los) dato(s) de salud ha(n) sido modificado(s) satisfactoriamente.'';\n              break;\n            case ''delAllDatosSalud'':\n              msg = ''El(Los) dato(s) de salud ha(n) sido eliminado(s) satisfactoriamente.'';\n              break;\n            case ''addAllDatosSalud'':\n              msg = ''El(Los) dato(s) de salud ha(n) sido adicionado(s) satisfactoriamente.'';\n              break\n          }\n          notification({\n            title: ''Informaci&oacute;n'',\n            msg: msg,\n            icon: ''ok''\n          });\n        } else {\n          switch (dataResponse.codigo) {\n            default :\n              notification({\n                title: ''Error'',\n                msg: ''Ha ocurrido un error durante la transacción.'',\n                icon: ''error''\n              });\n              break;\n          }\n        }\n      }.createDelegate(this)\n    }, this);\n  }\n}","listeners":{"expand":"function(cmp){\n\tcmp.doLayout();\n}","focus":"","render":"","resize":"","show":""}}', 'null', '{"class":"DatAfeccionModel","function":"","id":"", "project":""}');
INSERT INTO dat_proyectoconcepto (idproyectoconcepto, denominacion, idpadre, idproyecto, descripcion, tipo, propiedades, iconcls, orden, codigo, cmpempleado, getdata) VALUES (1086, 'Categorías científicas', 1066, 'basetecnologica', NULL, 1, '{"xtype":"gest_panel","animCollapse":"false","autoHeight":"false","border":"true","collapsed":"false","collapsible":"false","disabled":"false","frame":"false","hidden":"false","split":"false","elementsByRow":"2","height":"","anchocolumna":"","anchor":"","cmargins":"","collapseMode":"","html":"","layout":"","margins":"","region":"","title":"Categorías científicas","width":"auto"}', 'tag', 1, '{"columns":"[\n  {header: \"Tipo de categoría\", width: 220, sortable: true, dataIndex: \"denomtipocategoria\"},\n  {header: \"Categor&iacute;a\", width: 220, sortable: true, dataIndex: \"denomcategoria\"},  \n  {header: \"Desde\", width: 100, sortable: true, dataIndex: \"fdesde\"},\n  {header: \"Hasta\", width: 100, sortable: true, dataIndex: \"fhasta\"}\n]","addBotones":"","adicionarHandler":"","aplicarHandler":"function ()\n{\n    var values = this.fpFormulario.getForm().getValues();\n\t//Obteniendo la denominacion del tipo de categoria selecionada\n    values.denomtipocategoria = Ext.getCmp(\"1088\" + this.idpadre) ? Ext.getCmp(\"1088\" + this.idpadre).getRawValue():'''';\n\n    values.denomcategoria = Ext.getCmp(\"1089\" + this.idpadre).getRawValue();\n\n    var store = this.gpGrid.getStore();\n\n    var index = -1;\n\n    if (Ext.isEmpty(values.idcategorizacion)) {\n        values.idcategorizacion = Ext.id();\n        values.add = true;\n        Ext.each(store.getRange(), function (rec)\n        {\n            if (rec.get(''idcategoria'') == values.idcategoria) {\n                index = ''categoria'';\n                return false;\n            }\n        });\n\n        switch (index) {\n            case ''categoria'':\n                Ext.Notification.show({\n                    title: ''Error'',\n                    msg: ''La categoría científica que quiere adicionar ya existe.'',\n                    icon: ''error''\n                });\n                break;\n            default :\n                try {\n                    store.add(new Ext.data.Record(values));\n                    this.cleanForm();\n                } catch (error) {\n                    Ext.Notification.show({\n                        title: ''Error'',\n                        msg: ''Ha ocurrido un error mientras se guardaba, contacte el administrador.'',\n                        icon: ''error''\n                    });\n                }\n                break;\n        }\n    }\n}","eliminarHandler":"function ()\n{\n   var records = this.gpGrid.getSelectionModel().getSelections();\n   var ask = (records.length == 1) ? ''¿Está seguro que quiere eliminar la categor&iacute;a seleccionada?'' : \n    ''¿Está seguro que quiere eliminar las categor&iacute;as seleccionadas?'';\n\tmostrarMensaje(2, ask, function (btn)\n        {\n            if (btn == ''ok'') {                \n                Ext.each(records, function (rec)\n                {\n                    if (!rec.data.add) {\n                        this.arrDel.push(rec.get(''idcategorizacion''));\n                    }\n                    this.gpGrid.getStore().remove(rec);\n                }, this);\n\n                this.gpGrid.getView().refresh();\n            }\n        }.createDelegate(this));\n}","gSecurity":"","getLanguaje":"function(idioma){\n  var lang={};\n if(idioma===''es''){\n     lang ={\n        ttBtnAdd:\"Adicionar categoría científica\",\n        ttBtnMod:\"Modificar categoría científica\",\n        ttBtnDel:\"Eliminar categoría científica\",\n        ttBtnSave:\"Guardar datos y cerrar formulario\",\n        ttBtnApl:\"Guardar datos y limpiar los campos\",\n        ttBtnCancel:\"Cerrar formulario sin guardar los datos\"      \n\n      }  \t\n    }else{\n     lang = {\n        \n      }  \t\n      \n    }\n  return lang;\n\t\n}","guardarHandler":"function ()\n{\n    var values = this.fpFormulario.getForm().getValues();\n\t//Obteniendo la denominacion del tipo de categoria selecionada\n    values.denomtipocategoria = Ext.getCmp(\"1088\" + this.idpadre) ? Ext.getCmp(\"1088\" + this.idpadre).getRawValue():'''';\n\n    values.denomcategoria = Ext.getCmp(\"1089\" + this.idpadre).getRawValue();\n\n    var store = this.gpGrid.getStore();\n\n    var index = -1;\n\n    if (Ext.isEmpty(values.idcategorizacion)) {\n        values.idcategorizacion = Ext.id();\n        values.add = true;\n        Ext.each(store.getRange(), function (rec)\n        {\n            if (rec.get(''idcategoria'') == values.idcategoria) {\n                index = ''categoria'';\n                return false;\n            }\n        });\n\n        switch (index) {\n            case ''categoria'':\n                Ext.Notification.show({\n                    title: ''Error'',\n                    msg: ''La categoría científica que quiere adicionar ya existe.'',\n                    icon: ''error''\n                });\n                break;\n            default :\n                try {\n                    store.add(new Ext.data.Record(values));\n                    this.cancelarHandler();\n                } catch (error) {\n                    Ext.Notification.show({\n                        title: ''Error'',\n                        msg: ''Ha ocurrido un error mientras se guardaba, contacte el administrador.'',\n                        icon: ''error''\n                    });\n                }\n                break;\n        }\n    } else {\n        var record;\n        Ext.each(store.getRange(), function (rec)\n        {\n            if (rec.get(''idcategorizacion'') != values.idcategorizacion) {                \n                if (rec.get(''idcategoria'') == values.idcategoria) {\n                \tindex = ''categoria'';\n                \treturn false;\n            \t}\n            } else {\n                record = rec;\n            }\n        });\n        switch (index) {\n            case ''categoria'':\n                Ext.Notification.show({\n                    title: ''Error'',\n                    msg: ''La categoría científica ya existe.'',\n                    icon: ''error''\n                });\n                break;\n            default :\n                try {\n                    for (var p in values) {\n                        if (values[p] != record.get(p)) {\n                            record.set(p, values[p]);\n                        }\n                    }\n                    this.cancelarHandler();\n                } catch (error) {\n                    Ext.Notification.show({\n                        title: ''Error'',\n                        msg: ''Ha ocurrido un error mientras se modificaba, contacte el administrador'',\n                        icon: ''error''\n                    });\n                }\n                break;\n        }\n    }\n}","helpHandler":"","isDirty":"","loadFn":"function (idpersona) {\n  this.arrAdd = [];\n  this.arrMod = [];\n  this.arrDel = [];\n  this.loadGridStore({idpersona: idpersona});\n}","modificarHandler":"","saveFn":"function (btnPress) {\n   var self = this;\n   var store = this.gpGrid.getStore();\n   var pass = false;\n   this.arrAdd = [];\n   this.arrMod = [];\n   Ext.each(store.getRange(), function (rec)\n            {\n              if (rec.data.add) {//Si es un record que se adiciono nuevo\n                this.arrAdd.push(rec.data);\n              } else {\n                if (!Ext.isEmpty(rec.modified)) {//Si el record fue modificado\n                  this.arrMod.push(rec.data);\n                }\n              }\n              pass = true;\n            }, this);\n   if (!pass && this.obligatorio) {\n     Ext.Notification.show({\n       title: ''Advertencia'',\n       msg: ''La categoría científica que quiere adicionar ya existe.'',\n       icon: ''warning''\n     });\n     return false;\n   }\n   var url = '''';\n   if (this.arrMod.length > 0 || (this.arrDel.length > 0 && this.arrAdd.length > 0)) {\n     url = ''modCategoriasCientificasPersona'';\n   } else\n     if (this.arrDel.length > 0) {\n       url = ''delCategoriasCientificasPersona'';\n     } else {\n       url = ''addCategoriasCientificasPersona'';\n     }\n   if (this.arrAdd.length > 0 || this.arrMod.length > 0 || this.arrDel.length > 0) {\n     Ext.sendAjax.request({\n       url: url,\n       params: {\n         arrAdd: Ext.encode(self.arrAdd),\n         arrMod: Ext.encode(self.arrMod),\n         arrDel: Ext.encode(self.arrDel)\n       },\n       success: function (response, opt, notification)\n       {\n         var dataResponse = Ext.decode(response.responseText);\n         if (dataResponse.success) {\n           if (btnPress === ''APLICAR'') { //Si el boton que ejecuto la funcion fue aplicar\n             this.loadFn(Ext.getCmp(this.idpadre).persona.idpersona);\n           }\n           this.arrAdd = [];\n           this.arrMod = [];\n           this.arrDel = [];\n           var msg;\n           switch (url) {\n             case ''modCategoriasCientificasPersona'':\n               msg = ''La(s) categoría(s) científica(s) ha(n) sido modificada(s) satisfactoriamente.'';\n               break;\n             case ''delCategoriasCientificasPersona'':\n               msg = ''La(s) categoría(s) científica(s) ha(n) sido eliminada(s) satisfactoriamente.'';\n               break;\n             case ''addCategoriasCientificasPersona'':\n               msg = ''La(s) categoría(s) científica(s) ha(n) sido adicionada(s) satisfactoriamente.'';\n               break\n           }\n           notification({\n             title: ''Informaci&oacute;n'',\n             msg: msg,\n             icon: ''ok''\n           });\n         } else {\n           switch (dataResponse.codigo) {\n             case 23503:\n               notification({\n                 title: ''Error'',\n                 msg: ''No se puede eliminar debido a que est&aacute; en uso.'',\n                 icon: ''error''\n               });\n               break;\n             default :\n               notification({\n                 title: ''Error'',\n                 msg: ''Ha ocurrido un error durante la transaccion.'',\n                 icon: ''error''\n               });\n               break;\n           }\n         }\n       }.createDelegate(this)\n     }, this);\n   }\n }","validateForm":"","bbar":"","ptbar":"","sm":"{\n  type: \"CheckboxSelectionModel\",\n  singleSelect: false\n}","store":"{\n  url: \"getCategoriasCientificasByPersona\",\n    type: \"Store\",\n      baseParams: {\n            value: 1\n        },\n      reader: {\n        type: \"JsonReader\",\n          totalProperty: \"quantity\",\n            root: \"data\"\n      },\n        mapping: [\n          {name: \"idcategorizacion\"},\n          {name: \"idcategoria\"},\n          {name: \"denomcategoria\"},\n          {name: \"idtipocategoria\"},\n          {name: \"denomtipocategoria\"},\n          {name: \"fdesde\"},\n          {name: \"fhasta\"}\n        ]\n}","view":"","viewConfig":"","listeners":{"beforeload":"","expand":"","focus":"","load":"","render":"","resize":"","selectionchange":"","show":""}}', '{"module":"persona","component":"templates"}', '{"class":"DatCategorizacioncientificaModel","function":"","id":"", "project":""}');
INSERT INTO dat_proyectoconcepto (idproyectoconcepto, denominacion, idpadre, idproyecto, descripcion, tipo, propiedades, iconcls, orden, codigo, cmpempleado, getdata) VALUES (1142, 'Datos de tallaje', 1118, 'basetecnologica', NULL, 1, '{"xtype":"gest_panel","animCollapse":"false","autoHeight":"false","border":"true","collapsed":"false","collapsible":"false","disabled":"false","frame":"false","hidden":"false","split":"false","elementsByRow":3,"height":"","anchocolumna":"","anchor":"","cmargins":"","collapseMode":"","html":"","layout":"","margins":"","region":"","title":"Datos de tallaje","width":"auto"}', 'tag', 2, '{"columns":"[\n  {header: \"Prenda\", width: 220, sortable: true, dataIndex: \"denomprenda\"},\n  {header: \"Norma\", width: 220, sortable: true, dataIndex: \"denomnorma\"},  \n  {header: \"Talla\", width: 100, sortable: true, dataIndex: \"denomtalla\"} \n]","addBotones":"","adicionarHandler":"","aplicarHandler":"function ()\n{\n    var values = this.fpFormulario.getForm().getValues();\n\t//Obteniendo la denominacion de la talla selecionada\n    values.denomtalla = Ext.getCmp(\"1146\" + this.idpadre).getRawValue();\n\t//Obteniendo la denominacion de la prenda selecionada\n    values.denomprenda = Ext.getCmp(\"1144\" + this.idpadre).getRawValue();\n  \t//Obteniendo la denominacion de la norma selecionada\n    values.denomnorma = Ext.getCmp(\"1145\" + this.idpadre).getRawValue();\n\n    var store = this.gpGrid.getStore();\n\n    var index = -1;\n\n    if (Ext.isEmpty(values.idtallaje)) {\n        values.idtallaje = Ext.id();\n        values.add = true;\n        Ext.each(store.getRange(), function (rec)\n        {\n            if (rec.get(''idprenda'') == values.idprenda) {\n                index = ''prenda'';\n                return false;\n            }\n        });\n\n        switch (index) {\n            case ''prenda'':\n                Ext.Notification.show({\n                    title: ''Error'',\n                    msg: ''El dato de tallaje que quiere adicionar ya existe.'',\n                    icon: ''error''\n                });\n                break;\n            default :\n                try {\n                    store.add(new Ext.data.Record(values));\n                    this.cleanForm();\n                } catch (error) {\n                    Ext.Notification.show({\n                        title: ''Error'',\n                        msg: ''Ha ocurrido un error mientras se guardaba, contacte el administrador.'',\n                        icon: ''error''\n                    });\n                }\n                break;\n        }\n    }\n}","eliminarHandler":"function(){  \n  \tvar records = this.gpGrid.getSelectionModel().getSelections();\n   \tvar ask = (records.length == 1) ? ''¿Está seguro que quiere eliminar el dato de tallaje seleccionado?'' : \n    ''¿Está seguro que quiere eliminar los datos de tallaje seleccionados?'';\n  \n\tmostrarMensaje(2, ask, function (btn)\n        {\n            if (btn == ''ok'') {\n\n                var records = this.gpGrid.getSelectionModel().getSelections();\n                Ext.each(records, function (rec)\n                {\n                    if (!rec.data.add) {\n                        this.arrDel.push(rec.get(''idtallaje''));\n                    }\n                    this.gpGrid.getStore().remove(rec);\n                }, this);\n                this.gpGrid.getView().refresh();\n            }\n        }.createDelegate(this));\n}","gSecurity":"","getLanguaje":"function(idioma){\n  var lang={};\n if(idioma===''es''){\n     lang ={\n        ttBtnAdd:\"Adicionar datos de tallaje\",\n        ttBtnMod:\"Modificar datos de tallaje\",\n        ttBtnDel:\"Eliminar datos de tallaje\",\n        ttBtnSave:\"Guardar datos y cerrar formulario\",\n        ttBtnApl:\"Guardar datos y limpiar los campos\",\n        ttBtnCancel:\"Cerrar formulario sin guardar los datos\"      \n\n      }  \t\n    }else{\n     lang = {\n        \n      }  \t\n      \n    }\n  return lang;\n\t\n}","guardarHandler":"function ()\n{\n    var values = this.fpFormulario.getForm().getValues();\n\t//Obteniendo la denominacion de la talla selecionada\n    values.denomtalla = Ext.getCmp(\"1146\" + this.idpadre).getRawValue();\n\t//Obteniendo la denominacion de la prenda selecionada\n    values.denomprenda = Ext.getCmp(\"1144\" + this.idpadre).getRawValue();\n  \t//Obteniendo la denominacion de la norma selecionada\n    values.denomnorma = Ext.getCmp(\"1145\" + this.idpadre).getRawValue();\n\n    var store = this.gpGrid.getStore();\n\n    var index = -1;\n\n    if (Ext.isEmpty(values.idtallaje)) {\n        values.idtallaje = Ext.id();\n        values.add = true;\n        Ext.each(store.getRange(), function (rec)\n        {\n            if (rec.get(''idprenda'') == values.idprenda) {\n                index = ''prenda'';\n                return false;\n            }\n        });\n\n        switch (index) {\n            case ''prenda'':\n                Ext.Notification.show({\n                    title: ''Error'',\n                    //msg: ''La prenda <b>'' + values.denomprenda + ''</b> ya se ha registrado.'',\n                  \tmsg: ''El dato de tallaje que quiere adicionar ya existe.'',\n                    icon: ''error''\n                });\n                break;\n            default :\n                try {\n                    store.add(new Ext.data.Record(values));\n                    this.cancelarHandler();\n                } catch (error) {\n                    Ext.Notification.show({\n                        title: ''Error'',\n                        msg: ''Ha ocurrido un error mientras se guardaba, contacte el administrador.'',\n                        icon: ''error''\n                    });\n                }\n                break;\n        }\n    } else {\n        var record;\n        Ext.each(store.getRange(), function (rec)\n        {\n            if (rec.get(''idtallaje'') != values.idtallaje) {                \n                if (rec.get(''idprenda'') == values.idprenda) {\n                \tindex = ''prenda'';\n                \treturn false;\n            \t}\n            } else {\n                record = rec;\n            }\n        });\n        switch (index) {\n            case ''prenda'':\n                Ext.Notification.show({\n                    title: ''Error'',\n                    msg: ''El dato de tallaje ya existe.'',\n                    icon: ''error''\n                });\n                break;\n            default :\n                try {\n                    for (var p in values) {\n                        if (values[p] != record.get(p)) {\n                            record.set(p, values[p]);\n                        }\n                    }\n                    this.cancelarHandler();\n                } catch (error) {\n                    Ext.Notification.show({\n                        title: ''Error'',\n                        msg: ''Ha ocurrido un error mientras se modificaba, contacte el administrador'',\n                        icon: ''error''\n                    });\n                }\n                break;\n        }\n    }\n}","helpHandler":"","isDirty":"","loadFn":"function(idpersona){\n  this.arrAdd = [];\n  this.arrMod = [];\n  this.arrDel = [];\n  this.loadGridStore({idpersona: idpersona});\n}","modificarHandler":"","saveFn":"function (btnPress) {\n   var self = this;\n   var store = this.gpGrid.getStore();\n   var pass = false;\n   this.arrAdd = [];\n   this.arrMod = [];\n   Ext.each(store.getRange(), function (rec)\n            {\n              if (rec.data.add) {//Si es un record que se adiciono nuevo\n                this.arrAdd.push(rec.data);\n              } else {\n                if (!Ext.isEmpty(rec.modified)) {//Si el record fue modificado\n                  this.arrMod.push(rec.data);\n                }\n              }\n              pass = true;\n            }, this);\n   if (!pass && this.obligatorio) {\n     Ext.Notification.show({\n       title: ''Advertencia'',\n       msg: ''La persona debe tener alg&uacute;n dato de tallaje registrado'',\n       icon: ''warning''\n     });\n     return false;\n   }\n   var url = '''';\n   if (this.arrMod.length > 0 || (this.arrDel.length > 0 && this.arrAdd.length > 0)) {\n     url = ''modTallaje'';\n   } else\n     if (this.arrDel.length > 0) {\n       url = ''delTallaje'';\n     } else {\n       url = ''addTallaje'';\n     }\n   if (this.arrAdd.length > 0 || this.arrMod.length > 0 || this.arrDel.length > 0) {\n     Ext.sendAjax.request({\n       url: url,\n       params: {\n         arrAdd: Ext.encode(self.arrAdd),\n         arrMod: Ext.encode(self.arrMod),\n         arrDel: Ext.encode(self.arrDel)\n       },\n       success: function (response, opt, notification)\n       {\n         var dataResponse = Ext.decode(response.responseText);\n         if (dataResponse.success) {\n           if (btnPress === ''APLICAR'') { //Si el boton que ejecuto la funcion fue aplicar\n             this.loadFn(Ext.getCmp(this.idpadre).persona.idpersona);\n           }\n           this.arrAdd = [];\n           this.arrMod = [];\n           this.arrDel = [];\n           var msg;\n           switch (url) {\n             case ''modTallaje'':\n               msg = ''El(Los) dato(s) de tallaje(s) ha(n) sido modificado(s) satisfactoriamente.'';\n               break;\n             case ''delTallaje'':\n               msg = ''El(Los) dato(s) de tallaje(s) ha(n) sido eliminado(s) satisfactoriamente.'';\n               break;\n             case ''addTallaje'':\n               msg = ''El(Los) dato(s) de tallaje(s) ha(n) sido adicionado(s) satisfactoriamente.'';\n               break\n           }\n           notification({\n             title: ''Informaci&oacute;n'',\n             msg: msg,\n             icon: ''ok''\n           });\n         } else {\n           switch (dataResponse.codigo) {\n             case 23503:\n               notification({\n                 title: ''Error'',\n                 msg: ''No se puede eliminar debido a que est&aacute; en uso.'',\n                 icon: ''error''\n               });\n               break;\n             default :\n               notification({\n                 title: ''Error'',\n                 msg: ''Ha ocurrido un error durante la transaccion.'',\n                 icon: ''error''\n               });\n               break;\n           }\n         }\n       }.createDelegate(this)\n     }, this);\n   }\n }","validateForm":"","bbar":"","ptbar":"","sm":"{\n  type: \"CheckboxSelectionModel\",\n  singleSelect: false\n}","store":"{\n  url: \"getTallaje\",\n    type: \"Store\",\n      reader: {\n        type: \"JsonReader\",\n          totalProperty: \"quantity\",\n            root: \"data\"\n      },\n        mapping: [\n          {name: \"idtallaje\"},\n          {name: \"idprenda\"},\n          {name: \"denomprenda\"},\n          {name: \"idnorma\"},\n          {name: \"denomnorma\"},\n          {name: \"idtalla\"},\n          {name: \"denomtalla\"}\n        ]\n}","view":"","viewConfig":"","listeners":{"beforeload":"","expand":"","focus":"","load":"","render":"","resize":"","selectionchange":"","show":""}}', '{"module":"persona","component":"templates"}', '{"class":"DatTallajeModel","function":"","id":"", "project":""}');
INSERT INTO dat_proyectoconcepto (idproyectoconcepto, denominacion, idpadre, idproyecto, descripcion, tipo, propiedades, iconcls, orden, codigo, cmpempleado, getdata) VALUES (1223, 'Relaciones con extranjeros', 1180, 'basetecnologica', NULL, 1, '{"xtype":"gest_panel","animCollapse":"false","autoHeight":"false","border":"true","collapsed":"false","collapsible":"false","disabled":"false","frame":"false","hidden":"false","split":"false","elementsByRow":3,"height":"","anchocolumna":"","anchor":"","cmargins":"","collapseMode":"","html":"","layout":"","margins":"","region":"","title":"Relaciones con extranjeros","width":"auto"}', 'tag', 5, '{"columns":"[ \n  {header: \"Familiar\", width:270, dataIndex: \"nombre\"},\n  {header: \"Nacionalidad\",width:100, dataIndex: \"nacionalidad\"\n  , renderer: function (value, meta, record) {\n     return \"<div class=''flags_img \" + record.get(''bandera'') + \"'' style=''width: 16px; height: 16px;''><p style=''margin-left: 20px; margin-top: 2px;''>\" + value + \"</p></div>\";\n   }},\n  {header: \"Pais\",width:130, dataIndex: \"pais\"},\n  {header: \"Parentesco\",width:130, dataIndex: \"parentesco\"}, \n]","addBotones":"","adicionarHandler":"","aplicarHandler":"function ()\n{\n    var values = this.fpFormulario.getForm().getValues();\n    values.nombre = Ext.getCmp(\"1238\" + this.idpadre).getRawValue();\n    values.pais = Ext.getCmp(\"1240\" + this.idpadre).getRawValue();\n   values.nacionalidad = Ext.getCmp(\"1240\" + this.idpadre).getRawValue();\n    var store = this.gpGrid.getStore();\n    var index = -1;\n    if (Ext.isEmpty(values.idfamiliarresidente)) {//Si es vacio es porke estoy adicionando\n        values.idfamiliarresidente = Ext.id();\n        values.add = true;\n        Ext.each(store.getRange(), function (rec)\n        {\n            if (rec.get(''idfamiliar'') == values.idfamiliar) {\n                index = ''idfamiliar'';\n                return false;\n            }\n        });\n        switch (index) {\n            case ''idfamiliar'':\n                Ext.Notification.show({\n                    title: ''Error'',                  \n                  \tmsg: ''El familiar que quiere adicionar ya existe.'',\n                    icon: ''error''\n                });\n                break\n            default:\n                try {\n                    store.add(new Ext.data.Record(values));\n                    this.cleanForm();  \n                } catch (error) {\n                    Ext.Notification.show({\n                        title: ''Error'',\n                        msg: ''Ha ocurrido un error mientras se guardaba, contacte el administrador.'',\n                        icon: ''error''\n                    });\n                }\n                break;\n        }\n    }\n}","eliminarHandler":"function ()\n{\n  var records = this.gpGrid.getSelectionModel().getSelections();\n   var ask = (records.length == 1) ? ''¿Está seguro que quiere eliminar la relaci&oacute;n seleccionada?'' : \n    ''¿Está seguro que quiere eliminar las relaciones seleccionadas?'';\n\tmostrarMensaje(2, ask, function (btn)\n        {\n            if (btn == ''ok'') {\n              \n                Ext.each(records, function (rec)\n                {\n                    if (!rec.data.add) {\n                        this.arrDel.push(rec.get(''idfamiliarresidente''));\n                    }\n                    this.gpGrid.getStore().remove(rec);\n                }, this);\n\n                this.gpGrid.getView().refresh();\n            }\n        }.createDelegate(this));\n}","gSecurity":"","getLanguaje":"function(idioma){\n  var lang={};\n if(idioma===''es''){\n     lang ={\n        ttBtnAdd:\"Adicionar familar\",\n        ttBtnMod:\"Modificar familar\",\n        ttBtnDel:\"Eliminar familar\",\n        ttBtnSave:\"Guardar datos y cerrar formulario\",\n        ttBtnApl:\"Guardar datos y limpiar los campos\",\n        ttBtnCancel:\"Cerrar formulario sin guardar los datos\"      \n\n      }  \t\n    }else{\n     lang = {\n        \n      }  \t\n      \n    }\n  return lang;\n\t\n}","guardarHandler":"function ()\n{\n    var values = this.fpFormulario.getForm().getValues();\n     values.nombre = Ext.getCmp(\"1238\" + this.idpadre).getRawValue();\n    values.pais = Ext.getCmp(\"1239\" + this.idpadre).getRawValue();\n  values.nacionalidad = Ext.getCmp(\"1240\" + this.idpadre).getRawValue();\n    var store = this.gpGrid.getStore();\n    var index = -1;\n    if (Ext.isEmpty(values.idfamiliarresidente)) {//Si es vacio es porke estoy adicionando\n        values.idfamiliarresidente = Ext.id();\n        values.add = true;\n        Ext.each(store.getRange(), function (rec)\n        {\n            if (rec.get(''idfamiliar'') == values.idfamiliar) {\n                index = ''idfamiliar'';\n                return false;\n            }\n        });\n        switch (index) {\n            case ''idfamiliarresidente'':\n                Ext.Notification.show({\n                    title: ''Error'',\n                    msg: ''El familiar que quiere adicionar ya existe.'',\n                    icon: ''error''\n                });\n                break\n            default:\n                try {\n                    store.add(new Ext.data.Record(values));\n                    this.cancelarHandler();\n                } catch (error) {\n                    Ext.Notification.show({\n                        title: ''Error'',\n                        msg: ''Ha ocurrido un error mientras se guardaba, contacte el administrador.'',\n                        icon: ''error''\n                    });\n                }\n                break;\n        }\n    } else {\n        var record;\n        //Iteracion para validar la modificacion y obtener el record a modificar\n        Ext.each(store.getRange(), function (rec, i)\n        {\n            if (rec.get(''idfamiliarresidente'') == values.idfamiliarresidente) { //Si  es el que se va a modificar\n                record = rec; //Obtengo el record que se va a modificar\n            } else\n                if (rec.get(''idfamiliar'') == values.idfamiliar) {\n                    index = ''idfamiliar'';\n                }\n        });\n        switch (index) {\n            case ''idfamiliarresidente'':\n                Ext.Notification.show({\n                    title: ''Error'',\n                    msg: ''El familiar ya existe.'',\n                    icon: ''error''\n                });\n                break\n            default:\n                try {\n                    for (var p in values) {\n                        if (values[p] != record.get(p)) {\n                            record.set(p, values[p]);\n                        }\n                    }\n                    this.cancelarHandler();\n                } catch (error) {\n                    Ext.Notification.show({\n                        title: ''Error'',\n                        msg: ''Ha ocurrido un error mientras se modificaba, contacte el administrador.'',\n                        icon: ''error''\n                    });\n                }\n                break;\n        }\n    }\n}","helpHandler":"","isDirty":"","loadFn":"function(idpersona){\n  this.arrAdd = [];\n  this.arrMod = [];\n  this.arrDel = [];\n  this.loadGridStore({idpersona: idpersona});\n}","modificarHandler":"","saveFn":"function(btnPress){\n  var self = this;\n  var store = this.gpGrid.getStore();\n  this.arrAdd = [];\n  this.arrMod = [];\n  Ext.each(store.getRange(), function (rec) {\n    if (rec.data.add) {\n      this.arrAdd.push(rec.data);\n    } else {\n      if (!Ext.isEmpty(rec.modified)) {\n        this.arrMod.push(rec.data);\n      }\n    }\n  }, this);\n  if(this.arrAdd.length > 0 || this.arrMod.length > 0 || this.arrDel.length > 0) {\n    Ext.sendAjax.request({\n      url: ''gestFamiliarRelaciones'',\n      params: {\n        arrAdd: Ext.encode(self.arrAdd),\n        arrMod: Ext.encode(self.arrMod),\n        arrDel: Ext.encode(self.arrDel)\n      },\n      success: function (response, opt, notification) {\n        var dataResponse = Ext.decode(response.responseText);\n        if(dataResponse.success) {\n          if(btnPress === ''APLICAR'') {\n            this.loadFn(Ext.getCmp(this.idpadre).persona.idpersona);\n          }\n          this.arrAdd = [];\n          this.arrMod = [];\n          this.arrDel = [];\n          mostrarMensaje(1, ''Los datos han sido gestionados satisfactoriamente.'');\n          this.loadFn(Ext.getCmp(this.idpadre).persona.idpersona);\n        } else {\n         mostrarMensaje(6, ''Error al procesar los datos.'');\n        }\n      }.createDelegate(this)\n    }, this);\n  }\n}","validateForm":"","bbar":"","ptbar":"","sm":"","store":"{\n  url: \"getFamiliarRelacionesByPesona\",\n  type: \"Store\",\n  reader: {\n    type: \"JsonReader\",\n    totalProperty: \"quantity\",\n    root: \"data\"\n  },\n  mapping: [\n    {name: \"idfamiliarresidente\"},\n    {name: \"fdesde\"},\n    {name: \"fhasta\"},\n    {name: \"idpais\"},\n    {name: \"idfamiliar\"},\n    {name: \"nombre\"},\n    {name: \"pais\"},\n    {name: \"idnacionalidad\"},\n    {name: \"nacionalidad\"},\n    {name: \"bandera\"},\n     {name: \"idparentesco\"},\n    {name: \"parentesco\"}\n  ],\n  sortInfo:{field: \"nombre\", direction: \"ASC\"}\n}","view":"","viewConfig":"","listeners":{"beforeload":"","expand":"","focus":"","load":"","render":"function(cmp){\n\tExt.getCmp(''1238''+this.idpadre).store.baseParams.idpersona=Ext.getCmp(this.idpadre).persona.idpersona;\n  Ext.getCmp(''1238''+this.idpadre).store.load();\n}","resize":"","selectionchange":"","show":""}}', '{"module":"persona","component":"templates"}', NULL);
INSERT INTO dat_proyectoconcepto (idproyectoconcepto, denominacion, idpadre, idproyecto, descripcion, tipo, propiedades, iconcls, orden, codigo, cmpempleado, getdata) VALUES (1307, 'Estado de vivienda', 1118, 'basetecnologica', NULL, 1, '{"xtype":"form_panel","animCollapse":"false","autoHeight":"false","border":"true","collapsed":"false","collapsible":"false","disabled":"false","frame":"true","hidden":"false","split":"false","trackResetOnLoad":"true","elementsByRow":"2","height":100,"anchocolumna":"","anchor":"","buttonAlign":"right","cmargins":"","collapseMode":"","html":"","labelAlign":"top","layout":"","margins":"","region":"","title":"Estado de vivienda","width":"auto"}', 'tag', 7, '{"gSecurity":"","helpHandler":"","isDirty":"","loadFn":"function(idpersona){\n  Ext.Ajax.request({\n    url: ''getEstadoViviendaByPersona'',\n    params: {idpersona: idpersona},\n    success: function (response, opt)\n    {\n      var dataResponse = Ext.decode(response.responseText);\n    \n      if (dataResponse.data.length != 0) {\n        this.getForm().loadRecord(new Ext.data.Record(dataResponse.data[0]));\n        this.getForm().findField(''idestadovivienda'').setRawValue(dataResponse.data[0].denomestado);\n        this.getForm().findField(''idconvivencia'').setRawValue(dataResponse.data[0].denomconvivencia);\n      }\n    }.createDelegate(this)\n  });\n}","saveFn":"function (btnPress)\n{\n  \n  if (this.getForm().isValid() && this.getForm().isDirty()) {      \n        var url = (Ext.isEmpty(this.getForm().getValues().idestadoviviendap)) ? ''addEstadoVivienda'' : ''modEstadoVivienda'';\n        Ext.sendAjax.request({\n            url: url,\n            params: this.getForm().getValues(),\n            success: function (response, opt, notification)\n            {\n                var dataResponse = Ext.decode(response.responseText);\n                if (dataResponse.success) {\n                    if (btnPress === ''APLICAR'') { //Si el boton que ejecuto la funcion fue aplicar\n                        if (dataResponse.data) {\n                            this.getForm().loadRecord(new Ext.data.Record(dataResponse.data));\n                            this.getForm().findField(''idestadovivienda'').setRawValue(dataResponse.data.denomestado);\n                            this.getForm().findField(''idconvivencia'').setRawValue(dataResponse.data.denomconvivencia);\n                        }\n                    }\n                    var msg = '''';\n                    switch (url) {\n                        case ''addEstadoVivienda'':\n                            msg = ''El estado de la vivienda se ha adicionado satisfactoriamente.'';\n                            break;\n                        case ''modEstadoVivienda'':\n                            msg = ''El estado de la vivienda se ha modificado satisfactoriamente.'';\n                            break;\n                    }\n                    notification({\n                        title: ''Informaci&oacute;n'',\n                        msg: msg,\n                        icon: ''ok''\n                    });\n                } else {\n                    switch (dataResponse.codigo) {\n                        default :\n                            notification({\n                                title: ''Error'',\n                                msg: ''Ha ocurrido un error durante la transaccion.'',\n                                icon: ''error''\n                            });\n                            break;\n                    }\n                }\n\n            }.createDelegate(this)\n        }, this);\n    }\n}","listeners":{"clientvalidation":"","expand":"","focus":"","render":"","resize":"","show":""}}', '{"module":"persona","component":"templates"}', NULL);
