INSERT INTO dat_proyectoconcepto (idproyectoconcepto, denominacion, idpadre, idproyecto, descripcion, tipo, propiedades, iconcls, orden, codigo, cmpempleado, getdata) VALUES (72, 'Centro de estudio', 68, 'basetecnologica', NULL, 3, '{"xtype":"combo_box","allowBlank":"false","disabled":"false","editable":"true","forceSelection":"false","hidden":"false","readOnly":"false","resizable":"false","selectOnFocus":"false","typeAhead":"false","anchocolumna":"","anchor":"100%","displayField":"denominacion","emptyText":"Seleccione...","fieldLabel":"Centro de estudio","hiddenName":"idcentroestudio","loadingText":"","mode":"local","name":"idcentroestudio","toolTipTrigger1":"","toolTipTrigger2":"","triggerAction":"","valueField":"idcentroestudio"}', 'icondistra-tag_blue', 5, '{"handler":"","store":"{\n  url: \"getCentroEstudios\",\n    type: \"Store\",\n       baseParams: {\n            value: 1\n        },\n      reader: {\n        type: \"JsonReader\",          \n            root: \"data\"\n      },\n        mapping: [\n          {name: ''idcentroestudio''},\n          {name: ''idtipocentroestudio''},\n          {name: ''denominacion''},\n          {name: ''fdesde''},\n          {name: ''fhasta''},\n          {name: ''descripcion''}        \n        ],\n          autoLoad:true,\n          \n}","tpl":"","listeners":{"expand":"function (cmp) {\n \n  if(Ext.getCmp(''1405''+this.idpadre).getValue()){\n    cmp.store.filter(''idtipocentroestudio'', Ext.getCmp(''1405''+this.idpadre).getValue(), true);\n  }\n   \n}","focus":"","render":"","select":"function(cb, rec){\n  //ComboBox de Tipo de Centro de estudio\n  if(Ext.getCmp(''1405''+this.idpadre))\n  \tExt.getCmp(''1405''+this.idpadre).setValue(rec.get(''idtipocentroestudio''));\n}"}}', '{"module":"persona","component":"templates"}', NULL);
