switch (dataResponse.codigo) {\n                        default :\n                            notification({\n                                title: ''Error'',\n                                msg: ''Ha ocurrido un error durante la transaccion.'',\n                                icon: ''error''\n                            });\n                            break;\n                    }\n                }\n            }.createDelegate(this)\n        }, this);\n    }\n}","validateForm":"","bbar":"","ptbar":"","sm":"{\n  type: \"RowSelectionModel\",\n  singleSelect: false\n}","store":"{\n  url: \"getSituacExcep\",\n    type: \"Store\",\n      reader: {\n        type: \"JsonReader\",\n          totalProperty: \"quantity\",\n            root: \"data\"\n      },\n        mapping: [\n          {name: \"idsitexcepcional\"},\n          {name: \"idsituacexcep\"},\n          {name: \"idcargoexcep\"},\n          {name: \"situacexcep\"},\n          {name: \"cargoexcep\"},\n          {name: \"fdesde\"},       \n          {name: \"fhasta\"}         \n        ]\n          \n}","view":"","viewConfig":"","listeners":{"beforeload":"","expand":"","focus":"","load":"","render":"","resize":"","selectionchange":"","show":""}}', '{"module":"persona","component":"templates"}', NULL);
INSERT INTO dat_proyectoconcepto (idproyectoconcepto, denominacion, idpadre, idproyecto, descripcion, tipo, propiedades, iconcls, orden, codigo, cmpempleado, getdata) VALUES (1388, 'Reclamacion', 1118, 'basetecnologica', NULL, 1, '{"xtype":"gest_panel","animCollapse":"false","autoHeight":"false","border":"true","collapsed":"false","collapsible":"false","disabled":"false","frame":"false","hidden":"false","split":"false","elementsByRow":4,"height":"","anchocolumna":"","anchor":"","cmargins":"","collapseMode":"","html":"","layout":"","margins":"","region":"","title":"Reclamación","width":"auto"}', 'icondistra-tag', 12, '{"columns":"[\n  {header: \"No. acuerdo\", width: 100, sortable: true, dataIndex: \"numeroacuerdo\"},  \n  {header: \"Fecha acuerdo\", width: 100, sortable: true, dataIndex: \"fechaacuerdo\"},\n  {header: \"Decisión\", width: 200, sortable: true, dataIndex: \"decision\"},\n  {header: \"Plaza a ocupar\", width: 200, sortable: true, dataIndex: \"nuevaplaza\"},\n  {header: \"Reclamación\", width: 200, sortable: true, dataIndex: \"reclamacion\"}\n]","addBotones":"","adicionarHandler":"","aplicarHandler":"function ()\n{\n    var values = this.fpFormulario.getForm().getValues();\n    values.decision = Ext.getCmp(\"1390\" + this.idpadre).getRawValue();\n    var store = this.gpGrid.getStore();\n\n    var index = -1;\n\n    if (Ext.isEmpty(values.idreclamacion)) {\n        values.idreclamacion = Ext.id();\n        values.add = true;\n       \n        switch (index) {\n           \n            default :\n                try {\n                    store.add(new Ext.data.Record(values));\n                    this.cleanForm();\n                } catch (error) {\n                    Ext.Notification.show({\n                        title: ''Error'',\n                        msg: ''Ha ocurrido un error mientras se guardaba, contacte el administrador.'',\n                        icon: ''error''\n                    });\n                }\n                break;\n        }\n    }\n}","eliminarHandler":"function(){\n  \n  var records = this.gpGrid.getSelectionModel().getSelections();\n  var ask = ''¿Está seguro que quiere eliminar la reclamación seleccionada?'';\n  if (records.length > 1) {\n    var ask = ''¿Está seguro que quiere eliminar las reclamaciones seleccionadas?'';\n  } \n  mostrarMensaje(2, ask, function (btn)\n                 {\n                   if (btn == ''ok'') {\n                     var records = this.gpGrid.getSelectionModel().getSelections();\n                     Ext.each(records, function (rec)\n                              {\n                                if (!rec.data.add) {\n                                  this.arrDel.push(rec.get(''idreclamacion''));\n                                }\n                                this.gpGrid.getStore().remove(rec);\n                              }, this);\n\n                     this.gpGrid.getView().refresh();\n                   }\n                 }.createDelegate(this));\n}","gSecurity":"","getLanguaje":"","guardarHandler":"function ()\n{\n    var values = this.fpFormulario.getForm().getValues();\t\n    values.decision = Ext.getCmp(\"1390\" + this.idpadre).getRawValue();\n    var store = this.gpGrid.getStore();\n    var index = -1;\n\n    if (Ext.isEmpty(values.idreclamacion)) {\n        values.idreclamacion = Ext.id();\n        values.add = true;\n       \n        switch (index) {\n           \n            default :\n                try {\n                    store.add(new Ext.data.Record(values));\n                    this.cancelarHandler();\n                } catch (error) {\n                    Ext.Notification.show({\n                        title: ''Error'',\n                        msg: ''Ha ocurrido un error mientras se guardaba, contacte el administrador.'',\n                        icon: ''error''\n                    });\n                }\n                break;\n        }\n    } else {\n      \n      \n      \n      var record;\n      \n      \n      \n       Ext.each(store.getRange(), function (rec)\n               {\n                 if (rec.get(''idreclamacion'') == values.idreclamacion) {                   \n                   record = rec;\n                   return false;\n                 }\n               });\n      \n       \n        switch (index) {             \n            default :\n                try {\n                    for (var p in values) {\n                        if (values[p] != record.get(p)) {\n                            record.set(p, values[p]);\n                        }\n                    }\n                    this.cancelarHandler();\n                } catch (error) {\n                \n                    Ext.Notification.show({\n                        title: ''Error'',\n                        msg: ''Ha ocurrido un error mientras se modificaba, contacte el administrador.'',\n                        icon: ''error''\n                    });\n                }\n                break;\n        }\n    }\n}","helpHandler":"","isDirty":"","loadFn":"function (idpersona)\n{\n  this.arrAdd = [];\n  this.arrMod = [];\n  this.arrDel = [];\n  this.loadGridStore({idpersona: idpersona});\n}","modificarHandler":"function(){\n  var record = this.gpGrid.getSelectionModel().getSelected();  \n  this.loadFormulario(record);\n  \n}","saveFn":"function (btnPress)\n{\n    var store = this.gpGrid.getStore();\n    var self = this;\n    var pass = false;\n    this.arrAdd = [];\n    this.arrMod = [];\n    Ext.each(store.getRange(), function (rec)\n    {\n        if (rec.data.add) {//Si es un record que se adiciono nuevo\n            this.arrAdd.push(rec.data);\n        } else {\n            if (!Ext.isEmpty(rec.modified)) {//Si el record fue modificado\n                this.arrMod.push(rec.data);\n            }\n        }\n    }, this);\n    \n    if (this.arrMod.length > 0 || (this.arrDel.length > 0 && this.arrAdd.length > 0)) {\n        url = ''modReclamacion'';\n    } else\n        if (this.arrDel.length > 0) {\n            url = ''delReclamacion'';\n        } else {\n            url = ''addReclamacion'';\n        }\n    if (this.arrAdd.length > 0 || this.arrMod.length > 0 || this.arrDel.length > 0) {\n        Ext.sendAjax.request({\n            url: url,\n            params: {\n                arrAdd: Ext.encode(self.arrAdd),\n                arrMod: Ext.encode(self.arrMod),\n                arrDel: Ext.encode(self.arrDel)\n            },\n            success: function (response, opt, notification)\n            {\n                var dataResponse = Ext.decode(response.responseText);\n                if (dataResponse.success) {\n                    if (btnPress === ''APLICAR'') { //Si el boton que ejecuto la funcion fue aplicar\n                        this.loadFn(Ext.getCmp(this.idpadre).persona.idpersona);\n                    }\n                    this.arrAdd = [];\n                    this.arrMod = [];\n                    this.arrDel = [];\n                    var msg;\n                    switch (url) {\n                        case ''modReclamacion'':\n                            msg = ''La reclamación se ha modificado satisfactoriamente.'';\n                            break;\n                        case ''delReclamacion'':\n                            msg = ''La reclamaciónl se ha eliminado satisfactoriamente.'';\n                            break;\n                        case ''addReclamacion'':\n                            msg = ''La reclamación se ha adicionado satisfactoriamente.'';\n                            break\n                    }\n                    notification({\n                        title: ''Informaci&oacute;n'',\n                        msg: msg,\n                        icon: ''ok''\n                    });\n                } else {\n                    switch (dataResponse.codigo) {\n                        default :\n                            notification({\n                                title: ''Error'',\n                                msg: ''Ha ocurrido un error durante la transaccion.'',\n                                icon: ''error''\n                            });\n                            break;\n                    }\n                }\n            }.createDelegate(this)\n        }, this);\n    }\n}","validateForm":"","bbar":"","ptbar":"","sm":"{\n  type: \"RowSelectionModel\",\n  singleSelect: false\n}","store":"{\n  url: \"getReclamacion\",\n    type: \"Store\",\n      reader: {\n        type: \"JsonReader\",\n          totalProperty: \"quantity\",\n            root: \"data\"\n      },\n        mapping: [\n          {name: \"idreclamacion\"},\n          {name: \"fechaacuerdo\"},\n          {name: \"numeroacuerdo\"},\n          {name: \"decision\"},\n          {name: \"decision\"},\n          {name: \"reclamacion\"},\n          {name: \"nuevaplaza\"},       \n          {name: \"idpersona\"}         \n        ]\n          \n}","view":"","viewConfig":"","listeners":{"beforeload":"","expand":"","focus":"","load":"","render":"","resize":"","selectionchange":"","show":""}}', '{"module":"persona","component":"templates"}', NULL);
INSERT INTO dat_proyectoconcepto (idproyectoconcepto, denominacion, idpadre, idproyecto, descripcion, tipo, propiedades, iconcls, orden, codigo, cmpempleado, getdata) VALUES (109, 'Direcciones', 57, 'basetecnologica', NULL, 1, '{"xtype":"gest_panel","animCollapse":"false","autoHeight":"false","border":"true","collapsed":"false","collapsible":"false","disabled":"false","frame":"false","hidden":"false","split":"false","elementsByRow":3,"height":"","anchocolumna":"","anchor":"","cmargins":"","collapseMode":"","html":"","layout":"","margins":"","region":"","title":"Direcciones","width":"auto"}', 'icondistra-tag', 3, '{"columns":"[\n  {header: \"Pa&iacute;s\", width: 120, sortable: true, dataIndex: \"pais\"},\n  {header: \"Provincia\", width: 180, sortable: true, dataIndex: \"denomprov\"},\n  {header: \"Municipio\", width: 180, sortable: true, dataIndex: \"denommunic\"},\n  {header: \"Direcci&oacute;n\", width: 250, sortable: true, dataIndex: \"direccion\"},\n  {header: \"Principal\", width: 55, sortable: true, dataIndex: \"oficial\", renderer: function (val)\n   {\n     if (val == true) {\n       return \"<center class=''checked'' style=''width: 16px; height: 16px;''></center>\";\n     }\n     return '''';\n   }},\n  {header: \"Desde\", width: 85, sortable: true, dataIndex: \"fdesde\"},\n  {header: \"Hasta\", width: 85, sortable: true, dataIndex: \"fhasta\"},\n  {header: \"Hist&oacute;rico\", hidden: true, sortable: true, dataIndex: \"historico\", renderer: function (v)\n   {\n     return (v == 1) ? ''Actual'' : ''Hist&oacute;rico'';\n   }}\n]","addBotones":"","adicionarHandler":"","aplicarHandler":"function ()\n{\n  var values = this.fpFormulario.getForm().getValues();\n  values.oficial = values.oficial == \"on\" ? true : false;\n  values.pais = Ext.getCmp(\"1193\" + this.idpadre).getRawValue();\n  var prov_mun = values.denomprovmun.split(''-'');\n\n    values.denomprov = prov_mun[0] || '''';\n\n    values.denommunic = prov_mun[1] || '''';\n\n    values.historico = isActual(values.fdesde, values.fhasta);\n\n    var store = this.gpGrid.getStore();\n\n    var index = -1;\n  \n  console.info(values);\n\n    if (Ext.isEmpty(values.iddireccion)) {//Si es vacio es porke estoy adicionando\n        values.iddireccion = Ext.id();\n        values.add = true;\n        if (values.historico != 0) { //El checkeo eso solo si la direccion es actual\n            Ext.each(store.getRange(), function (rec)\n            {\n                if (rec.get(''oficial'') == true && values.oficial != false && rec.get(''historico'') == 1) {\n                    index = ''oficial'';\n                    return false;\n                }\n              \tif (rec.get(''idprovincia'') == values.idprovincia && rec.get(''idmunicipio'') == values.idmunicipio && \n                    rec.get(''direccion'') == values.direccion && rec.get(''fdesde'') == values.fdesde && rec.get(''fhasta'') == values.fhasta) {\n                    index = ''direccion'';\n                    return false;\n                }              \n            });\n        }\n        switch (index) {\n            case ''oficial'':\n                Ext.Notification.show({\n                    title: ''Error'',\n                    msg: ''La persona ya tiene una dirección actual como principal.'',\n                    icon: ''error''\n                });\n                break;\n            case ''direccion'':\n                Ext.Notification.show({\n                    title: ''Error'',\n                    msg: ''La dirección que quiere adicionar ya existe.'',\n                    icon: ''error''\n                });\n                break;\n            default :\n                try {\n                    store.add(new Ext.data.Record(values));\n                    this.cleanForm();\n                } catch (error) {\n                    Ext.Notification.show({\n                        title: ''Error'',\n                        msg: ''Ha ocurrido un error mientras se guardaba, contacte el administrador.'',\n                        icon: ''error''\n                    });\n                }\n                break;\n        }\n    }\n    store.clearGrouping();\n    store.groupBy(''historico'', true);\n\n    function isActual(fi, ff)\n    {\n        if (!Ext.isEmpty(ff)) {//Si la fecha fin es ditinto de vacio\n            var date = new Date();\n            date = date.format(''d/m/Y'');\n            var arrfi = fi.split(''/'');\n            var arrff = ff.split(''/'');\n            var arrfa = date.split(''/'');\n            var fi = arrfi[2] + arrfi[1] + arrfi[0];\n            var ff = arrff[2] + arrff[1] + arrff[0];\n            var fa = arrfa[2] + arrfa[1] + arrfa[0];\n            fi = parseInt(fi);\n            ff = parseInt(ff);\n            fa = parseInt(fa);\n            return (fi <= fa && fa <= ff) ? 1 : 0;\n            //1->Actual  0->Historico\n        }\n        return 1;\n    }\n}","eliminarHandler":"function(){\n  var records = this.gpGrid.getSelectionModel().getSelections();\n   var ask = (records.length == 1) ? ''¿Está seguro que quiere eliminar la dirección seleccionada?'' : \n    ''¿Está seguro que quiere eliminar las direcciones seleccionadas?'';\n\tmostrarMensaje(2, ask, function (btn)\n        {\n            if (btn == ''ok'') {\n\n                \n                Ext.each(records, function (rec)\n                {\n                    if (!rec.data.add) {\n                        this.arrDel.push(rec.get(''iddireccion''));\n                    }\n                    this.gpGrid.getStore().remove(rec);\n                }, this);\n                this.gpGrid.getView().refresh();\n            }\n        }.createDelegate(this));\n}","gSecurity":"","getLanguaje":"function(idioma){\n  var lang={};\n if(idioma===''es''){\n     lang ={\n        ttBtnAdd:\"Adicionar dirección\",\n        ttBtnMod:\"Modificar dirección\",\n        ttBtnDel:\"Eliminar dirección\",\n        ttBtnSave:\"Guardar datos y cerrar formulario\",\n        ttBtnApl:\"Guardar datos y limpiar los campos\",\n        ttBtnCancel:\"Cerrar formulario sin guardar los datos\"      \n\n      }  \t\n    }else{\n     lang = {\n        \n      }  \t\n      \n    }\n  return lang;\n\t\n}","guardarHandler":"function ()\n{\n  var values = this.fpFormulario.getForm().getValues();\n  values.oficial = values.oficial == \"on\" ? true : false;\n  values.pais = Ext.getCmp(\"1193\" + this.idpadre).getRawValue();\n  var prov_mun = values.denomprovmun.split(''-'');\n  values.denomprov = prov_mun[0] || '''';\n  values.denommunic = prov_mun[1] || '''';\n  values.historico = isActual(values.fdesde, values.fhasta);\n  var store = this.gpGrid.getStore();\n  var index = -1;\n  if (Ext.isEmpty(values.iddireccion)) {//Si es vacio es porke estoy adicionando\n    values.iddireccion = Ext.id();\n    values.add = true;\n    if (values.historico != 0) {//El checkeo eso solo si la direccion es actual\n      Ext.each(store.getRange(), function (rec){\n        if (rec.get(''oficial'') == true && values.oficial != false && rec.get(''historico'') == 1) {\n          index = ''oficial'';\n          return false;\n        }\n        if (rec.get(''idprovincia'') == values.idprovincia && rec.get(''idmunicipio'') == values.idmunicipio && \n            rec.get(''direccion'') == values.direccion && rec.get(''fdesde'') == values.fdesde && rec.get(''fhasta'') == values.fhasta) {\n          index = ''direccion'';\n          return false;\n        }\n      });\n    }\n    switch (index) {\n      case ''oficial'':\n        Ext.Notification.show({\n          title: ''Error'',\n          msg: ''La persona ya tiene una dirección actual como principal.'',\n          icon: ''error''\n        });\n        break;\n      case ''direccion'':\n        Ext.Notification.show({\n          title: ''Error'',\n          msg: ''La dirección que quiere adicionar ya existe.'',\n          icon: ''error''\n        });\n        break;\n      default :\n        try {\n          store.add(new Ext.data.Record(values));\n          this.cancelarHandler();\n        } catch (error) {\n          Ext.Notification.show({\n            title: ''Error'',\n            msg: ''Ha ocurrido un error mientras se guardaba, contacte el administrador.'',\n            icon: ''error''\n          });\n        }\n        break;\n    }\n  } else {\n    var record;\n    //Iteracion para validar la modificacion y obtener el record a modificar\n    Ext.each(store.getRange(), function (rec) {\n      if (rec.get(''iddireccion'') != values.iddireccion) { //Si no es el que se va a modificar\n        if (values.historico != 0) {//El checkeo eso solo si la direccion es actual\n          if (rec.get(''oficial'') == true && values.oficial != false && rec.get(''historico'') == 1) {\n            index = ''oficial'';\n            return false;\n          }\n        }\n      } else {\n        record = rec;//Obtengo el record que se va a modificar\n      }\n      if (rec.get(''idprovincia'') == values.idprovincia && rec.get(''idmunicipio'') == values.idmunicipio && \n          rec.get(''direccion'') == values.direccion && rec.get(''fdesde'') == values.fdesde && rec.get(''fhasta'') == values.fhasta) {\n        index = ''direccion'';\n        return false;\n      }\n    });\n    switch (index) {\n      case ''oficial'':\n        Ext.Notification.show({\n          title: ''Error'',\n          msg: ''La persona ya tiene una dirección actual como principal.'',\n          icon: ''error''\n        });\n        break;\n      case ''direccion'':\n        Ext.Notification.show({\n          title: ''Error'',\n          msg: ''La dirección ya existe.'',\n          icon: ''error''\n        });\n        break;\n      default :\n        try {\n          for (var p in values) {\n            if (values[p] != record.get(p)) {\n              record.set(p, values[p]);\n            }\n          }\n          this.cancelarHandler();\n        } catch (error) {\n          Ext.Notification.show({\n            title: ''Error'',\n            msg: ''Ha ocurrido un error mientras se modificaba, contacte el administrador.'',\n            icon: ''error''\n          });\n        }\n        break;\n    }\n  }\n  store.clearGrouping();\n  store.groupBy(''historico'', true);\n \n\n  function isActual(fi, ff) {\n    if (!Ext.isEmpty(ff)) {//Si la fecha fin es ditinto de vacio\n      var date = new Date();\n      date = date.format(''d/m/Y'');\n      var arrfi = fi.split(''/'');\n      var arrff = ff.split(''/'');\n      var arrfa = date.split(''/'');\n      var fi = arrfi[2] + arrfi[1] + arrfi[0];\n      var ff = arrff[2] + arrff[1] + arrff[0];\n      var fa = arrfa[2] + arrfa[1] + arrfa[0];\n      fi = parseInt(fi);\n      ff = parseInt(ff);\n      fa = parseInt(fa);\n      return (fi <= fa && fa <= ff) ? 1 : 0;\n      //1->Actual  0->Historico\n    }\n    return 1;\n  }\n}","helpHandler":"","isDirty":"","loadFn":"function(idpersona){\n  this.arrAdd = [];\n  this.arrMod = [];\n  this.arrDel = [];\n  this.loadGridStore({idpersona: idpersona});\n}","modificarHandler":"function(){\n  var record = this.gpGrid.getSelectionModel().getSelected();\n  \n  Ext.getCmp(''120'' + this.idpadre).treeConfig.loader.baseParams.idpais=record.get(''idpais'');\n  Ext.getCmp(''120'' + this.idpadre).onTrigger1Click();\n    \n  Ext.getCmp(''120'' + this.idpadre).enable();\n  record.data.denomprovmun = record.get(''denomprov'') + ''-'' + record.get(''denommunic'');\n  this.loadFormulario(record);\n}","saveFn":"function (btnPress)\n{\n    var self = this;\n    var store = this.gpGrid.getStore();\n    this.arrAdd = [];\n    this.arrMod = [];\n    var pass = false;\n    Ext.each(store.getRange(), function (rec)\n    {\n        if (rec.data.add) {//Si es un record que se adiciono nuevo\n            this.arrAdd.push(rec.data);\n        } else {\n            if (!Ext.isEmpty(rec.modified)) {//Si el record fue modificado\n                this.arrMod.push(rec.data);\n            }\n        }\n        if (rec.get(''historico'') == 1 && rec.get(''oficial'') == true && !pass) {\n            pass = true;\n        }\n    }, this);\n    if (!pass && this.obligatorio) {\n        Ext.Notification.show({\n            title: ''Advertencia'',\n            msg: ''La persona ya tiene una dirección actual como principal.'',\n            icon: ''warning''\n        });\n        return false;\n    }\n    var url = '''';\n    if (this.arrMod.length > 0 || (this.arrDel.length > 0 && this.arrAdd.length > 0)) {\n        url = ''modDirecciones'';\n    } else\n        if (this.arrDel.length > 0) {\n            url = ''delDirecciones'';\n        } else {\n            url = ''addDirecciones'';\n        }\n    if (this.arrAdd.length > 0 || this.arrMod.length > 0 || this.arrDel.length > 0) {\n        Ext.sendAjax.request({\n            url: url,\n            params: {\n                arrAdd: Ext.encode(self.arrAdd),\n                arrMod: Ext.encode(self.arrMod),\n                arrDel: Ext.encode(self.arrDel)\n            },\n            success: function (response, opt, notification)\n            {\n                var dataResponse = Ext.decode(response.responseText);\n                if (dataResponse.success) {\n                    if (btnPress === ''APLICAR'') { //Si el boton que ejecuto la funcion fue aplicar\n                        this.loadFn(Ext.getCmp(this.idpadre).persona.idpersona);\n                    }\n                    this.arrAdd = [];\n                    this.arrMod = [];\n                    this.arrDel = [];\n                    var msg = '''';\n                    switch (url) {\n                        case ''modDirecciones'':\n                            msg = ''La(s) dirección(es) ha(n) sido modificada(s) satisfactoriamente.'';\n                            break;\n                        case ''delDirecciones'':\n                            msg = ''La(s) dirección(es) ha(n) sido eliminada(s) satisfactoriamente.'';\n                            break;\n                        case ''addDirecciones'':\n                            msg = ''La(s) dirección(es) ha(n) sido adicionada(s) satisfactoriamente.'';\n                            break\n                    }\n                    notification({\n                        title: ''Informaci&oacute;n'',\n                        msg: msg,\n                        icon: ''ok''\n                    });\n                } else {\n                    switch (dataResponse.codigo) {\n                        default :\n                            notification({\n                                title: ''Error'',\n                                msg: ''Ha ocurrido un error durante la transaccion.'',\n                                icon: ''error''\n                            });\n                            break;\n                    }\n                }\n            }.createDelegate(this)\n        }, this);\n    }\n}","validateForm":"","bbar":"","ptbar":"","sm":"{\n  type: \"RowSelectionModel\",\n  singleSelect: false\n}","store":"{\n  url: \"getDirecciones\",\n    type: \"GroupingStore\",\n      reader: {\n        type: \"JsonReader\",\n          totalProperty: \"quantity\",\n            root: \"data\"\n      },\n        mapping: [\n          {name: \"iddireccion\"},\n          {name: \"idpais\"},\n          {name: \"pais\"},\n          {name: \"idprovincia\"},\n          {name: \"denomprov\"},\n          {name: \"idmunicipio\"},\n          {name: \"denommunic\"},\n          {name: \"direccion\"},\n          {name: \"oficial\"},\n          {name: \"fdesde\"},\n          {name: \"fhasta\"},\n          {name: \"historico\"}\n        ],\n          sortInfo: {field: ''historico'', direction: \"DESC\"},\n            groupField: ''historico''\n}","view":"{\n  type: ''GroupingView'',\n    //startCollapsed: true,\n      groupTextTpl: ''{group} ({[values.rs.length]} {[values.rs.length > 1 ? \"Direcciones\" : \"Direcci&oacute;n\"]})''\n}","viewConfig":"","listeners":{"beforeload":"","expand":"","focus":"","load":"","render":"","resize":"","selectionchange":"","show":""}}', '{"module":"persona","component":"templates"}', '{"class":"DatDireccionModel","function":"","id":"", "project":""}');
INSERT INTO dat_proyectoconcepto (idproyectoconcepto, denominacion, idpadre, idproyecto, descripcion, tipo, propiedades, iconcls, orden, codigo, cmpempleado, getdata) VALUES (129, 'Datos de nacimiento', 57, 'basetecnologica', NULL, 1, '{"xtype":"form_panel","animCollapse":"false","autoHeight":"false","border":"true","collapsed":"false","collapsible":"false","disabled":"false","frame":"true","hidden":"false","split":"false","trackResetOnLoad":true,"elementsByRow":3,"height":"","anchocolumna":"","anchor":"","buttonAlign":"right","cmargins":"","collapseMode":"","html":"","labelAlign":"top","layout":"","margins":"","region":"","title":"Datos de nacimiento","width":"auto"}', 'icondistra-tag', 5, '{"gSecurity":"","helpHandler":"","isDirty":"","loadFn":"function(idpersona){\n  Ext.Ajax.request({\n    url: ''getBirthdataByIdPerson'',\n    params: {idpersona: idpersona},\n    success: function (response, opt)\n    {\n      var dataResponse = Ext.decode(response.responseText);\n      if (dataResponse.data) {\n         Ext.getCmp(''144'' + this.idpadre).enable();\n        this.getForm().loadRecord(new Ext.data.Record(dataResponse.data));\n        if(this.getForm().findField(''idpais'')){\n          \tthis.getForm().findField(''idpais'').setRawValue(dataResponse.data.denompais);\n          \tExt.getCmp(''144'' + this.idpadre).treeConfig.loader.baseParams.idpais=dataResponse.data.idpais;\n  \t\t\tExt.getCmp(''144'' + this.idpadre).onTrigger1Click();\n        }\n        if(this.getForm().findField(''denomprovmuni'')){\n          this.getForm().findField(''denomprovmuni'').setRawValue(dataResponse.data.denomprovmuni);\n        }\n      }\n    }.createDelegate(this)\n  });\n}","saveFn":"function (btnPress)\n{\n    if (this.getForm().isValid() && this.getForm().isDirty()) {\n        var url = (Ext.isEmpty(this.getForm().getValues().iddatosnacimiento)) ? ''addBirthdata'' : ''changeBirthdata'';\n        Ext.sendAjax.request({\n            url: url,\n            params: this.getForm().getValues(),\n            success: function (response, opt, notification)\n            {\n                var dataResponse = Ext.decode(response.responseText);\n                if (dataResponse.success) {\n                    if (btnPress === ''APLICAR'') { //Si el boton que ejecuto la funcion fue aplicar\n                        this.getForm().loadRecord(new Ext.data.Record(dataResponse.data));\n                    }\n                    var msg = (url === ''addBirthdata'')\n                        ? ''Los datos de nacimiento han sido adicionados satisfactoriamente.''\n                        : ''Los datos de nacimento han sido modificados satisfactoriamente.'';\n                    notification({\n                        title: ''Informaci&oacute;n'',\n                        msg: msg,\n                        icon: ''ok''\n                    });\n                } else {\n                    switch (dataResponse.codigo) {\n                        default:\n                            notification({\n                                title: ''Error'',\n                                msg: ''Ha ocurrido un error durante la transaccion.'',\n                                icon: ''ok''\n                            });\n                            break;\n                    }\n                }\n            }.createDelegate(this)\n        }, this);\n    }\n}","listeners":{"clientvalidation":"","expand":"","focus":"","render":"function(){\n\tExt.getCmp(\"132\" + this.idpadre).focus(true,200);\n}","resize":"","show":""}}', '{"module":"persona","component":"templates"}', '{"class":"DatDatosnacimientoModel","function":"","id":"", "project":""}');
INSERT INTO dat_proyectoconcepto (idproyectoconcepto, denominacion, idpadre, idproyecto, descripcion, tipo, propiedades, iconcls, orden, codigo, cmpempleado, getdata) VALUES (1203, 'Ocupación en tiempo de guerra', 67, 'basetecnologica', NULL, 1, '{"xtype":"gest_panel","animCollapse":"false","autoHeight":"false","border":"true","collapsed":"false","collapsible":"false","disabled":"false","frame":"false","hidden":"false","split":"false","elementsByRow":5,"height":"","anchocolumna":"","anchor":"","cmargins":"","collapseMode":"","html":"","layout":"","margins":"","region":"","title":"Ocupación en tiempo de guerra","width":"auto"}', 'tag', 5, '{"columns":"[\n  {header: \"Entidad\", width: 180, sortable: true, dataIndex: \"entidad\"},\n  {header: \"Cargo\", width: 180, sortable: true, dataIndex: \"cargo\"}, \n  {header: \"Principal\", width: 60, sortable: true, dataIndex: \"oficial\", renderer: function (val)\n   {\n     if (val == true) {\n       return \"<center class=''checked'' style=''width: 16px; height: 16px;''></center>\";\n     }\n     return '''';\n   }},\n  {header: \"Desde\", width: 100, sortable: true, dataIndex: \"fdesde\"},\n  {header: \"Hasta\", width: 100, sortable: true, dataIndex: \"fhasta\"},\n  {header: \"Hist&oacute;rico\", hidden: true, sortable: true, dataIndex: \"historico\", renderer: function (v)\n   {\n     return (v == 1) ? ''Actual'' : ''Hist&oacute;rico'';\n   }}\n]","addBotones":"","adicionarHandler":"","aplicarHandler":"function ()\n{\n    var values = this.fpFormulario.getForm().getValues();   \n\t\n  \tvalues.oficial = values.oficial == \"on\" ? true : false;\n  \n    values.historico = isActual(values.fdesde, values.fhasta);\n\n    var store = this.gpGrid.getStore();\n\n    var index = -1;\n\t\n    if (Ext.isEmpty(values.idocupaciontiempoguerra)) {//Si es vacio es porke estoy adicionando\n        values.idocupaciontiempoguerra = Ext.id();\n        values.add = true;\n        if (values.historico != 0) { //El checkeo eso solo si la direccion es actual\n            Ext.each(store.getRange(), function (rec)\n            {\n                if (rec.get(''oficial'') == true && values.oficial != false && rec.get(''historico'') == 1) {\n                    index = ''oficial'';\n                    return false;\n                }\n            });\n        }\n        switch (index) {\n            case ''oficial'':\n                Ext.Notification.show({\n                    title: ''Error'',\n                    msg: ''La persona ya tiene un cargo actual como oficial.'',\n                    icon: ''error''\n                });\n                break;\n            default :\n                try {\n                    store.add(new Ext.data.Record(values));\n                    this.cleanForm();\n                } catch (error) {\n                    Ext.Notification.show({\n                        title: ''Error'',\n                        msg: ''Ha ocurrido un error mientras se guardaba, contacte el administrador.'',\n                        icon: ''error''\n                    });\n                }\n                break;\n        }\n    }\n    store.clearGrouping();\n    store.groupBy(''historico'', true);\n\n    function isActual(fi, ff)\n    {\n        if (!Ext.isEmpty(ff)) {//Si la fecha fin es ditinto de vacio\n            var date = new Date();\n            date = date.format(''d/m/Y'');\n            var arrfi = fi.split(''/'');\n            var arrff = ff.split(''/'');\n            var arrfa = date.split(''/'');\n            var fi = arrfi[2] + arrfi[1] + arrfi[0];\n            var ff = arrff[2] + arrff[1] + arrff[0];\n            var fa = arrfa[2] + arrfa[1] + arrfa[0];\n            fi = parseInt(fi);\n            ff = parseInt(ff);\n            fa = parseInt(fa);\n            return (fi <= fa && fa <= ff) ? 1 : 0;\n            //1->Actual  0->Historico\n        }\n        return 1;\n    }\n}","eliminarHandler":"function(){\n  \tvar records = this.gpGrid.getSelectionModel().getSelections();\n  \tvar ask = (records.length == 1) ? ''¿Está seguro que quiere eliminar el cargo seleccionado?'' : \n    ''¿Está seguro que quiere eliminar los cargos seleccionados?'';\n  \n\tmostrarMensaje(2, ask, function (btn)\n        {\n            if (btn == ''ok'') {\n\n                var records = this.gpGrid.getSelectionModel().getSelections();\n                Ext.each(records, function (rec)\n                {\n                    if (!rec.data.add) {\n                        this.arrDel.push(rec.get(''idocupaciontiempoguerra''));\n                    }\n                    this.gpGrid.getStore().remove(rec);\n                }, this);\n                this.gpGrid.getView().refresh();\n            }\n        }.createDelegate(this));\n}","gSecurity":"","getLanguaje":"","guardarHandler":"function ()\n{\n    var values = this.fpFormulario.getForm().getValues();\n\n    values.oficial = values.oficial == \"on\" ? true : false;\n\n\n    values.historico = isActual(values.fdesde, values.fhasta);\n\n    var store = this.gpGrid.getStore();\n\n    var index = -1;\n\n    if (Ext.isEmpty(values.idocupaciontiempoguerra)) {//Si es vacio es porke estoy adicionando\n        values.idocupaciontiempoguerra = Ext.id();\n        values.add = true;\n        if (values.historico != 0) { //El checkeo eso solo si la direccion es actual\n            Ext.each(store.getRange(), function (rec)\n            {\n                if (rec.get(''oficial'') == true && values.oficial != false && rec.get(''historico'') == 1) {\n                    index = ''oficial'';\n                    return false;\n                }\n            });\n        }\n        switch (index) {\n            case ''oficial'':\n                Ext.Notification.show({\n                    title: ''Error'',\n                    msg: ''La persona ya tiene un cargo actual como oficial.'',\n                    icon: ''error''\n                });\n                break;\n            default :\n                try {\n                    store.add(new Ext.data.Record(values));\n                    this.cancelarHandler();\n                } catch (error) {\n                    Ext.Notification.show({\n                        title: ''Error'',\n                        msg: ''Ha ocurrido un error mientras se guardaba, contacte el administrador.'',\n                        icon: ''error''\n                    });\n                }\n                break;\n        }\n    } else {\n        var record;\n        //Iteracion para validar la modificacion y obtener el record a modificar\n        Ext.each(store.getRange(), function (rec)\n        {\n            if (rec.get(''idocupaciontiempoguerra'') != values.idocupaciontiempoguerra) { //Si no es el que se va a modificar\n                if (values.historico != 0) {//El checkeo eso solo si la direccion es actual\n                    if (rec.get(''oficial'') == true && values.oficial != false\n                        && rec.get(''historico'') == 1) {\n                        index = ''oficial'';\n                        return false;\n                    }\n                }\n            } else {\n                record = rec; //Obtengo el record que se va a modificar\n            }\n        });\n        switch (index) {\n            case ''oficial'':\n                Ext.Notification.show({\n                    title: ''Error'',\n                    msg: ''La persona ya tiene cargo actual como oficial.'',\n                    icon: ''error''\n                });\n                break;\n            default :\n                try {\n                    for (var p in values) {\n                        if (values[p] != record.get(p)) {\n                            record.set(p, values[p]);\n                        }\n                    }\n                    this.cancelarHandler();\n                } catch (error) {\n                    Ext.Notification.show({\n                        title: ''Error'',\n                        msg: ''Ha ocurrido un error mientras se modificaba, contacte el administrador.'',\n                        icon: ''error''\n                    });\n                }\n                break;\n        }\n    }\n    store.clearGrouping();\n    store.groupBy(''historico'', true);\n\n    function isActual(fi, ff)\n    {\n        if (!Ext.isEmpty(ff)) {//Si la fecha fin es ditinto de vacio\n            var date = new Date();\n            date = date.format(''d/m/Y'');\n            var arrfi = fi.split(''/'');\n            var arrff = ff.split(''/'');\n            var arrfa = date.split(''/'');\n            var fi = arrfi[2] + arrfi[1] + arrfi[0];\n            var ff = arrff[2] + arrff[1] + arrff[0];\n            var fa = arrfa[2] + arrfa[1] + arrfa[0];\n            fi = parseInt(fi);\n            ff = parseInt(ff);\n            fa = parseInt(fa);\n            return (fi <= fa && fa <= ff) ? 1 : 0;\n            //1->Actual  0->Historico\n        }\n        return 1;\n    }\n}","helpHandler":"","isDirty":"","loadFn":"function(idpersona){\n  this.arrAdd = [];\n  this.arrMod = [];\n  this.arrDel = [];\n  this.loadGridStore({idpersona: idpersona});\n}","modificarHandler":"","saveFn":"function (btnPress)\n{\n    var self = this;\n    var store = this.gpGrid.getStore();\n    this.arrAdd = [];\n    this.arrMod = [];\n    var pass = false;\n    Ext.each(store.getRange(), function (rec)\n    {\n        if (rec.data.add) {//Si es un record que se adiciono nuevo\n            this.arrAdd.push(rec.data);\n        } else {\n            if (!Ext.isEmpty(rec.modified)) {//Si el record fue modificado\n                this.arrMod.push(rec.data);\n            }\n        }\n        if (rec.get(''historico'') == 1 && rec.get(''oficial'') == true && !pass) {\n            pass = true;\n        }\n    }, this);\n    if (!pass && this.obligatorio) {\n        Ext.Notification.show({\n            title: ''Advertencia'',\n            msg: ''La persona debe tener un cargo actual como oficial'',\n            icon: ''warning''\n        });\n        return false;\n    }\n    var url = '''';\n    if (this.arrMod.length > 0 || (this.arrDel.length > 0 && this.arrAdd.length > 0)) {\n        url = ''modCargosGuerra'';\n    } else\n        if (this.arrDel.length > 0) {\n            url = ''delCargosGuerra'';\n        } else {\n            url = ''addCargosGuerra'';\n        }\n    if (this.arrAdd.length > 0 || this.arrMod.length > 0 || this.arrDel.length > 0) {\n        Ext.sendAjax.request({\n            url: url,\n            params: {\n                arrAdd: Ext.encode(self.arrAdd),\n                arrMod: Ext.encode(self.arrMod),\n                arrDel: Ext.encode(self.arrDel)\n            },\n            success: function (response, opt, notification)\n            {\n                var dataResponse = Ext.decode(response.responseText);\n                if (dataResponse.success) {\n                  //console.info(dataResponse.success);\n                    if (btnPress === ''APLICAR'') { //Si el boton que ejecuto la funcion fue aplicar\n                        this.loadFn(Ext.getCmp(this.idpadre).persona.idpersona);\n                    }\n                    this.arrAdd = [];\n                    this.arrMod = [];\n                    this.arrDel = [];\n                    var msg = '''';\n                    switch (url) {\n                        case ''modCargosGuerra'':\n                            msg = ''Lo(s) cargo(s) se ha(n) modificado satisfactoriamente.'';\n                            break;\n                        case ''delCargosGuerra'':\n                            msg = ''Lo(s) cargo(s) se ha(n) eliminado satisfactoriamente.'';\n                            break;\n                        case ''addCargosGuerra'':\n                            msg = ''Lo(s) cargo(s) se ha(n) adicionado satisfactoriamente.'';\n                            break\n                    }\n                    notification({\n                        title: ''Informaci&oacute;n'',\n                        msg: msg,\n                        icon: ''ok''\n                    });\n                } else {\n                    switch (dataResponse.codigo) {\n                        default :\n                            notification({\n                                title: ''Error'',\n                                msg: ''Ha ocurrido un error durante la transaccion.'',\n                                icon: ''error''\n                            });\n                            break;\n                    }\n                }\n            }.createDelegate(this)\n        }, this);\n    }\n}","validateForm":"","bbar":"","ptbar":"","sm":"{\n  type: \"RowSelectionModel\",\n  singleSelect: false\n}","store":"{\n  url: \"getCargosGuerra\",\n    type: \"GroupingStore\",\n      reader: {\n        type: \"JsonReader\",\n          totalProperty: \"quantity\",\n            root: \"data\"\n      },\n        mapping: [\n          {name: \"idocupaciontiempoguerra\"},\n          {name: \"entidad\"},\n          {name: \"cargo\"},\n          {name: \"fdesde\"},\n          {name: \"fhasta\"},     \n          {name: \"oficial\"},\n          {name: \"historico\"}\n        ],\n          sortInfo: {field: ''fhasta'', direction: \"ASC\"},\n            groupField: ''historico''\n}","view":"{\n  type: ''GroupingView'',\n    startCollapsed: false,\n      groupTextTpl: ''{group} ({[values.rs.length]} {[values.rs.length > 1 ? \"Cargos\" : \"Cargo\"]})''\n}","viewConfig":"","listeners":{"beforeload":"","expand":"","focus":"","load":"","render":"","resize":"","selectionchange":"","show":""}}', '{"module":"persona","component":"templates"}', NULL);
INSERT INTO dat_proyectoconcepto (idproyectoconcepto, denominacion, idpadre, idproyecto, descripcion, tipo, propiedades, iconcls, orden, codigo, cmpempleado, getdata) VALUES (1327, 'Ocupación actual', 67, 'basetecnologica', NULL, 1, '{"xtype":"gest_panel","animCollapse":"false","autoHeight":"false","border":"true","collapsed":"false","collapsible":"false","disabled":"false","frame":"false","hidden":"false","split":"false","elementsByRow":5,"height":"","anchocolumna":"","anchor":"","cmargins":"","collapseMode":"","html":"","layout":"","margins":"","region":"","title":"Ocupación actual","width":"auto"}', 'tag', 6, '{"columns":"[\n  {header: \"Entidad\", width: 350,hidden: true,sortable: true, dataIndex: \"entidad\"},\n  {header: \"Área\", width: 350,sortable: true, dataIndex: \"denomarea\"},\n  {header: \"Cargo\", width: 250,sortable: true, dataIndex: \"denomcargo\"},\n  {header: \"Situación laboral\", width: 150, sortable: true, dataIndex: \"situacionlaboral\"},\n  {header: \"Principal\", width: 60, sortable: true, dataIndex: \"principal\", renderer: function (val, metadata)\n   {\n     if (val == true) {\n       return \"<center class=''checked'' style=''width: 16px; height: 16px;''></center>\";\n     }\n     return '''';\n   }},\n  {header: \"Desde\", width: 100, sortable: true, dataIndex: \"fdesde\"},\n  {header: \"Hasta\", width: 100, sortable: true, dataIndex: \"fhasta\"},\n  {header: \"Hist&oacute;rico\", hidden: true, sortable: true, dataIndex: \"historico\", renderer: function (v)\n   {\n     if(isNaN(v)){\n     return ''Nuevo'';\n   }else{\n    return (v == 1) ? ''Actual'' : ''Hist&oacute;rico'';\n   }\n   }}\n]","addBotones":"","adicionarHandler":"","aplicarHandler":"function ()\n{\n    var values = this.fpFormulario.getForm().getValues();  \n\n    values.principal = values.principal == \"on\" ? true : false;\n\n    var store = this.gpGrid.getStore();\n\n    var index = -1;\n\n    if (Ext.isEmpty(values.idsituacionlaboralp)) {\n        values.idsituacionlaboralp = Ext.id();\n        values.add = true;\n        Ext.each(store.getRange(), function (rec)\n        {\n            if (rec.get(''principal'') == true && values.principal != false) {\n                index = ''principal'';\n                return false;\n            }\n          if (rec.get(''idcargo'') == values.idcargo) {\n                index = ''cargo'';\n                return false;\n            }\n        });\n\n        switch (index) {\n            case ''principal'':\n               \n            \tExt.Notification.show({\n                       title: ''Error'',\n                  msg: ''La persona posee registrado un cargo como principal.'',\n                  icon: ''error''\n                    });\n                break;\n            case ''cargo'':\n              \n            Ext.Notification.show({\n                      title: ''Error'',\n                  msg: ''El cargo que quiere adicionar ya existe.'',\n                  icon: ''error''\n                    });\n                break;            \n            default :\n                try {\n                    store.add(new Ext.data.Record(values));\n                    this.cleanForm();\n                } catch (error) {\n                  \n                   Ext.Notification.show({\n                     title: ''Error'',\n                      msg: ''Ha ocurrido un error mientras se guardaba, contacte el administrador.'',\n                      icon: ''error''\n                    });\n                 \n                }\n                break;\n        }\n    }\n}","eliminarHandler":"function ()\n{\n   var records = this.gpGrid.getSelectionModel().getSelections();\n    var ask = (records.length == 1) ? ''¿Está seguro que quiere eliminar el cargo seleccionado?'' : \n    ''¿Está seguro que quiere eliminar los cargos seleccionados?'';\n     \n\tmostrarMensaje(2, ask, function (btn)\n        {\n            if (btn == ''ok'') {\n               \n                Ext.each(records, function (rec)\n                {\n                    if (!rec.data.add) {\n                        this.arrDel.push(rec.get(''idsituacionlaboralp''));\n                    }\n                    this.gpGrid.getStore().remove(rec);\n                }, this);\n\n                this.gpGrid.getView().refresh();\n            }\n        }.createDelegate(this));\n}","gSecurity":"","getLanguaje":"function(idioma){\n  var lang={};\n if(idioma===''es''){\n     lang ={\n        ttBtnAdd:\"Adicionar cargo\",\n        ttBtnMod:\"Modificar cargo\",\n        ttBtnDel:\"Eliminar cargo\",\n        ttBtnSave:\"Guardar datos y cerrar formulario\",\n        ttBtnApl:\"Guardar datos y limpiar los campos\",\n        ttBtnCancel:\"Cerrar formulario sin guardar los datos\"      \n\n      }  \t\n    }else{\n     lang = {\n        \n      }  \t\n      \n    }\n  return lang;\n\t\n}","guardarHandler":"function ()\n{\n    var values = this.fpFormulario.getForm().getValues();\n\n    values.principal = values.principal == \"on\" ? true : false;\n\n    var store = this.gpGrid.getStore();\n\n    var index = -1;\n\n    if (Ext.isEmpty(values.idsituacionlaboralp)) {\n        values.idsituacionlaboralp = Ext.id();\n        values.add = true;\n        Ext.each(store.getRange(), function (rec)\n        {\n            if (rec.get(''principal'') == true && values.principal != false) {\n                index = ''principal'';\n                return false;\n            }\n          \n          if (rec.get(''idcargo'') == values.idcargo) {\n                index = ''cargo'';\n                return false;\n            }\n        });\n\n        switch (index) {\n            case ''principal'':\n             \n            Ext.Notification.show({\n                      title: ''Error'',\n                      msg: ''La persona posee registrado un cargo como principal.'',\n                      icon: ''error''\n                    });\n        \n                break;\n            \n            case ''cargo'':\n                Ext.Notification.show({\n                    title: ''Error'',\n                    msg: ''El cargo que quiere adicionar ya existe.'',\n                    icon: ''error''\n                });\n                break;\n           \n            default :\n                try {\n                    store.add(new Ext.data.Record(values));\n                    this.cancelarHandler();\n                } catch (error) {\n                    \n                     Ext.Notification.show({\n                      title: ''Error'',\n                      msg: ''Ha ocurrido un error mientras se guardaba, contacte el administrador.'',\n                      icon: ''error''\n                    });\n                 \n                }\n                break;\n        }\n    } else {\n        var record;\n        Ext.each(store.getRange(), function (rec)\n        {\n            if (rec.get(''idsituacionlaboralp'') != values.idsituacionlaboralp) {\n                if (rec.get(''principal'') == true && values.principal != false) {\n                    index = ''principal'';\n                    return false;\n                }\n              if (rec.get(''idcargo'') == values.idcargo) {\n                    index = ''cargo'';\n                    return false;\n                }\n            } else {\n                record = rec;\n            }\n        });\n        switch (index) {\n            case ''principal'':              \t \n             Ext.Notification.show({\n                    title: ''Error'',\n                      msg: ''La persona posee registrado un cargo como principal.'',\n                      icon: ''error''\n                    });\n          \n                break;\n            \n            case ''cargo'':             \t \n              Ext.Notification.show({\n                    title: ''Error'',\n                      msg: ''El cargo ya existe.'',\n                      icon: ''error''\n                    });\n                break;\n            \n            default :\n                try {\n                    for (var p in values) {\n                        if (values[p] != record.get(p)) {\n                            record.set(p, values[p]);\n                        }\n                    }\n                    this.cancelarHandler();\n                } catch (error) {\n                    \n                    Ext.Notification.show({\n                    title: ''Error'',\n                      msg: ''Ha ocurrido un error mientras se modificaba, contacte el administrador.'',\n                      icon: ''error''\n                    });\n                }\n                break;\n        }\n    }\n}","helpHandler":"function()\n{\nvar title = ''Ayuda de Tipos de nodos'';\nvar referencia = ''RH/Registro/Clientes/principal'';\nhelp.show(title, referencia);\n}","isDirty":"","loadFn":"function(idpersona){\n  this.arrAdd = [];\n  this.arrMod = [];\n  this.arrDel = [];\n  this.loadGridStore({idpersona: idpersona});\n}","modificarHandler":"","saveFn":"function (btnPress)\n{\n  var store = this.gpGrid.getStore();\n  var self = this;\n  var pass = false;\n  this.arrAdd = [];\n  this.arrMod = [];\n  Ext.each(store.getRange(), function (rec)\n           {\n             if (rec.data.add) {//Si es un record que se adiciono nuevo\n               this.arrAdd.push(rec.data);\n             } else {\n               if (!Ext.isEmpty(rec.modified)) {//Si el record fue modificado\n                 this.arrMod.push(rec.data);\n               }\n             }\n             if (rec.get(''principal'') == true) {\n               pass = true;\n             }\n           }, this);\n  if (!pass && this.obligatorio) {\n      notification({\n        title: ''Error'',\n        msg: ''La persona debe tener un cargo como principal.'',\n        icon: ''error''\n      });  \n    return false;\n  }\n  var url = '''';\n  if (this.arrMod.length > 0) {\n    url = ''setAlta'';\n  } else\n    if (this.arrDel.length > 0) {\n      url = ''darBaja'';\n    } else {\n      url = ''darAlta'';\n    }\n  if (this.arrAdd.length > 0 || this.arrMod.length > 0 || this.arrDel.length > 0) {\n    Ext.sendAjax.request({\n      url: url,\n      params: {\n        arrAdd: Ext.encode(self.arrAdd),\n        arrMod: Ext.encode(self.arrMod),\n        arrDel: Ext.encode(self.arrDel)\n      },\n      success: function (response, opt, notification)\n      {\n        var dataResponse = Ext.decode(response.responseText);\n        if (dataResponse.success) {\n          if (btnPress === ''APLICAR'') { //Si el boton que ejecuto la funcion fue aplicar\n            this.loadFn(Ext.getCmp(this.idpadre).persona.idpersona);\n          }\n          this.arrAdd = [];\n          this.arrMod = [];\n          this.arrDel = [];\n          var msg;\n          switch (url) {\n            case ''setAlta'':\n              msg = ''El(Los) cargo(s) ha(n) sido modificado satisfactoriamente.'';\n              break;\n            case ''darBaja'':\n              msg = ''El(Los) cargo(s) ha(n) sido eliminado satisfactoriamente.'';\n              break;\n           \tcase ''darAlta'':\n              msg = ''El(Los) cargo(s) ha(n) sido adicionado(s) satisfactoriamente.'';\n              break\n          }         \n            notification({\n              title: ''Informaci&oacute;n'',\n              msg: msg,\n              icon: ''ok''\n          \t}); \n        } else {\n          switch (dataResponse.codigo) {\n            default :\n             notification({\n                title: ''Error'',\n                msg: ''H ocurrido un error durante la transacción.'',\n                icon: ''error''\n              });\n              break;\n          }\n        }\n      }.createDelegate(this)\n    }, this);\n  }\n}","validateForm":"","bbar":"","ptbar":"","sm":"{\n  type: \"CheckboxSelectionModel\",\n  singleSelect: false\n}","store":"{\n  url: \"getCargosByPersona\",\n    type: \"GroupingStore\",\n      reader: {\n        type: \"JsonReader\",\n          totalProperty: \"quantity\",\n            root: \"data\"\n      },\n        mapping: [\n          {name: \"idsituacionlaboralp\"},\n          {name: \"idpersona\"},\n          {name: \"denomcargo\"},\n          {name: \"idcargo\"},\n          {name: \"denomarea\"},\n          {name: \"idarea\"},\n          {name: \"entidad\"},\n          {name: \"identidad\"},\n          {name: \"idsituacion\"},\n          {name: \"situacionlaboral\"},\n          {name: \"fdesde\"},\n          {name: \"fhasta\"},\n          {name: \"principal\"},\n          {name: \"historico\"},\n        ],\n  sortInfo: {field: ''entidad'', direction: \"DESC\"},\n  groupField: ''entidad''\n}","view":"{\n  type: ''GroupingView'',\n    startCollapsed: false,\n      groupTextTpl: ''{group} ({[values.rs.length]} {[values.rs.length > 1 ? \"Cargos\" : \"Cargo\"]})''\n}","viewConfig":"","listeners":{"beforeload":"","expand":"","focus":"","load":"","render":"function(p){  \n\n p.btnCancelWin = new Ext.Button({     \n      iconCls: ''cancelar'',\n      text: ''Cancelar'',              \n      scope: p,\n      handler: function () {\n            p.winEstructura.hide();\n        }\n\n    });\n\n    p.btnAceptarWin = new Ext.Button({     \n      iconCls: ''aceptar'',\n      text: ''Aceptar'',\n      disabled:true,\n      scope: p,\n      handler: function () {\n        var node = p.pEstructura.tree.getSelectionModel().getSelectedNode();\n        var nodo = node.text.split(''<'');\n        var entidad = getEntidad(node);\n        var area = getArea(node);\n        Ext.getCmp(\"1329\" + this.idpadre).setRawValue(nodo[0]);\n        Ext.getCmp(\"1332\" + this.idpadre).setValue(node.id);\n        Ext.getCmp(\"1333\" + this.idpadre).setRawValue(entidad);\n        Ext.getCmp(\"1331\" + this.idpadre).setRawValue(area);\n        \n        p.winEstructura.hide();\n        }\n\n    });\n  \n  function getEntidad(node){\n    if(node.attributes.idconcepto == 3 || node.attributes.idconcepto == 2 || node.attributes.idconcepto == 4)\n      return node.attributes.text;\n    if(node.parentNode)\n      return getEntidad(node.parentNode);  \n    \n  } \n  \n  function getArea(node){    \n    if(node.attributes.idconcepto == 5 || node.attributes.idconcepto == 4)\n      return node.attributes.text;\n    if(node.parentNode)\n      return getArea(node.parentNode);  \n    \n  }\n  \n  \n    p.pEstructura= new Ext.estructura.panel.PanelEstructura({\n      title: ''Estructura'',\n      //inicial : perfil.idestructuracomun\n    });\n  \n  p.pEstructura.on(''dameseleccion'', function (obj, data) {\n    if(data.attributes.idconcepto == 7){\n      p.btnAceptarWin.enable();\n    }else{\n      p.btnAceptarWin.disable();\n    }\n        \n }.createDelegate(this));\n\n  \n\n    p.winEstructura = new Ext.Window({\n      title: ''Estructura'',\n      closeAction: ''hide'',\n      layout: ''fit'',\n      resizable: false,\n      modal: true,\n      items: [p.pEstructura],\n      buttons: [p.btnCancelWin, p.btnAceptarWin]\n    });\n\n}","resize":"","selectionchange":"","show":""}}', '{"module":"persona","component":"templates"}', NULL);
INSERT INTO dat_proyectoconcepto (idproyectoconcepto, denominacion, idpadre, idproyecto, descripcion, tipo, propiedades, iconcls, orden, codigo, cmpempleado, getdata) VALUES (884, 'Idiomas', 1066, 'basetecnologica', NULL, 1, '{"xtype":"gest_panel","animCollapse":"false","autoHeight":"false","border":"true","collapsed":"false","collapsible":"false","disabled":"false","frame":"false","hidden":"false","split":"false","elementsByRow":2,"height":"","anchocolumna":"","anchor":"","cmargins":"","collapseMode":"","html":"","layout":"","margins":"","region":"","title":"Idiomas","width":"auto"}', 'tag', 7, '{"columns":"[  \n  {header: \"Idioma\",\n   width: 180, \n   sortable: true,\n   resizable:false, \n   dataIndex: \"denomidioma\",\n   renderer: function (value, meta, record) {\n    \n     return \"<div class=''flags_img \" + record.get(''bandera'') + \"'' style=''width: 18px; height: 18px;''><p style=''margin-left: 30px; margin-top: 2px;''>\" + value + \"</p></div>\";\n   }\n  },\n  {header: \"Vía de aprendizaje\", width: 100, sortable: true,resizable:false, dataIndex: \"denomformaadquirir\"},\n  {header: \"Observaci&oacute;n\", width: 300, sortable: true,resizable:false, dataIndex: \"observacion\"},\n  \n]","addBotones":"","adicionarHandler":"","aplicarHandler":"function ()\n{\n    var values = this.fpFormulario.getForm().getValues();\n    values.denomidioma = Ext.getCmp(\"886\" + this.idpadre).getRawValue();\n    values.denomformaadquirir = Ext.getCmp(\"887\" + this.idpadre).getRawValue();\n    values.bandera = Ext.getCmp(\"886\" + this.idpadre).findRecord(\"ididioma\", values.ididioma).get(\"bandera\");\n\n    var store = this.gpGrid.getStore();\n    var index = -1;\n    if (Ext.isEmpty(values.ididiomap)) {//Si es vacio es porke estoy adicionando\n        values.ididiomap = Ext.id();\n        values.add = true;\n        Ext.each(store.getRange(), function (rec)\n        {\n            if (rec.get(''ididioma'') == values.ididioma) {\n                index = ''idioma'';\n                return false;\n            }\n        });\n        switch (index) {\n            case ''idioma'':\n                Ext.Notification.show({\n                    title: ''Error'',\n                    //msg: ''La persona ya sabe '' + values.denomidioma + ''</b>.'',\n                  \tmsg: ''El idioma que quiere adicionar ya existe.'',\n                    icon: ''error''\n                });\n                break\n            default:\n                try {\n                    store.add(new Ext.data.Record(values));\n                    this.cleanForm();  \n                } catch (error) {\n                    Ext.Notification.show({\n                        title: ''Error'',\n                        msg: ''Ha ocurrido un error mientras se guardaba, contacte el administrador.'',\n                        icon: ''error''\n                    });\n                }\n                break;\n        }\n    }\n}","eliminarHandler":"function ()\n{\n  var records = this.gpGrid.getSelectionModel().getSelections();\n   var ask = (records.length == 1) ? ''¿Está seguro que quiere eliminar el idioma seleccionado?'' : \n    ''¿Está seguro que quiere eliminar los idiomas seleccionados?'';\n\tmostrarMensaje(2, ask, function (btn)\n        {\n            if (btn == ''ok'') {\n              \n                Ext.each(records, function (rec)\n                {\n                    if (!rec.data.add) {\n                        this.arrDel.push(rec.get(''ididiomap''));\n                    }\n                    this.gpGrid.getStore().remove(rec);\n                }, this);\n\n                this.gpGrid.getView().refresh();\n            }\n        }.createDelegate(this));\n}","gSecurity":"","getLanguaje":"function(idioma){\n  var lang={};\n if(idioma===''es''){\n     lang ={\n        ttBtnAdd:\"Adicionar idioma\",\n        ttBtnMod:\"Modificar idioma\",\n        ttBtnDel:\"Eliminar idioma\",\n        ttBtnSave:\"Guardar datos y cerrar formulario\",\n        ttBtnApl:\"Guardar datos y limpiar los campos\",\n        ttBtnCancel:\"Cerrar formulario sin guardar los datos\"      \n\n      }  \t\n    }else{\n     lang = {\n        \n      }  \t\n      \n    }\n  return lang;\n\t\n}","guardarHandler":"function ()\n{\n    var values = this.fpFormulario.getForm().getValues();\n    values.denomidioma = Ext.getCmp(\"886\" + this.idpadre).getRawValue();\n    values.denomformaadquirir = Ext.getCmp(\"887\" + this.idpadre).getRawValue();\n    values.bandera = Ext.getCmp(\"886\" + this.idpadre).findRecord(\"ididioma\", values.ididioma).get(\"bandera\");\n\n    var store = this.gpGrid.getStore();\n    var index = -1;\n    if (Ext.isEmpty(values.ididiomap)) {//Si es vacio es porke estoy adicionando\n        values.ididiomap = Ext.id();\n        values.add = true;\n        Ext.each(store.getRange(), function (rec)\n        {\n            if (rec.get(''ididioma'') == values.ididioma) {\n                index = ''idioma'';\n                return false;\n            }\n        });\n        switch (index) {\n            case ''idioma'':\n                Ext.Notification.show({\n                    title: ''Error'',\n                    msg: ''El idioma que quiere adicionar ya existe.'',\n                    icon: ''error''\n                });\n                break\n            default:\n                try {\n                    store.add(new Ext.data.Record(values));\n                    this.cancelarHandler();\n                } catch (error) {\n                    Ext.Notification.show({\n                        title: ''Error'',\n                        msg: ''Ha ocurrido un error mientras se guardaba, contacte el administrador.'',\n                        icon: ''error''\n                    });\n                }\n                break;\n        }\n    } else {\n        var record;\n        //Iteracion para validar la modificacion y obtener el record a modificar\n        Ext.each(store.getRange(), function (rec, i)\n        {\n            if (rec.get(''ididiomap'') == values.ididiomap) { //Si  es el que se va a modificar\n                record = rec; //Obtengo el record que se va a modificar\n            } else\n                if (rec.get(''ididioma'') == values.ididioma) {\n                    index = ''ciudadadania'';\n                }\n        });\n        switch (index) {\n            case ''ciudadadania'':\n                Ext.Notification.show({\n                    title: ''Error'',\n                    msg: ''El idioma ya existe.'',\n                    icon: ''error''\n                });\n                break\n            default:\n                try {\n                    for (var p in values) {\n                        if (values[p] != record.get(p)) {\n                            record.set(p, values[p]);\n                        }\n                    }\n                    this.cancelarHandler();\n                } catch (error) {\n                    Ext.Notification.show({\n                        title: ''Error'',\n                        msg: ''Ha ocurrido un error mientras se modificaba, contacte el administrador.'',\n                        icon: ''error''\n                    });\n                }\n                break;\n        }\n    }\n}","helpHandler":"","isDirty":"","loadFn":"function (idpersona) {\n  this.arrAdd = [];\n  this.arrMod = [];\n  this.arrDel = [];\n  this.loadGridStore({idpersona: idpersona});\n}","modificarHandler":"","saveFn":" function (btnPress) {\n   var self = this;\n   var store = this.gpGrid.getStore();\n   var pass = false;\n   this.arrAdd = [];\n   this.arrMod = [];\n   Ext.each(store.getRange(), function (rec)\n            {\n              if (rec.data.add) {//Si es un record que se adiciono nuevo\n                this.arrAdd.push(rec.data);\n              } else {\n                if (!Ext.isEmpty(rec.modified)) {//Si el record fue modificado\n                  this.arrMod.push(rec.data);\n                }\n              }\n              pass = true;\n            }, this);\n   if (!pass && this.obligatorio) {\n     Ext.Notification.show({\n       title: ''Advertencia'',\n       msg: ''La persona debe tener alguna idioma registrada'',\n       icon: ''warning''\n     });\n     return false;\n   }\n   var url = '''';\n   if (this.arrMod.length > 0 || (this.arrDel.length > 0 && this.arrAdd.length > 0)) {\n     url = ''changeLanguages'';\n   } else\n     if (this.arrDel.length > 0) {\n       url = ''removeLanguages'';\n     } else {\n       url = ''addLanguages'';\n     }\n   if (this.arrAdd.length > 0 || this.arrMod.length > 0 || this.arrDel.length > 0) {\n     Ext.sendAjax.request({\n       url: url,\n       params: {\n         arrAdd: Ext.encode(self.arrAdd),\n         arrMod: Ext.encode(self.arrMod),\n         arrDel: Ext.encode(self.arrDel)\n       },\n       success: function (response, opt, notification)\n       {\n         var dataResponse = Ext.decode(response.responseText);\n         if (dataResponse.success) {\n           if (btnPress === ''APLICAR'') { //Si el boton que ejecuto la funcion fue aplicar\n             this.loadFn(Ext.getCmp(this.idpadre).persona.idpersona);\n           }\n           this.arrAdd = [];\n           this.arrMod = [];\n           this.arrDel = [];\n           var msg;\n           switch (url) {\n             case ''changeLanguages'':\n               msg = ''¨El(Los) idioma(s) ha(n) sido modificado(s) satisfactoriamente.'';\n               break;\n             case ''removeLanguages'':\n               msg = ''El(Los) idioma(s) ha(n) sido eliminado(s) satisfactoriamente.'';\n               break;\n             case ''addLanguages'':\n               msg = ''El(Los) idioma(s) ha(n) sido adicionado(s) satisfactoriamente.'';\n               break\n           }\n           notification({\n             title: ''Informaci&oacute;n'',\n             msg: msg,\n             icon: ''ok''\n           });\n         } else {\n           switch (dataResponse.codigo) {\n             case 23503:\n               notification({\n                 title: ''Error'',\n                 msg: ''No se puede eliminar debido a que est&aacute; en uso.'',\n                 icon: ''error''\n               });\n               break;\n             default :\n               notification({\n                 title: ''Error'',\n                 msg: ''Ha ocurrido un error durante la transaccion.'',\n                 icon: ''error''\n               });\n               break;\n           }\n         }\n       }.createDelegate(this)\n     }, this);\n   }\n }","validateForm":"function () {\n  if (this.fpFormulario.getForm().isValid()) {\n    return true;\n  } else {\n    return false;\n  }\n}","bbar":"","ptbar":"","sm":"{  type:''RowSelectionModel'',  singleSelect: false}","store":"{\n  url: \"getLanguageByIdperson\",\n    type: \"Store\",\n      reader: {\n        type: \"JsonReader\",\n          totalProperty: \"quantity\",\n            root: \"data\"\n      },\n        mapping: [\n          {name: \"ididiomap\"},\n          {name: \"ididioma\"},\n          {name: \"idformaadquiriridioma\"},\n          {name:\"observacion\"},\n          {name: \"denomidioma\"},\n          {name: \"denomformaadquirir\"},          \n          {name: \"bandera\"}\n        ]\n}","view":"","viewConfig":"","listeners":{"beforeload":"","expand":"","focus":"","load":"","render":"","resize":"","selectionchange":"","show":""}}', '{"module":"persona","component":"templates"}', '{"class":"DatIdiomaModel","function":"","id":"", "project":""}');
INSERT INTO dat_proyectoconcepto (idproyectoconcepto, denominacion, idpadre, idproyecto, descripcion, tipo, propiedades, iconcls, orden, codigo, cmpempleado, getdata) VALUES (68, 'Estudios concluidos', 1066, 'basetecnologica', NULL, 1, '{"xtype":"gest_panel","animCollapse":"false","autoHeight":"false","border":"true","collapsed":"false","collapsible":"false","disabled":"false","frame":"false","hidden":"false","split":"false","elementsByRow":4,"height":330,"anchocolumna":"","anchor":"","cmargins":"","collapseMode":"","html":"","layout":"","margins":"","region":"","title":"Estudios concluidos","width":"auto"}', 'icondistra-tag', 1, '{"columns":"[ \n  {header: \"Tipo de centro de estudio\", width: 200, sortable: true, dataIndex: \"tipocentroestudio\"},    \n  {header: \"Centro de estudio\", width: 200, sortable: true, dataIndex: \"denomcentroestudio\"},    \n  {header: \"Tipo de formación\", width: 200, sortable: true, dataIndex: \"denomtipoformacion\"},\n  {header: \"Forma de la preparación\", width: 200, sortable: true, dataIndex: \"denommodoformacion\"},\n  {header: \"Curso\", width: 150, sortable: true, dataIndex: \"curso\"},\n  {header: \"Desde\", width: 100, sortable: true, dataIndex: \"fdesde\"},\n  {header: \"Hasta\", width: 100, sortable: true, dataIndex: \"fhasta\"},\n  /*{header: \"Hist&oacute;rico\", hidden: true, sortable: true, dataIndex: \"historico\", renderer: function (v)\n   {\n     return (v == 1) ? ''Actual'' : ''Hist&oacute;rico'';\n   }}*/\n]","addBotones":"","adicionarHandler":"","aplicarHandler":"function(){\n  var values = this.fpFormulario.getForm().getValues();\n  \n  values.denomtipoformacion = Ext.getCmp(\"73\" + this.idpadre) ? Ext.getCmp(\"73\" + this.idpadre).getRawValue():'''';\n  \n  values.denommodoformacion = Ext.getCmp(\"71\" + this.idpadre) ? Ext.getCmp(\"71\" + this.idpadre).getRawValue():''''; \n\n  values.denomcentroestudio = Ext.getCmp(\"72\" + this.idpadre).getRawValue();  \n  \n  values.tipocentroestudio = Ext.getCmp(\"1405\" + this.idpadre).getRawValue();  \n  \n  values.curso = Ext.getCmp(\"74\" + this.idpadre).getRawValue();  \n  \n\n  var store = this.gpGrid.getStore();\n  var index = -1;\n  if (Ext.isEmpty(values.ideducacion)) {//Si es vacio es porke estoy adicionando\n    values.ideducacion = Ext.id();\n    values.add = true;\n    try {\n      store.add(new Ext.data.Record(values));\n      this.cleanForm();\n    } catch (error) {\n      Ext.Notification.show({\n        title: ''Error'',\n        msg: ''Ha ocurrido un error mientras se guardaba, contacte el administrador.'',\n        icon: ''error''\n      });\n    }\n  }\n  store.clearGrouping();\n  store.groupBy(''historico'', true);\n\n  function isActual(fi, ff)\n  {\n    if (!Ext.isEmpty(ff)) {//Si la fecha fin es ditinto de vacio\n      var date = new Date();\n      date = date.format(''d/m/Y'');\n      var arrfi = fi.split(''/'');\n      var arrff = ff.split(''/'');\n      var arrfa = date.split(''/'');\n      var fi = arrfi[2] + arrfi[1] + arrfi[0];\n      var ff = arrff[2] + arrff[1] + arrff[0];\n      var fa = arrfa[2] + arrfa[1] + arrfa[0];\n      fi = parseInt(fi);\n      ff = parseInt(ff);\n      fa = parseInt(fa);\n      return (fi <= fa && fa <= ff) ? 1 : 0;\n      //1->Actual  0->Historico\n    }\n    return 1;\n  }\n}","eliminarHandler":"function(){\n  var records = this.gpGrid.getSelectionModel().getSelections();\n   var ask = (records.length == 1) ? ''¿Está seguro que quiere eliminar el estudio seleccionado?'' : \n    ''¿Está seguro que quiere eliminar los estudios seleccionados?'';\n\tmostrarMensaje(2, ask, function (btn)\n                   {\n                     if (btn == ''ok'') {\n\n                       \n                       Ext.each(records, function (rec)\n                                {\n                                  if (!rec.data.add) {\n                                    this.arrDel.push(rec.get(''ideducacion''));\n                                  }\n                                  this.gpGrid.getStore().remove(rec);\n                                }, this);\n                       this.gpGrid.getView().refresh();\n                     }\n                   }.createDelegate(this));\n}","gSecurity":"","getLanguaje":"function(idioma){\n  var lang={};\n if(idioma===''es''){\n     lang ={\n        ttBtnAdd:\"Adicionar datos de estudio\",\n        ttBtnMod:\"Modificar datos de estudio\",\n        ttBtnDel:\"Eliminar datos de estudio\",\n        ttBtnSave:\"Guardar datos y cerrar formulario\",\n        ttBtnApl:\"Guardar datos y limpiar los campos\",\n        ttBtnCancel:\"Cerrar formulario sin guardar los datos\"      \n\n      }  \t\n    }else{\n     lang = {\n        \n      }  \t\n      \n    }\n  return lang;\n\t\n}","guardarHandler":"function(){\n  var values = this.fpFormulario.getForm().getValues();\n  \n  values.denomtipoformacion = Ext.getCmp(\"73\" + this.idpadre) ? Ext.getCmp(\"73\" + this.idpadre).getRawValue():'''';\n  \n  values.denommodoformacion = Ext.getCmp(\"71\" + this.idpadre) ? Ext.getCmp(\"71\" + this.idpadre).getRawValue():''''; \n  \n  values.denomcentroestudio = Ext.getCmp(\"72\" + this.idpadre).getRawValue();  \n  \n  values.tipocentroestudio = Ext.getCmp(\"1405\" + this.idpadre).getRawValue();\n   \n  values.curso = Ext.getCmp(\"74\" + this.idpadre).getRawValue();  \n\n  var store = this.gpGrid.getStore();\n  var index = -1;\n  if (Ext.isEmpty(values.ideducacion)) {//Si es vacio es porke estoy adicionando\n    values.ideducacion = Ext.id();\n    values.add = true;\n    try {\n      store.add(new Ext.data.Record(values));\n      this.cancelarHandler();\n    } catch (error) {\n      Ext.Notification.show({\n        title: ''Error'',\n        msg: ''Ha ocurrido un error mientras se guardaba, contacte el administrador.'',\n        icon: ''error''\n      });\n    }\n  }else {\n    var record;\n    //Iteracion para validar la modificacion y obtener el record a modificar\n    Ext.each(store.getRange(), function (rec)\n    {\n      if (rec.get(''ideducacion'') === values.ideducacion) {\n        record = rec; //Obtengo el record que se va a modificar\n        return false;\n      }\n    });\n    \n    try {\n      for (var p in values) {\n        if (values[p] != record.get(p)) {\n          record.set(p, values[p]);\n        }\n      }\n      this.cancelarHandler();\n    } catch (error) {\n      Ext.Notification.show({\n        title: ''Error'',\n        msg: ''Ha ocurrido un error mientras se modificaba, contacte el administrador.'',\n        icon: ''error''\n      });\n    }\n\n  }\n  store.clearGrouping();\n  store.groupBy(''historico'', true);\n\n  function isActual(fi, ff)\n  {\n    if (!Ext.isEmpty(ff)) {//Si la fecha fin es ditinto de vacio\n      var date = new Date();\n      date = date.format(''d/m/Y'');\n      var arrfi = fi.split(''/'');\n      var arrff = ff.split(''/'');\n      var arrfa = date.split(''/'');\n      var fi = arrfi[2] + arrfi[1] + arrfi[0];\n      var ff = arrff[2] + arrff[1] + arrff[0];\n      var fa = arrfa[2] + arrfa[1] + arrfa[0];\n      fi = parseInt(fi);\n      ff = parseInt(ff);\n      fa = parseInt(fa);\n      return (fi <= fa && fa <= ff) ? 1 : 0;\n      //1->Actual  0->Historico\n    }\n    return 1;\n  }\n}","helpHandler":"","isDirty":"","loadFn":"function(idpersona){\n  this.arrAdd = [];\n  this.arrMod = [];\n  this.arrDel = [];\n  this.loadGridStore({idpersona: idpersona});\n}","modificarHandler":"","saveFn":"function(btnPress){\n  var self = this;\n  var store = this.gpGrid.getStore();\n  this.arrAdd = [];\n  this.arrMod = [];\n  var pass = false;\n  Ext.each(store.getRange(), function (rec)\n           {\n             if (rec.data.add) {//Si es un record que se adiciono nuevo\n               this.arrAdd.push(rec.data);\n             } else {\n               if (!Ext.isEmpty(rec.modified)) {//Si el record fue modificado\n                 this.arrMod.push(rec.data);\n               }\n             }             \n               pass = true;\n           }, this);\n  if (!pass && this.obligatorio) {\n    Ext.Notification.show({\n      title: ''Advertencia'',\n      msg: ''El dato de estudio que quiere adicionar ya existe.'',\n      icon: ''warning''\n    });\n    return false;\n  }\n  var url = '''';\n  if (this.arrMod.length > 0 || (this.arrDel.length > 0 && this.arrAdd.length > 0)) {\n    url = ''modDatosEducacionales'';\n  } else\n    if (this.arrDel.length > 0) {\n      url = ''delDatosEducacionales'';\n    } else {\n      url = ''addDatosEducacionales'';\n    }\n  if (this.arrAdd.length > 0 || this.arrMod.length > 0 || this.arrDel.length > 0) {\n    Ext.sendAjax.request({\n      url: url,\n      params: {\n        arrAdd: Ext.encode(self.arrAdd),\n        arrMod: Ext.encode(self.arrMod),\n        arrDel: Ext.encode(self.arrDel)\n      },\n      success: function (response, opt, notification)\n      {\n        var dataResponse = Ext.decode(response.responseText);\n        if (dataResponse.success) {\n          if (btnPress === ''APLICAR'') { //Si el boton que ejecuto la funcion fue aplicar\n            this.loadFn(Ext.getCmp(this.idpadre).persona.idpersona);\n          }\n          this.arrAdd = [];\n          this.arrMod = [];\n          this.arrDel = [];\n          var msg = '''';\n          switch (url) {\n            case ''modDatosEducacionales'':\n              msg = ''El(Los) dato(s) de estudio(s) ha(n) sido modificado(s) satisfactoriamente.'';\n              break;\n            case ''delDatosEducacionales'':\n              msg = ''El(Los) dato(s) de estudio(s) ha(n) sido eliminado(s) satisfactoriamente.'';\n              break;\n            case ''addDatosEducacionales'':\n              msg = ''El(Los) dato(s) de estudio(s) ha(n) sido adicionado(s) satisfactoriamente.'';\n              break\n          }\n          notification({\n            title: ''Informaci&oacute;n'',\n            msg: msg,\n            icon: ''ok''\n          });\n        } else {\n          switch (dataResponse.codigo) {\n            default :\n              notification({\n                title: ''Error'',\n                msg: ''Ha ocurrido un error durante la transaccion.'',\n                icon: ''error''\n              });\n              break;\n          }\n        }\n      }.createDelegate(this)\n    }, this);\n  }\n}","validateForm":"","bbar":"","ptbar":"","sm":"{\n  type: \"RowSelectionModel\",\n  singleSelect: false\n}","store":"{\n  url: \"getDatosEducacionales\",\n    type: \"GroupingStore\",\n      reader: {\n        type: \"JsonReader\",\n          totalProperty: \"quantity\",\n            root: \"data\"\n      },\n        mapping: [\n          {name: \"ideducacion\"},\n          {name: \"idtipoformacion\"},\n          {name: \"denomtipoformacion\"},\n          {name: \"idmodoformacion\"},\n          {name: \"denommodoformacion\"},\n          {name: \"idtipocentroestudio\"},\n          {name: \"tipocentroestudio\"},\n          {name: \"idcentroestudio\"},\n          {name: \"denomcentroestudio\"},\n          {name: \"idcurso\"},\n          {name: \"curso\"},\n          {name: \"resultado\"},\n          {name: \"fdesde\"},\n          {name: \"fhasta\"},\n          {name: \"historico\"}\n        ],\n          sortInfo: {field: ''historico'', direction: \"DESC\"},\n            groupField: ''historico''\n}","view":"{\n  /*type: ''GroupingView'',\n    startCollapsed: false,\n      groupTextTpl: ''{group} ({[values.rs.length]} {[values.rs.length > 1 ? \"Registros\" : \"Registro\"]})''*/\n}","viewConfig":"","listeners":{"beforeload":"","expand":"","focus":"","load":"","render":"","resize":"","selectionchange":"","show":""}}', '{"module":"persona","component":"templates"}', NULL);
INSERT INTO dat_proyectoconcepto (idproyectoconcepto, denominacion, idpadre, idproyecto, descripcion, tipo, propiedades, iconcls, orden, codigo, cmpempleado, getdata) VALUES (1280, 'Nivel educacional', 1066, 'basetecnologica', NULL, 1, '{"xtype":"gest_panel","animCollapse":"false","autoHeight":"false","border":"true","collapsed":"false","collapsible":"false","disabled":"false","frame":"false","hidden":"false","split":"false","elementsByRow":2,"height":"","anchocolumna":"","anchor":"","cmargins":"","collapseMode":"","html":"","layout":"","margins":"","region":"","title":"Nivel educacional","width":"auto"}', 'tag', 2, '{"columns":"[\n  {header: \"Nivel educacional\", width: 300, sortable: true, dataIndex: \"niveleducacional\"},\n  {header: \"T&iacute;tulo\", width: 300, sortable: true, dataIndex: \"titulo\"},  \n  {header: \"Desde\", width: 200, sortable: true, dataIndex: \"fdesde\"}\n]","addBotones":"","adicionarHandler":"","aplicarHandler":"function ()\n{\n    var values = this.fpFormulario.getForm().getValues();\n\t//Obteniendo la denominacion del nivel educacional\n    values.niveleducacional = Ext.getCmp(\"1285\" + this.idpadre).getRawValue();\n    values.titulo = Ext.getCmp(\"1341\" + this.idpadre).getRawValue();\n\n\n    var store = this.gpGrid.getStore();\n\n    var index = -1;\n\n    if (Ext.isEmpty(values.idniveleducacionalp)) {\n        values.idniveleducacionalp = Ext.id();\n        values.add = true;\n        Ext.each(store.getRange(), function (rec)\n        {\n            if (rec.get(''idniveleducacionalp'') == values.idniveleducacionalp) {\n                index = ''nivel'';\n                return false;\n            }\n        });\n\n        switch (index) {\n            case ''nivel'':\n                Ext.Notification.show({\n                    title: ''Error'',\n                    msg: ''El nivel educacional que quiere adicionar ya existe.'',\n                    icon: ''error''\n                });\n                break;\n            default :\n                try {\n                    store.add(new Ext.data.Record(values));\n                    this.cleanForm();\n                } catch (error) {\n                    Ext.Notification.show({\n                        title: ''Error'',\n                        msg: ''Ha ocurrido un error mientras se guardaba, contacte el administrador.'',\n                        icon: ''error''\n                    });\n                }\n                break;\n        }\n    }\n}","eliminarHandler":"function ()\n{\n   var records = this.gpGrid.getSelectionModel().getSelections();\n   var ask = (records.length == 1) ? ''¿Está seguro que quiere eliminar el nivel educacional seleccionado?'' : \n    ''¿Está seguro que quiere eliminar los niveles educacionales seleccionados?'';\n\tmostrarMensaje(2, ask, function (btn)\n        {\n            if (btn == ''ok'') {                \n                Ext.each(records, function (rec)\n                {\n                    if (!rec.data.add) {\n                        this.arrDel.push(rec.get(''idniveleducacionalp''));\n                    }\n                    this.gpGrid.getStore().remove(rec);\n                }, this);\n\n                this.gpGrid.getView().refresh();\n            }\n        }.createDelegate(this));\n}","gSecurity":"","getLanguaje":"","guardarHandler":"function ()\n{\n    var values = this.fpFormulario.getForm().getValues();\n\t//Obteniendo la denominacion del tipo de categoria selecionada\n    values.niveleducacional = Ext.getCmp(\"1285\" + this.idpadre).getRawValue();\n    values.titulo = Ext.getCmp(\"1341\" + this.idpadre).getRawValue();\n  \n\n    var store = this.gpGrid.getStore();\n\n    var index = -1;\n\n    if (Ext.isEmpty(values.idniveleducacionalp)) {\n        values.idniveleducacionalp = Ext.id();\n        values.add = true;\n        Ext.each(store.getRange(), function (rec)\n        {\n            if (rec.get(''idniveleducacionalp'') == values.idniveleducacionalp) {\n                index = ''nivel'';\n                return false;\n            }\n        });\n\n        switch (index) {\n            case ''nivel'':\n                Ext.Notification.show({\n                    title: ''Error'',\n                    msg: ''El nivel educacional  que quiere adicionar ya existe.'',\n                    icon: ''error''\n                });\n                break;\n            default :\n                try {\n                    store.add(new Ext.data.Record(values));\n                    this.cancelarHandler();\n                } catch (error) {\n                    Ext.Notification.show({\n                        title: ''Error'',\n                        msg: ''Ha ocurrido un error mientras se guardaba, contacte el administrador.'',\n                        icon: ''error''\n                    });\n                }\n                break;\n        }\n    } else {\n        var record;\n        Ext.each(store.getRange(), function (rec)\n        {\n            if (rec.get(''idniveleducacionalp'') != values.idniveleducacionalp) {                \n                if (rec.get(''idniveleducacional'') == values.idniveleducacional) {\n                \tindex = ''nivel'';\n                \treturn false;\n            \t}\n            } else {\n                record = rec;\n            }\n        });\n        switch (index) {\n            case ''nivel'':\n                Ext.Notification.show({\n                    title: ''Error'',\n                    msg: ''El nivel educacional ya existe.'',\n                    icon: ''error''\n                });\n                break;\n            default :\n                try {\n                    for (var p in values) {\n                        if (values[p] != record.get(p)) {\n                            record.set(p, values[p]);\n                        }\n                    }\n                    this.cancelarHandler();\n                } catch (error) {\n                    Ext.Notification.show({\n                        title: ''Error'',\n                        msg: ''Ha ocurrido un error mientras se modificaba, contacte el administrador'',\n                        icon: ''error''\n                    });\n                }\n                break;\n        }\n    }\n}","helpHandler":"","isDirty":"","loadFn":"function (idpersona) {\n  this.arrAdd = [];\n  this.arrMod = [];\n  this.arrDel = [];\n  this.loadGridStore({idpersona: idpersona});\n}","modificarHandler":"","saveFn":"function (btnPress) {\n   var self = this;\n   var store = this.gpGrid.getStore();\n   var pass = false;\n   this.arrAdd = [];\n   this.arrMod = [];\n   Ext.each(store.getRange(), function (rec)\n            {\n              if (rec.data.add) {//Si es un record que se adiciono nuevo\n                this.arrAdd.push(rec.data);\n              } else {\n                if (!Ext.isEmpty(rec.modified)) {//Si el record fue modificado\n                  this.arrMod.push(rec.data);\n                }\n              }\n              pass = true;\n            }, this);\n   if (!pass && this.obligatorio) {\n     Ext.Notification.show({\n       title: ''Advertencia'',\n       msg: ''El nivel educacional que quiere adicionar ya existe.'',\n       icon: ''warning''\n     });\n     return false;\n   }\n   var url = '''';\n   if (this.arrMod.length > 0 || (this.arrDel.length > 0 && this.arrAdd.length > 0)) {\n     url = ''modNiveleducacional'';\n   } else\n     if (this.arrDel.length > 0) {\n       url = ''delNiveleducacional'';\n     } else {\n       url = ''addNiveleducacional'';\n     }\n   if (this.arrAdd.length > 0 || this.arrMod.length > 0 || this.arrDel.length > 0) {\n     Ext.sendAjax.request({\n       url: url,\n       params: {\n         arrAdd: Ext.encode(self.arrAdd),\n         arrMod: Ext.encode(self.arrMod),\n         arrDel: Ext.encode(self.arrDel)\n       },\n       success: function (response, opt, notification)\n       {\n         var dataResponse = Ext.decode(response.responseText);\n         if (dataResponse.success) {\n           if (btnPress === ''APLICAR'') { //Si el boton que ejecuto la funcion fue aplicar\n             this.loadFn(Ext.getCmp(this.idpadre).persona.idpersona);\n           }\n           this.arrAdd = [];\n           this.arrMod = [];\n           this.arrDel = [];\n           var msg;\n           switch (url) {\n             case ''modNiveleducacional'':\n               msg = ''El(Los) nivel(es) educacional(es) ha(n) sido modificado(s) satisfactoriamente.'';\n               break;\n             case ''delNiveleducacional'':\n               msg = ''El(Los) nivel(es) educacional(es) ha(n) sido eliminado(s) satisfactoriamente.'';\n               break;\n             case ''addNiveleducacional'':\n               msg = ''El(Los) nivel(es) educacional(es) ha(n) sido adicionado(s) satisfactoriamente.'';\n               break\n           }\n           notification({\n             title: ''Informaci&oacute;n'',\n             msg: msg,\n             icon: ''ok''\n           });\n         } else {\n           switch (dataResponse.codigo) {\n             case 23503:\n               notification({\n                 title: ''Error'',\n                 msg: ''No se puede eliminar debido a que est&aacute; en uso.'',\n                 icon: ''error''\n               });\n               break;\n             default :\n               notification({\n                 title: ''Error'',\n                 msg: ''Ha ocurrido un error durante la transaccion.'',\n                 icon: ''error''\n               });\n               break;\n           }\n         }\n       }.createDelegate(this)\n     }, this);\n   }\n }","validateForm":"","bbar":"","ptbar":"","sm":"{\n  type: \"RowSelectionModel\",\n  singleSelect: false\n}","store":"{\n  url: \"getNiveleducacional\",\n    type: \"Store\",\n      reader: {\n        type: \"JsonReader\",\n          totalProperty: \"quantity\",\n            root: \"data\"\n      },\n        mapping: [\n          {name: \"idniveleducacionalp\"},\n          {name: \"idniveleducacional\"},\n          {name: \"niveleducacional\"},\n          {name: \"fdesde\"},\n          {name: \"titulo\"},\n          {name: \"idtitulo\"}\n        ]\n}","view":"","viewConfig":"","listeners":{"beforeload":"","expand":"","focus":"","load":"","render":"","resize":"","selectionchange":"","show":""}}', '{"module":"persona","component":"templates"}', NULL);
