INSERT INTO dat_proyectoconcepto (idproyectoconcepto, denominacion, idpadre, idproyecto, descripcion, tipo, propiedades, iconcls, orden, codigo, cmpempleado, getdata) VALUES (61, 'Nombre', 60, 'basetecnologica', NULL, 3, '{"xtype":"twntrigger","allowBlank":"false","disabled":"false","hidden":"false","readOnly":"false","maxLength":50,"minLength":1,"anchocolumna":"","anchor":"100%","emptyText":"","fieldLabel":"Nombre","maxLengthText":"","minLengthText":"","name":"nombre","regex":"","trigger1Class":"x-form-clear-trigger","trigger2Class":"x-form-search-trigger","vtype":"nombrep"}', 'icondistra-tag_blue', 2, '{"onTrigger1Click":"","onTrigger2Click":"function () {\n  var buscadorSuin = Ext.getCmp(\"58\" + this.idpadre).buscadorSuin;\n  if(buscadorSuin){\n    buscadorSuin.show();\n  }\n}","listeners":{"focus":"","render":"function () {\n  this.triggers[0].hide();\n  //Verifica si emplea fuente de datos para el registro.\n  if(this.fdatos==1){\n    this.triggers[1].show();\n  }else{\n    this.triggers[1].hide();\n  }\n}"}}', '{"module":"comun","component":"utiles"}', NULL);
