INSERT INTO dat_proyectoconcepto (idproyectoconcepto, denominacion, idpadre, idproyecto, descripcion, tipo, propiedades, iconcls, orden, codigo, cmpempleado, getdata) VALUES (1406, 'Disposición', 1147, 'basetecnologica', NULL, 3, '{"xtype":"combo_box","allowBlank":"true","disabled":"false","editable":"true","forceSelection":"false","hidden":"false","readOnly":"false","resizable":"false","selectOnFocus":"false","typeAhead":"false","anchocolumna":"0.2","anchor":"100%","displayField":"denominacion","emptyText":"Seleccione...","fieldLabel":"Disposición","hiddenName":"iddisposicion","loadingText":"","mode":"local","name":"iddisposicion","toolTipTrigger1":"","toolTipTrigger2":"","triggerAction":"all","valueField":"iddisposicion"}', 'icondistra-tag_blue', 6, '{"handler":"","store":"{\n  url: \"obtenerDisposiciones\",\n  type: \"Store\",\n  baseParams: {\n    value: 1\n  },\n  reader: {\n    type: \"JsonReader\",\n    root: \"data\"\n  },\n  mapping: [\n    {name: ''iddisposicion''},\n    {name: ''denominacion''},\n    {name: ''descripcion''},\n  ],\n  autoLoad:true\n}","tpl":"","listeners":{"expand":"","focus":"","render":"","select":"function(comp){\n  if (!Ext.getCmp(\"1404\" + this.idpadre).checked) {\n     comp.reset();\n  }\n}"}}', '{"module":"persona","component":"templates"}', NULL);
INSERT INTO dat_proyectoconcepto (idproyectoconcepto, denominacion, idpadre, idproyecto, descripcion, tipo, propiedades, iconcls, orden, codigo, cmpempleado, getdata) VALUES (70, 'Sexo', 60, 'basetecnologica', NULL, 3, '{"xtype":"combo_box","allowBlank":"false","disabled":"false","editable":true,"forceSelection":"false","hidden":"false","readOnly":"true","resizable":"false","selectOnFocus":"false","typeAhead":"false","anchocolumna":"","anchor":"100%","displayField":"denomsexo","emptyText":"Seleccione...","fieldLabel":"Sexo","hiddenName":"sexo","loadingText":"","mode":"local","name":"sexo","toolTipTrigger1":"","toolTipTrigger2":"","triggerAction":"all","valueField":"sexo"}', 'icondistra-tag_blue', 11, '{"handler":"","store":"{\n  type: \"SimpleStore\",\n    fields: [\n      {name: \"sexo\"},\n      {name: \"denomsexo\"},\n      {name: \"css\"}\n    ],\n      data: [\n        [\"1\", \"Masculino\", \"male\"],\n        [\"0\", \"Femenino\", \"female\"]\n      ]\n}","tpl":"''<tpl for=\".\"><div ext:qtip=\"{denomsexo}\" class=\"x-combo-list-item\"><img width=\"16\" height=\"16\" src=\"../../../../views/images/persona/{css}.png\">  {denomsexo}</div></tpl>''","listeners":{"expand":"","focus":"","render":"","select":"function (cb)\n{\n  Ext.getCmp(\"59\" + this.idpadre).setSexoImgDefault.call(Ext.getCmp(\"59\" + this.idpadre),cb.getValue());\n}"}}', '{"module":"persona","component":"templates"}', NULL);
INSERT INTO dat_proyectoconcepto (idproyectoconcepto, denominacion, idpadre, idproyecto, descripcion, tipo, propiedades, iconcls, orden, codigo, cmpempleado, getdata) VALUES (1147, 'Datos Sociales', 57, 'basetecnologica', NULL, 1, '{"xtype":"form_panel","animCollapse":"false","autoHeight":"true","border":"true","collapsed":"false","collapsible":"false","disabled":"false","frame":"true","hidden":"false","split":"false","trackResetOnLoad":true,"elementsByRow":5,"height":"","anchocolumna":"","anchor":"","buttonAlign":"right","cmargins":"","collapseMode":"","html":"","labelAlign":"top","layout":"","margins":"","region":"","title":"Datos Sociales","width":"auto"}', 'icondistra-tag', 11, '{"gSecurity":"function() {\n  var respuesta = true;\n  if (Ext.isEmpty(this.getForm().getValues().idcaracteristicasocial)) {\n    if (parseInt(this.segAction[0]) === 1) {\n      respuesta = false;\n    }\n  } else {\n    if (parseInt(this.segAction[1]) === 1) {\n      respuesta = false;\n    }\n  }\n  if (respuesta) {\n    Ext.getCmp(\"1147\" + this.idpadre).getForm().reset();\n  }\n  return respuesta;\n}","helpHandler":"","isDirty":"","loadFn":"function(idpersona){\n  Ext.Ajax.request({\n    url: ''getDatosSociales'',\n    params: {idpersona: idpersona},\n    success: function (response, opt)\n    {\n      var dataResponse = Ext.decode(response.responseText);\n      if (dataResponse.data) {\n        this.getForm().loadRecord(new Ext.data.Record(dataResponse.data));\n        this.getForm().findField(''idestadocivil'').setRawValue(dataResponse.data.estadocivil);\n        this.getForm().findField(''idestratificacionsocial'').setRawValue(dataResponse.data.estratificaionsocial);\n        this.getForm().findField(''iddisposicion'').setRawValue(dataResponse.data.disposicion);\n        this.getForm().findField(''jubilado'').setValue(dataResponse.data.jubilado);\n      }\n    }.createDelegate(this)\n  });\n}","saveFn":"function(btnPress) {\n  if (Ext.getCmp(\"1147\" + this.idpadre).gSecurity()) {\n    return;\n  };\n  if (this.getForm().isValid() && this.getForm().isDirty()) {\n    var url = (Ext.isEmpty(this.getForm().getValues().idcaracteristicasocial)) ? ''addDatosSociales'' : ''modDatosSociales'';\n    var values = this.getForm().getValues();\n    values.jubilado = (Ext.getCmp(\"1404\" + this.idpadre).checked) ? 1 : 0;\n    Ext.sendAjax.request({\n      url: url,\n      params: values,\n      success: function (response, opt, notification)\n      {\n        var dataResponse = Ext.decode(response.responseText);\n        if (dataResponse.success) {\n          if (btnPress === ''APLICAR'') {\n            if (dataResponse.data) {\n              this.getForm().loadRecord(new Ext.data.Record(dataResponse.data));\n              this.getForm().findField(''idestadocivil'').setRawValue(dataResponse.data.estadocivil);\n              this.getForm().findField(''idestratificacionsocial'').setRawValue(dataResponse.data.estratificaionsocial);\n              this.getForm().findField(''iddisposicion'').setRawValue(dataResponse.data.disposicion);\n              this.getForm().findField(''jubilado'').setValue(dataResponse.data.jubilado);\n            }\n          }\n          var msg = '''';\n          switch (url) {\n            case ''addDatosSociales'':\n              msg = ''Los datos sociales han  sido adicionados satisfactoriamente.'';\n              break;\n            case ''modDatosSociales'':\n              msg = ''Los datos sociales se ha modificado satisfactoriamente.'';\n              break;\n          }\n          notification({\n            title: ''Informaci&oacute;n'',\n            msg: msg,\n            icon: ''ok''\n          });\n        } else {\n          switch (dataResponse.codigo) {\n            default :\n              notification({\n                title: ''Error'',\n                msg: ''Ha ocurrido un error durante la transaccion.'',\n                icon: ''error''\n              });\n              break;\n          }\n        }\n\n      }.createDelegate(this)\n    }, this);\n  }\n}","listeners":{"clientvalidation":"","expand":"","focus":"","render":"","resize":"","show":""}}', '{"module":"persona","component":"templates"}', '{"class":"DatCaracteristicasocialModel","function":"","id":"", "project":""}');
